import { SVG_SELECTOR } from 'src/infrastructure/constants';
import { hideSvgEditorLayer } from 'src/presentation/level/parsing/svgDomUtils';
import type { Level } from 'src/domain/level';

export function applyObstacleVisibility(obstaclesHost: ParentNode, level: Level): void {
  const container = obstaclesHost.querySelector(SVG_SELECTOR.OBSTACLES);
  if (container == null) {
    return;
  }

  for (const obstacle of level.obstacles) {
    if (!obstacle.consumed) {
      continue;
    }

    const element = container.querySelector(`#${CSS.escape(obstacle.svgGroupId)}`);
    if (element instanceof SVGGraphicsElement) {
      hideSvgEditorLayer(element);
    }
  }
}
