import { useCallback, useEffect, useMemo, useState } from 'react';
import type { CourierId } from 'src/domain/courier';
import { MAX_PLAYER_LIVES } from 'src/domain/constants';
import type { AppContext } from 'src/infrastructure/bootstrap';
import { createPlayfieldConfig } from 'src/presentation/level/layout/playfieldConfig';
import { useLevelProgress } from 'src/presentation/level/loop/useLevelProgress';
import { useLevelTick } from 'src/presentation/level/loop/useLevelTick';
import { useVerticalInput } from 'src/presentation/level/loop/useVerticalInput';
import { useLevelSession } from 'src/presentation/level/session/useLevelSession';
import { useViewportSize } from 'src/presentation/shared/hooks/useViewportSize';
import { PauseScreen } from 'src/presentation/screen/components/PauseScreen';
import { INITIAL_LEVEL_VIEW_STATE } from 'src/presentation/level/session/levelViewState';
import { LevelCanvas } from './LevelCanvas';
import { LevelScreenOverlay } from './LevelScreenOverlay';
import 'src/presentation/level/styles/levelScene.css';

type LevelViewProps = {
  levelId: string;
  app: AppContext;
  courierId: CourierId;
  onFinish?: () => void;
  onGameOver?: () => void;
  onQuit?: () => void;
};

export function LevelView({ levelId, app, courierId, onFinish, onGameOver, onQuit }: LevelViewProps) {
  const [isPaused, setIsPaused] = useState(false);
  const viewport = useViewportSize();
  const playfield = useMemo(
    () => createPlayfieldConfig(viewport.width, viewport.height),
    [viewport.width, viewport.height],
  );

  const { pack, level, setLevel, player, setPlayer, viewState, setViewState, onLevelParsed } =
    useLevelSession(app, levelId);
  const { getVerticalDirection, verticalDirection } = useVerticalInput();

  const onTickFrame = useCallback((deltaSeconds: number) => {
    setViewState((previous) => {
      if (previous.reachedFinish) {
        return previous;
      }
      return {
        ...previous,
        elapsedSeconds: previous.elapsedSeconds + deltaSeconds,
      };
    });
  }, [setViewState]);

  useLevelTick(level, player, setPlayer, getVerticalDirection, onTickFrame, isPaused);
  useLevelProgress(level, player, setViewState);

  useEffect(() => {
    if (viewState.reachedFinish) {
      onFinish?.();
    }
  }, [onFinish, viewState.reachedFinish]);

  const playerLives = player?.lives;

  useEffect(() => {
    if (playerLives != null && playerLives <= 0) {
      onGameOver?.();
    }
  }, [onGameOver, playerLives]);

  const hud = useMemo(
    () => ({
      levelName: pack.name,
      elapsedSeconds: viewState.elapsedSeconds,
      routeEndS: level?.routeEndS ?? 0,
      worldS: player?.worldS ?? 0,
      collectiblesCollected: viewState.collectiblesCollected,
      collectiblesTotal: pack.collectiblesTotal,
      lives: player?.lives ?? MAX_PLAYER_LIVES,
    }),
    [
      pack.name,
      pack.collectiblesTotal,
      viewState.elapsedSeconds,
      viewState.collectiblesCollected,
      level?.routeEndS,
      player?.worldS,
      player?.lives,
    ],
  );

  const activeObstacleCount =
    level?.obstacles.filter((obstacle) => !obstacle.consumed).length ?? 0;

  const handlePause = useCallback(() => {
    setIsPaused(true);
  }, []);

  const handleContinue = useCallback(() => {
    setIsPaused(false);
  }, []);

  const handleRestart = useCallback(() => {
    if (level == null) {
      return;
    }

    const session = app.startLevel(level);
    setLevel(session.level);
    setPlayer(session.player);
    setViewState(INITIAL_LEVEL_VIEW_STATE);
    setIsPaused(false);
  }, [app, level, setLevel, setPlayer, setViewState]);

  const handleQuit = useCallback(() => {
    setIsPaused(false);
    onQuit?.();
  }, [onQuit]);

  return (
    <div className="level-scene">
      <LevelCanvas
        pack={pack}
        level={level}
        setLevel={setLevel}
        player={player}
        setPlayer={setPlayer}
        viewState={viewState}
        setViewState={setViewState}
        playfield={playfield}
        app={app}
        onLevelParsed={onLevelParsed}
        verticalDirection={verticalDirection}
        courierId={courierId}
      />
      <LevelScreenOverlay hud={hud} onPauseClick={handlePause} />
      {isPaused && (
        <PauseScreen
          onContinue={handleContinue}
          onRestart={handleRestart}
          onQuit={handleQuit}
        />
      )}
      {level != null && (
        <p className="level-scene__debug" aria-live="polite">
          {level.id} · route {Math.round(level.routeEndS)}m · obstacles {activeObstacleCount}
        </p>
      )}
    </div>
  );
}
