import { COURIER_IDS, type CourierId } from '../../domain';
import { useNavigate } from 'react-router-dom';
import { useAppStore } from '../store/appStore';
import { t } from '../../i18n';

export function CourierSelectScreen() {
  const navigate = useNavigate();
  const setSelectedCourier = useAppStore((s) => s.setSelectedCourier);

  const pick = (id: CourierId) => {
    void (async () => {
      await setSelectedCourier(id);
      navigate('/mission/swami/0', { replace: true });
    })();
  };

  return (
    <div style={{ padding: 24 }}>
      <h1>{t('shell.courier.title')}</h1>
      <p>{t('shell.courier.body')}</p>
      <ul>
        {COURIER_IDS.map((id) => (
          <li key={id}>
            <button type="button" onClick={() => pick(id)}>
              {id}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
