import type { CSSProperties, Ref } from 'react';
import type { SvgComponent } from 'src/infrastructure/levels/levelPack';
import type { LevelCanvasLayout } from 'src/presentation/level/layout/computeLevelLayout';
import { layoutToLayerStyle } from 'src/presentation/shared/layout/layoutToLayerStyle';

type LevelLayerProps = {
  component: SvgComponent;
  layout: LevelCanvasLayout;
  zIndex: number;
  pointerEvents?: CSSProperties['pointerEvents'];
  hostRef?: Ref<HTMLDivElement>;
};

export function LevelLayer({
  component: SvgComponent,
  layout,
  zIndex,
  pointerEvents = 'none',
  hostRef,
}: LevelLayerProps) {
  return (
    <div
      ref={hostRef}
      style={{
        ...layoutToLayerStyle(layout),
        pointerEvents,
        zIndex,
      }}
    >
      <SvgComponent
        width={layout.canvasWidthPx}
        height={layout.canvasHeightPx}
        style={{
          display: 'block',
          transform: `translateX(${layout.contentOffsetPx}px)`,
        }}
      />
    </div>
  );
}
