import { SVG_SELECTOR } from 'src/infrastructure/constants';
import { hideSvgEditorLayer } from 'src/presentation/level/parsing/svgDomUtils';
import type { Level } from 'src/domain/level';

export function applyBoosterVisibility(boostersHost: ParentNode, level: Level): void {
  const container = boostersHost.querySelector(SVG_SELECTOR.BOOSTERS);
  if (container == null) {
    return;
  }

  for (const booster of level.boosters) {
    if (!booster.consumed) {
      continue;
    }

    const element = container.querySelector(`#${CSS.escape(booster.svgGroupId)}`);
    if (element instanceof SVGGraphicsElement) {
      hideSvgEditorLayer(element);
    }
  }
}
