/** Подставляет текст в SVG `#id` или во все `<text>` внутри группы с этим id.
 *  Многострочный текст: разделяй строки через `\n` — каждая станет отдельным `<tspan>`.
 */
export function setSvgTextContent(host: ParentNode, selector: string, value: string): void {
  const el = host.querySelector(selector);
  if (el == null) {
    return;
  }

  const textElements =
    el instanceof SVGTextElement
      ? [el]
      : Array.from(el.querySelectorAll('text')).filter(
          (node): node is SVGTextElement => node instanceof SVGTextElement,
        );

  const lines = value.split('\n');

  for (const textEl of textElements) {
    const existingTspan = textEl.querySelector('tspan');
    const x = existingTspan?.getAttribute('x') ?? textEl.getAttribute('x') ?? '0';
    const baseY = Number(existingTspan?.getAttribute('y') ?? textEl.getAttribute('y') ?? 0);
    const fontSize = Number.parseFloat(textEl.getAttribute('font-size') ?? '40');
    const lineHeight = Number.isFinite(fontSize) ? fontSize * 1.2 : 48;

    while (textEl.firstChild) {
      textEl.removeChild(textEl.firstChild);
    }

    lines.forEach((line, index) => {
      const tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      tspan.setAttribute('x', x);
      tspan.setAttribute('y', String(baseY + index * lineHeight));
      tspan.textContent = line;
      textEl.appendChild(tspan);
    });
  }
}
