import { aabbFromCenter, aabbIntersects } from './collision';
import type { Booster, Level, ObstacleHitbox } from './level';
import type { Player } from './player';
import { computePlayerHitbox } from './playerHitbox';

function hitboxToAabb(hitbox: ObstacleHitbox) {
  return aabbFromCenter(
    hitbox.centerS,
    hitbox.centerLane,
    hitbox.widthS,
    hitbox.heightLane,
  );
}

export function detectBoosterCollisions(level: Level, player: Player): Booster[] {
  const playerBox = hitboxToAabb(computePlayerHitbox(level, player));
  const colliding: Booster[] = [];

  for (const booster of level.boosters) {
    if (booster.consumed) {
      continue;
    }
    if (aabbIntersects(playerBox, hitboxToAabb(booster.hitbox))) {
      colliding.push(booster);
    }
  }

  return colliding;
}
