import { hasPlayerReachedFinish } from '../../domain/levelRules';
import type { Level } from '../../domain/level';
import type { Player, VerticalMoveDirection } from '../../domain/player';
import { movePlayerForwardUseCase } from './playerMoveForwardUseCase';
import { movePlayerVerticalUseCase } from './playerMoveVerticalUseCase';
import { tickPlayerBoosterUseCase } from './tickPlayerBoosterUseCase';

export function tickLevelUseCase(
  level: Level,
  player: Player,
  verticalDirection: VerticalMoveDirection,
  deltaSeconds: number,
): Player {
  if (hasPlayerReachedFinish(level, player)) {
    return player;
  }

  const withBoosterTick = tickPlayerBoosterUseCase(player, deltaSeconds);
  const movedForward = movePlayerForwardUseCase(level, withBoosterTick, deltaSeconds);
  return movePlayerVerticalUseCase(movedForward, verticalDirection, deltaSeconds);
}
