import type { GiantId } from '../../domain';
import { MAP_SVG_GIANT_GROUP_ID } from './mapSvgGiantIds';

export const MAP_VIEWBOX = { width: 9960, height: 5662 } as const;

/** Ширина старого `mapWindowBackground.png`; совпадает с прежним масштабом карты на экране. */
export const MAP_LEGACY_DISPLAY_WIDTH = 1920;

/** Отображаемый масштаб карты относительно viewBox SVG. */
export const MAP_DISPLAY_SCALE = MAP_LEGACY_DISPLAY_WIDTH / MAP_VIEWBOX.width;

export function mapDisplaySize(
  viewBox: { width: number; height: number } = MAP_VIEWBOX,
  scale: number = MAP_DISPLAY_SCALE,
): { width: number; height: number } {
  return {
    width: viewBox.width * scale,
    height: viewBox.height * scale,
  };
}

export type MapGiantAnchor = { x: number; y: number };

function anchorFromRect(
  elRect: DOMRect,
  mapRect: DOMRect,
): MapGiantAnchor | null {
  if (mapRect.width <= 0 || mapRect.height <= 0) {
    return null;
  }
  if (elRect.width <= 0 && elRect.height <= 0) {
    return null;
  }
  return {
    x: (elRect.left + elRect.width / 2 - mapRect.left) / mapRect.width,
    y: (elRect.bottom - mapRect.top) / mapRect.height,
  };
}

/**
 * Якоря гигантов в долях контейнера карты (0–1) по фактической геометрии на экране.
 * Надёжнее `getBBox`, когда SVG масштабируется через CSS.
 */
export function parseMapGiantAnchorsFromLayout(
  svgRoot: SVGSVGElement | null | undefined,
  mapContainer: HTMLElement | null | undefined,
): Partial<Record<GiantId, MapGiantAnchor>> {
  if (svgRoot == null || mapContainer == null) {
    return {};
  }

  const mapRect = mapContainer.getBoundingClientRect();
  const giantsGroup = svgRoot.querySelector('#giants');
  if (giantsGroup == null) {
    return {};
  }

  const result: Partial<Record<GiantId, MapGiantAnchor>> = {};

  for (const [giantId, svgGroupId] of Object.entries(MAP_SVG_GIANT_GROUP_ID) as Array<
    [GiantId, string]
  >) {
    const el = giantsGroup.querySelector(`[id="${svgGroupId}"]`);
    if (el == null) {
      continue;
    }
    const anchor = anchorFromRect(el.getBoundingClientRect(), mapRect);
    if (anchor != null) {
      result[giantId] = anchor;
    }
  }

  return result;
}

/**
 * Центр по X и низ bbox гиганта в долях viewBox карты (0–1).
 * Используется в тестах и как запасной вариант без DOM-контейнера.
 */
export function parseMapGiantAnchors(
  svgRoot: SVGSVGElement | null | undefined,
  viewBox: { width: number; height: number } = MAP_VIEWBOX,
): Partial<Record<GiantId, MapGiantAnchor>> {
  if (svgRoot == null || viewBox.width <= 0 || viewBox.height <= 0) {
    return {};
  }

  const giantsGroup = svgRoot.querySelector('#giants');
  if (giantsGroup == null) {
    return {};
  }

  const result: Partial<Record<GiantId, MapGiantAnchor>> = {};

  for (const [giantId, svgGroupId] of Object.entries(MAP_SVG_GIANT_GROUP_ID) as Array<
    [GiantId, string]
  >) {
    const el = giantsGroup.querySelector(`[id="${svgGroupId}"]`);
    if (el == null || typeof (el as SVGGraphicsElement).getBBox !== 'function') {
      continue;
    }
    const bbox = (el as SVGGraphicsElement).getBBox();
    if (bbox.width <= 0 || bbox.height <= 0) {
      continue;
    }
    result[giantId] = {
      x: (bbox.x + bbox.width / 2) / viewBox.width,
      y: (bbox.y + bbox.height) / viewBox.height,
    };
  }

  return result;
}
