import { Link } from 'react-router-dom';
import { getGiantDisplayName, getGiantOrderText } from '../../content';
import { GIANT_IDS, GIANT_ORDER_COUNT, type GiantId } from '../../domain';
import { t } from '../../i18n';

function ordersForGiant(giantId: GiantId): number[] {
  const n = GIANT_ORDER_COUNT[giantId];
  return Array.from({ length: n }, (_, i) => i);
}

export function MissionCatalogScreen() {
  return (
    <div style={{ padding: 24, maxWidth: 560 }}>
      <h1>{t('shell.missions.title')}</h1>
      <p>{t('shell.missions.body')}</p>
      <p>
        <Link to="/game/map">{t('shell.missions.toMap')}</Link>
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {GIANT_IDS.map((giantId) => (
          <li key={giantId} style={{ marginBottom: 20 }}>
            <h2 style={{ fontSize: 18, margin: '0 0 8px' }}>{getGiantDisplayName(giantId)}</h2>
            <ul style={{ listStyle: 'none', padding: 0 }}>
              {ordersForGiant(giantId).map((orderIndex) => (
                <li key={orderIndex} style={{ marginBottom: 8 }}>
                  <Link to={`/mission/${giantId}/${orderIndex}`}>
                    {getGiantOrderText({ giantId, orderIndex })}
                  </Link>
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ul>
    </div>
  );
}
