import { INTERACTION_MARKER_IDS } from 'src/infrastructure/constants';

export function hideSvgEditorLayer(el: SVGGraphicsElement): void {
  el.setAttribute('fill', 'none');
  el.setAttribute('stroke', 'none');
  el.style.opacity = '0';
  el.style.pointerEvents = 'none';
}

export function hideInteractionMarkers(root: ParentNode): void {
  for (const id of INTERACTION_MARKER_IDS) {
    const el = root.querySelector(`#${id}`);
    if (el instanceof Element) {
      hideSvgEditorLayer(el as SVGGraphicsElement);
    }
  }
}

/** Скрывает editor-only элементы SVG после парсинга уровня. */
export function applyParsedLevelDomEffects(
  interactionsRoot: SVGSVGElement,
  _obstaclesRoot: SVGSVGElement,
): void {
  hideInteractionMarkers(interactionsRoot);
}
