import { useEffect, useMemo, useRef } from 'react';
import { Navigate, useNavigate, useParams } from 'react-router-dom';
import type { CSSProperties } from 'react';
import { findPoolEntryByGiant, isGiantId } from '../../domain';
import { getGiantDisplayName, getGiantOrder } from '../../content';
import { t } from '../../i18n';
import { useAppStore } from '../store/appStore';
import { tryGetMapDeliveryPoint } from './mapContent';
import { ReactComponent as DeliveryScreen } from '../../infrastructure/assets/Images/screenExamples/new_delivery_screen.svg';
import { applyDeliveryScreenSvg } from '../components/deliveryScreenSvg';
import {
  designRectStyle,
  designScreenHitLayerStyle,
  designScreenRootStyle,
  designScreenStageStyle,
} from '../designScreenFit';

/** Координаты из макета `new_delivery_screen.svg` (viewBox 1080×1920). */
const BACK_BTN = { x: 92, y: 1682, w: 173, h: 173 };
const TAKE_ORDER_BTN = { x: 296, y: 1682, w: 691, h: 173 };

const screenSvg: CSSProperties = {
  position: 'absolute',
  inset: 0,
  display: 'block',
  width: '100%',
  height: '100%',
};

const hitBtnBase: CSSProperties = {
  position: 'absolute',
  border: 'none',
  padding: 0,
  margin: 0,
  cursor: 'pointer',
  background: 'transparent',
};

export function GameOpenDeliveryScreen() {
  const screenRef = useRef<HTMLDivElement>(null);
  const { giantId: giantIdParam } = useParams();
  const navigate = useNavigate();
  const playerEconomy = useAppStore((s) => s.playerEconomy);

  const mapPoint =
    giantIdParam != null && giantIdParam !== '' && isGiantId(giantIdParam)
      ? tryGetMapDeliveryPoint(giantIdParam)
      : null;
  const poolEntry =
    mapPoint != null ? findPoolEntryByGiant(playerEconomy, mapPoint.giantId) : null;

  const labels = useMemo(() => {
    const base = {
      title: t('game.newDelivery.title'),
      whatInside: t('game.deliveries.whatInside'),
      takeOrder: t('game.openDelivery.takeOrder'),
    };

    if (poolEntry == null) {
      return {
        ...base,
        giantName: '—',
        description: t('game.deliveries.empty'),
      };
    }

    const order = getGiantOrder({ giantId: poolEntry.giantId, orderIndex: poolEntry.orderIndex });

    return {
      ...base,
      giantName: getGiantDisplayName(poolEntry.giantId),
      description: order.riddle,
    };
  }, [poolEntry]);

  const giantId = poolEntry?.giantId ?? null;

  useEffect(() => {
    const container = screenRef.current;
    if (container == null) {
      return;
    }

    let cancelled = false;

    const renderScreen = () => {
      if (!cancelled) {
        applyDeliveryScreenSvg(container, labels, giantId);
      }
    };

    if (document.fonts.status === 'loaded') {
      renderScreen();
    } else {
      void document.fonts.ready.then(renderScreen);
    }

    return () => {
      cancelled = true;
    };
  }, [giantId, labels]);

  if (mapPoint == null || poolEntry == null) {
    return <Navigate to="/game/map" replace />;
  }

  return (
    <div style={designScreenRootStyle()}>
      <div ref={screenRef} style={designScreenStageStyle()}>
        <DeliveryScreen
          style={screenSvg}
          preserveAspectRatio="xMidYMid meet"
          aria-label={labels.title}
        />
        <div style={designScreenHitLayerStyle()}>
          <button
            type="button"
            style={{ ...hitBtnBase, ...designRectStyle(BACK_BTN) }}
            aria-label={t('game.openDelivery.back')}
            onClick={() => navigate('/game/map')}
          />
          <button
            type="button"
            style={{ ...hitBtnBase, ...designRectStyle(TAKE_ORDER_BTN) }}
            aria-label={labels.takeOrder}
            onClick={() => navigate(`/game/character/${encodeURIComponent(poolEntry.giantId)}`)}
          />
        </div>
      </div>
    </div>
  );
}
