import type { Collectible } from 'src/domain/level';
import {
  COLLECTIBLE_SPRITE_SVG_HEIGHT,
  COLLECTIBLE_SPRITE_SVG_WIDTH,
} from 'src/domain/constants';
import { SVG_NAMESPACE, SVG_SELECTOR } from 'src/infrastructure/constants';
import {
  layerSpriteScale,
  parseSvgViewBox,
  type SvgViewBoxSize,
} from 'src/infrastructure/svgViewBox';

export function spawnCollectibleAssets(
  collectiblesRoot: ParentNode,
  collectibles: Collectible[],
  assetUrls: Record<string, string>,
  levelViewBox: SvgViewBoxSize,
): void {
  const container = collectiblesRoot.querySelector(SVG_SELECTOR.ROUTE_COLLECTIBLE);
  if (container == null) {
    return;
  }

  const scale =
    collectiblesRoot instanceof SVGSVGElement
      ? layerSpriteScale(parseSvgViewBox(collectiblesRoot), levelViewBox)
      : { scaleX: 1, scaleY: 1 };
  const spriteWidth = COLLECTIBLE_SPRITE_SVG_WIDTH * scale.scaleX;
  const spriteHeight = COLLECTIBLE_SPRITE_SVG_HEIGHT * scale.scaleY;

  for (const collectible of collectibles) {
    const placeholder = container.querySelector(`#${CSS.escape(collectible.svgGroupId)}`);
    if (!(placeholder instanceof SVGRectElement)) {
      continue;
    }

    const url = assetUrls[collectible.assetId];
    if (url == null) {
      console.warn(`[spawnCollectibleAssets] missing asset for id "${collectible.assetId}"`);
      continue;
    }

    const markerX = Number.parseFloat(placeholder.getAttribute('x') ?? '0');
    const markerY = Number.parseFloat(placeholder.getAttribute('y') ?? '0');
    const markerWidth = Number.parseFloat(placeholder.getAttribute('width') ?? '0');
    const markerHeight = Number.parseFloat(placeholder.getAttribute('height') ?? '0');
    const centerX = markerX + markerWidth / 2;
    const centerY = markerY + markerHeight / 2;

    const image = document.createElementNS(SVG_NAMESPACE, 'image');
    image.id = collectible.svgGroupId;
    image.setAttribute('href', url);
    image.setAttribute('x', String(centerX - spriteWidth / 2));
    image.setAttribute('y', String(centerY - spriteHeight / 2));
    image.setAttribute('width', String(spriteWidth));
    image.setAttribute('height', String(spriteHeight));
    image.setAttribute('preserveAspectRatio', 'xMidYMid meet');

    placeholder.replaceWith(image);
  }
}
