import type { Booster, BoosterKind, Collectible, Level, Obstacle, ObstacleHitbox } from '../domain/level';
import {
  COLLECTIBLE_SPRITE_SVG_HEIGHT,
  COLLECTIBLE_SPRITE_SVG_WIDTH,
  LANE_MAX,
  SHIELD_BOOSTER_SPRITE_SVG_HEIGHT,
  SHIELD_BOOSTER_SPRITE_SVG_WIDTH,
  SPEED_BOOSTER_SPRITE_SVG_HEIGHT,
  SPEED_BOOSTER_SPRITE_SVG_WIDTH,
  STATIC_OBSTACLE_SIZE_SCALE,
} from '../domain/constants';
import {
  BOOSTER_ASSET_IDS,
  OBSTACLE_ASSET_ID_PATTERN,
  SVG_NAMESPACE,
  SVG_SELECTOR,
} from './constants';
import {
  layerPointToLevel,
  layerSpriteScale,
  parseSvgViewBox,
  type LayerSpriteScale,
  type SvgViewBoxSize,
} from './svgViewBox';

function isSvgRect(el: Element | null): el is SVGRectElement {
  return el != null && el.namespaceURI === SVG_NAMESPACE && el.localName === 'rect';
}

function parseStartPointRect(el: SVGRectElement): {
  leftX: number;
  centerX: number;
  centerY: number;
} {
  const leftX = Number.parseFloat(el.getAttribute('x') ?? '0');
  const y = Number.parseFloat(el.getAttribute('y') ?? '0');
  const width = Number.parseFloat(el.getAttribute('width') ?? '0');
  const height = Number.parseFloat(el.getAttribute('height') ?? '0');
  return {
    leftX,
    centerX: leftX + width / 2,
    centerY: y + height / 2,
  };
}

function svgYToLane(y: number, viewBoxHeight: number): number {
  return LANE_MAX - y / viewBoxHeight;
}

function svgXToS(x: number, startPointSvgX: number): number {
  return x - startPointSvgX;
}

function parseInteractions(
  interactionsRoot: SVGSVGElement,
  viewBoxHeight: number,
): Pick<
  Level,
  'startPointSvgX' | 'spawnSvgX' | 'spawnSvgY' | 'startLane' | 'routeEndS'
> {
  const startEl = interactionsRoot.querySelector(SVG_SELECTOR.START_POINT);
  const finishEl = interactionsRoot.querySelector(SVG_SELECTOR.FINISH_POINT);
  if (!isSvgRect(startEl) || !isSvgRect(finishEl)) {
    throw new Error(
      `parseLevelSvg: ${SVG_SELECTOR.START_POINT} and ${SVG_SELECTOR.FINISH_POINT} must be SVG rect`,
    );
  }

  const start = parseStartPointRect(startEl);
  const finishLeftX = Number.parseFloat(finishEl.getAttribute('x') ?? '0');
  const routeEndS = finishLeftX - start.leftX;

  if (!Number.isFinite(routeEndS) || routeEndS <= 0) {
    throw new Error(`parseLevelSvg: invalid routeEndS (${routeEndS})`);
  }

  return {
    startPointSvgX: start.leftX,
    spawnSvgX: start.centerX,
    spawnSvgY: start.centerY,
    startLane: svgYToLane(start.centerY, viewBoxHeight),
    routeEndS,
  };
}

function resolveObstacleAssetId(rectId: string): string | null {
  const match = OBSTACLE_ASSET_ID_PATTERN.exec(rectId);
  return match?.[1] ?? null;
}

function isBoosterKind(assetId: string): assetId is BoosterKind {
  return (BOOSTER_ASSET_IDS as readonly string[]).includes(assetId);
}

function boosterSpriteSize(kind: BoosterKind): { width: number; height: number } {
  if (kind === 'shield') {
    return {
      width: SHIELD_BOOSTER_SPRITE_SVG_WIDTH,
      height: SHIELD_BOOSTER_SPRITE_SVG_HEIGHT,
    };
  }
  return {
    width: SPEED_BOOSTER_SPRITE_SVG_WIDTH,
    height: SPEED_BOOSTER_SPRITE_SVG_HEIGHT,
  };
}

function resolveLayerScale(
  layerRoot: ParentNode,
  levelViewBox: SvgViewBoxSize,
): LayerSpriteScale {
  if (!(layerRoot instanceof SVGSVGElement)) {
    return { scaleX: 1, scaleY: 1 };
  }
  return layerSpriteScale(parseSvgViewBox(layerRoot), levelViewBox);
}

function parseObstacleHitboxFromRect(
  rect: SVGRectElement,
  startPointSvgX: number,
  viewBoxHeight: number,
): ObstacleHitbox | null {
  const x = Number.parseFloat(rect.getAttribute('x') ?? '0');
  const y = Number.parseFloat(rect.getAttribute('y') ?? '0');
  const width = Number.parseFloat(rect.getAttribute('width') ?? '0');
  const height = Number.parseFloat(rect.getAttribute('height') ?? '0');

  if (width <= 0 || height <= 0) {
    return null;
  }

  const centerX = x + width / 2;
  const centerY = y + height / 2;

  return {
    centerS: svgXToS(centerX, startPointSvgX),
    centerLane: svgYToLane(centerY, viewBoxHeight),
    widthS: width,
    heightLane: height / viewBoxHeight,
  };
}

function parseObstacles(
  obstaclesRoot: ParentNode,
  startPointSvgX: number,
  viewBoxHeight: number,
): Obstacle[] {
  const container = obstaclesRoot.querySelector(SVG_SELECTOR.OBSTACLES);
  if (container == null) {
    return [];
  }

  const instances: Obstacle[] = [];

  for (const child of container.children) {
    if (!isSvgRect(child) || child.id.length === 0) {
      continue;
    }

    const assetId = resolveObstacleAssetId(child.id);
    if (assetId == null) {
      continue;
    }

    const hitbox = parseObstacleHitboxFromRect(child, startPointSvgX, viewBoxHeight);
    if (hitbox == null) {
      continue;
    }

    const scaledHitbox =
      assetId === 'static'
        ? {
            ...hitbox,
            widthS: hitbox.widthS * STATIC_OBSTACLE_SIZE_SCALE,
            heightLane: hitbox.heightLane * STATIC_OBSTACLE_SIZE_SCALE,
          }
        : hitbox;

    instances.push({
      id: `svg:${child.id}`,
      svgGroupId: child.id,
      assetId,
      anchorS: scaledHitbox.centerS,
      hitbox: scaledHitbox,
      consumed: false,
    });
  }

  return instances.sort((a, b) => a.hitbox.centerS - b.hitbox.centerS || a.id.localeCompare(b.id));
}

function parseCollectibleHitboxFromRect(
  rect: SVGRectElement,
  startPointSvgX: number,
  levelViewBox: SvgViewBoxSize,
  scale: LayerSpriteScale,
): ObstacleHitbox | null {
  const x = Number.parseFloat(rect.getAttribute('x') ?? '0');
  const y = Number.parseFloat(rect.getAttribute('y') ?? '0');
  const width = Number.parseFloat(rect.getAttribute('width') ?? '0');
  const height = Number.parseFloat(rect.getAttribute('height') ?? '0');

  if (width <= 0 || height <= 0) {
    return null;
  }

  const center = layerPointToLevel(x + width / 2, y + height / 2, scale);

  return {
    centerS: svgXToS(center.x, startPointSvgX),
    centerLane: svgYToLane(center.y, levelViewBox.height),
    widthS: COLLECTIBLE_SPRITE_SVG_WIDTH,
    heightLane: COLLECTIBLE_SPRITE_SVG_HEIGHT / levelViewBox.height,
  };
}

function parseCollectibles(
  collectiblesRoot: ParentNode,
  startPointSvgX: number,
  levelViewBox: SvgViewBoxSize,
): Collectible[] {
  const container = collectiblesRoot.querySelector(SVG_SELECTOR.ROUTE_COLLECTIBLE);
  if (container == null) {
    return [];
  }

  const scale = resolveLayerScale(collectiblesRoot, levelViewBox);
  const instances: Collectible[] = [];

  for (const child of container.children) {
    if (!isSvgRect(child) || child.id.length === 0) {
      continue;
    }

    const assetId = resolveObstacleAssetId(child.id);
    if (assetId == null) {
      continue;
    }

    const hitbox = parseCollectibleHitboxFromRect(
      child,
      startPointSvgX,
      levelViewBox,
      scale,
    );
    if (hitbox == null) {
      continue;
    }

    instances.push({
      id: `svg:${child.id}`,
      svgGroupId: child.id,
      assetId,
      anchorS: hitbox.centerS,
      hitbox,
      consumed: false,
    });
  }

  return instances.sort((a, b) => a.hitbox.centerS - b.hitbox.centerS || a.id.localeCompare(b.id));
}

function parseBoosterHitboxFromRect(
  rect: SVGRectElement,
  kind: BoosterKind,
  startPointSvgX: number,
  levelViewBox: SvgViewBoxSize,
  scale: LayerSpriteScale,
): ObstacleHitbox | null {
  const x = Number.parseFloat(rect.getAttribute('x') ?? '0');
  const y = Number.parseFloat(rect.getAttribute('y') ?? '0');
  const width = Number.parseFloat(rect.getAttribute('width') ?? '0');
  const height = Number.parseFloat(rect.getAttribute('height') ?? '0');

  if (width <= 0 || height <= 0) {
    return null;
  }

  const center = layerPointToLevel(x + width / 2, y + height / 2, scale);
  const sprite = boosterSpriteSize(kind);

  return {
    centerS: svgXToS(center.x, startPointSvgX),
    centerLane: svgYToLane(center.y, levelViewBox.height),
    widthS: sprite.width,
    heightLane: sprite.height / levelViewBox.height,
  };
}

function parseBoosters(
  boostersRoot: ParentNode,
  startPointSvgX: number,
  levelViewBox: SvgViewBoxSize,
): Booster[] {
  const container = boostersRoot.querySelector(SVG_SELECTOR.BOOSTERS);
  if (container == null) {
    return [];
  }

  const scale = resolveLayerScale(boostersRoot, levelViewBox);
  const instances: Booster[] = [];

  for (const child of container.children) {
    if (!isSvgRect(child) || child.id.length === 0) {
      continue;
    }

    const assetId = resolveObstacleAssetId(child.id);
    if (assetId == null || !isBoosterKind(assetId)) {
      continue;
    }

    const hitbox = parseBoosterHitboxFromRect(
      child,
      assetId,
      startPointSvgX,
      levelViewBox,
      scale,
    );
    if (hitbox == null) {
      continue;
    }

    instances.push({
      id: `svg:${child.id}`,
      svgGroupId: child.id,
      assetId,
      anchorS: hitbox.centerS,
      hitbox,
      consumed: false,
    });
  }

  return instances.sort((a, b) => a.hitbox.centerS - b.hitbox.centerS || a.id.localeCompare(b.id));
}

export function parseLevelSvg(
  levelId: string,
  interactionsRoot: SVGSVGElement,
  obstaclesRoot: SVGSVGElement,
  collectiblesRoot: SVGSVGElement = obstaclesRoot,
  boostersRoot: SVGSVGElement = obstaclesRoot,
): Level {
  const levelViewBox = parseSvgViewBox(interactionsRoot);
  const interactions = parseInteractions(interactionsRoot, levelViewBox.height);
  const obstacles = parseObstacles(
    obstaclesRoot,
    interactions.startPointSvgX,
    levelViewBox.height,
  );
  const collectibles = parseCollectibles(
    collectiblesRoot,
    interactions.startPointSvgX,
    levelViewBox,
  );
  const boosters = parseBoosters(boostersRoot, interactions.startPointSvgX, levelViewBox);

  return {
    id: levelId,
    viewBox: levelViewBox,
    ...interactions,
    obstacles,
    collectibles,
    boosters,
  };
}
