/** Доля прохождения маршрута: 0…1. */
export function computeRouteProgress(worldS: number, routeEndS: number): number {
  if (!(routeEndS > 0)) {
    return 0;
  }
  return Math.min(1, Math.max(0, worldS / routeEndS));
}

export function formatFlightTimer(seconds: number): string {
  return `${Math.floor(Math.max(0, seconds))}с`;
}

export function formatRouteDistanceMeters(distanceS: number): string {
  return `${Math.max(0, distanceS).toFixed(1).replace('.', ',')}м`;
}

export function formatCollectibleCount(collected: number, total: number): string {
  return `${collected} из ${total}`;
}
