import type { CSSProperties } from 'react';

export const DESIGN_SCREEN_W = 1080;
export const DESIGN_SCREEN_H = 1920;

export function designScreenRootStyle(backgroundColor = '#9fcfe4'): CSSProperties {
  return {
    flex: 1,
    minHeight: 0,
    minWidth: 0,
    containerType: 'size',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
    backgroundColor,
  };
}

/** Вписывает макет 1080×1920 в родителя без переполнения и скролла. */
export function designScreenStageStyle(): CSSProperties {
  return {
    position: 'relative',
    aspectRatio: `${DESIGN_SCREEN_W} / ${DESIGN_SCREEN_H}`,
    width: `min(100cqw, calc(100cqh * ${DESIGN_SCREEN_W} / ${DESIGN_SCREEN_H}))`,
    height: `min(100cqh, calc(100cqw * ${DESIGN_SCREEN_H} / ${DESIGN_SCREEN_W}))`,
  };
}

export function designScreenHitLayerStyle(): CSSProperties {
  return {
    position: 'absolute',
    inset: 0,
  };
}

export function designRectStyle(rect: { x: number; y: number; w: number; h: number }): CSSProperties {
  return {
    left: `${(rect.x / DESIGN_SCREEN_W) * 100}%`,
    top: `${(rect.y / DESIGN_SCREEN_H) * 100}%`,
    width: `${(rect.w / DESIGN_SCREEN_W) * 100}%`,
    height: `${(rect.h / DESIGN_SCREEN_H) * 100}%`,
  };
}
