import type { BoosterKind } from './level';

export type ActiveBooster = {
  kind: BoosterKind;
  remainingSeconds: number;
};

export type Player = {
  worldS: number;
  lane: number;
  /** Оставшиеся жизни (сердца), 0…MAX_PLAYER_LIVES. */
  lives: number;
  /** Активный бустер или null, если эффекта нет. */
  activeBooster: ActiveBooster | null;
};

export type VerticalMoveDirection = -1 | 0 | 1;

export function hasShieldBooster(player: Player): boolean {
  return player.activeBooster?.kind === 'shield';
}

export function hasSpeedBooster(player: Player): boolean {
  return player.activeBooster?.kind === 'speed';
}
