import { useLayoutEffect, useState } from 'react';
import type { RefObject } from 'react';

const GRID_COLS = 2;
const GRID_GAP_PX = 10;
const MIN_CELL_HEIGHT_PX = 68;
const NAV_RESERVED_PX = 36 * 2 + 8 * 2;
const PAGE_COUNTER_PX = 18;

export type StickerGridLayout = {
  cols: number;
  rows: number;
  pageSize: number;
};

function computeRows(gridHeightPx: number): number {
  return Math.max(
    1,
    Math.min(4, Math.floor((gridHeightPx + GRID_GAP_PX) / (MIN_CELL_HEIGHT_PX + GRID_GAP_PX))),
  );
}

export function useStickerGridLayout(
  pageWrapRef: RefObject<HTMLElement | null>,
  stickerCount: number,
): StickerGridLayout {
  const [layout, setLayout] = useState<StickerGridLayout>({
    cols: GRID_COLS,
    rows: 2,
    pageSize: GRID_COLS * 2,
  });

  useLayoutEffect(() => {
    const el = pageWrapRef.current;
    if (el == null) {
      return undefined;
    }

    const update = () => {
      const baseHeight = Math.max(0, el.clientHeight - NAV_RESERVED_PX);
      let rows = computeRows(baseHeight);
      let pageSize = GRID_COLS * rows;
      const needsCounter = stickerCount > pageSize;
      const gridHeight = Math.max(0, baseHeight - (needsCounter ? PAGE_COUNTER_PX : 0));
      rows = computeRows(gridHeight);
      pageSize = GRID_COLS * rows;
      setLayout({ cols: GRID_COLS, rows, pageSize });
    };

    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, [pageWrapRef, stickerCount]);

  return layout;
}
