export const COURIER_ORDER: readonly CourierId[] = COURIERS.map((courier) => courier.id);

export const DEFAULT_COURIER_ID: CourierId = 'eddy';

export function getCourierById(id: CourierId): Courier {
  const courier = COURIERS.find((entry) => entry.id === id);
  if (courier == null) {
    throw new Error(`Unknown courier id: ${id}`);
  }
  return courier;
}
