import { useEffect, type Dispatch, type SetStateAction } from 'react';
import { hasPlayerReachedFinish } from 'src/domain/levelRules';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';
import type { LevelViewState } from 'src/presentation/level/session/levelViewState';

export function useLevelProgress(
  level: Level | null,
  player: Player | null,
  setViewState: Dispatch<SetStateAction<LevelViewState>>,
): void {
  useEffect(() => {
    if (level == null || player == null) {
      return;
    }

    setViewState((previous) => {
      if (previous.reachedFinish) {
        return previous;
      }

      const reachedFinish = hasPlayerReachedFinish(level, player);
      if (reachedFinish === previous.reachedFinish) {
        return previous;
      }

      return { ...previous, reachedFinish };
    });
  }, [level, player, setViewState]);
}
