import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import type { CSSProperties } from 'react';
import {
  buildClaudiStickers,
  buildLeaderboards,
  fetchLeaderboardsFromBackend,
} from '../../application';
import {
  getCourierLicenseLevel,
  getCourierLicenseNameKey,
  getCourierLicenseProgressToNext,
  getUnlockedLevelCount,
} from '../../domain';
import { t } from '../../i18n';
import { useAppStore } from '../store/appStore';
import { SCREEN_BACKGROUNDS } from './screenBackgroundAssets';
import commonHeaderBackground from '../../infrastructure/assets/Images/commonHeaderBackground.png';

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  color: '#3a145c',
  backgroundImage: `url(${SCREEN_BACKGROUNDS.profile})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const headerStrip: CSSProperties = {
  width: '100%',
  flexShrink: 0,
  marginTop: 3,
  paddingTop: 'max(8px, env(safe-area-inset-top))',
  backgroundImage: `url(${commonHeaderBackground})`,
  backgroundRepeat: 'no-repeat',
  backgroundSize: '100% 100%',
  backgroundPosition: 'center top',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  minHeight: 52,
  paddingBottom: 12,
  paddingLeft: 16,
  paddingRight: 16,
  boxSizing: 'border-box',
};

const titleOnHeader: CSSProperties = {
  margin: 0,
  fontSize: 22,
  fontWeight: 900,
  color: '#3a145c',
  textShadow: '0 1px 0 rgba(255,255,255,0.6)',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  overflowY: 'auto',
  padding: 12,
  boxSizing: 'border-box',
};

const card: CSSProperties = {
  maxWidth: 460,
  margin: '0 auto 10px',
  padding: '12px 14px',
  borderRadius: 18,
  background: 'rgba(255, 255, 255, 0.85)',
  border: '3px solid rgba(90, 30, 120, 0.35)',
  fontSize: 14,
  fontWeight: 700,
  lineHeight: 1.45,
};

const row: CSSProperties = {
  display: 'flex',
  justifyContent: 'space-between',
  gap: 8,
  padding: '4px 0',
};

export function GameProfileScreen() {
  const economy = useAppStore((s) => s.playerEconomy);
  const [boards, setBoards] = useState(() => buildLeaderboards(economy));

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const remote = await fetchLeaderboardsFromBackend(economy);
      if (!cancelled && remote != null) {
        setBoards(remote);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [economy]);

  const stickers = useMemo(() => buildClaudiStickers(economy), [economy]);
  const unlockedStickers = stickers.filter((s) => s.unlocked).length;
  const licenseLevel = getCourierLicenseLevel(
    economy.ratedDeliveriesCount,
    economy.totalRating,
  );
  const licenseName = t(getCourierLicenseNameKey(licenseLevel));
  const licenseProgress = getCourierLicenseProgressToNext(
    economy.ratedDeliveriesCount,
    economy.totalRating,
  );
  const nextLicenseHint = licenseProgress.isMaxLevel
    ? t('game.profile.toNextLicenseMax')
    : t('game.profile.toNextLicenseHint')
        .replace('{deliveries}', String(licenseProgress.deliveriesToNext))
        .replace('{rating}', licenseProgress.ratingToNext.toFixed(1));
  const seasonRank =
    boards.weekly.find((e) => e.isPlayer)?.rank ??
    boards.allTime.find((e) => e.isPlayer)?.rank ??
    null;

  return (
    <div style={root}>
      <header style={headerStrip}>
        <h2 style={titleOnHeader}>{t('game.profile.title')}</h2>
      </header>
      <div style={body}>
        <div style={card}>
          <div style={row}>
            <span>{t('game.profile.totalRating')}</span>
            <span>{economy.totalRating.toFixed(1)}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.courierLicense')}</span>
            <span>{licenseName}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.toNextLicense')}</span>
            <span>{nextLicenseHint}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.passes')}</span>
            <span>{economy.passesBalance}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.unlockedGiants')}</span>
            <span>{getUnlockedLevelCount(economy.totalRating)}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.streak')}</span>
            <span>{economy.streakDays}</span>
          </div>
        </div>
        <div style={card}>
          <p style={{ margin: '0 0 8px', fontWeight: 900 }}>{t('game.profile.seasonBlock')}</p>
          <div style={row}>
            <span>{boards.seasonTitle}</span>
            <span>{boards.seasonEndsAtIso.slice(0, 10)}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.seasonRank')}</span>
            <span>{seasonRank != null ? `#${seasonRank}` : '—'}</span>
          </div>
          <div style={row}>
            <span>{t('game.profile.stickers')}</span>
            <span>
              {unlockedStickers}/{stickers.length}
            </span>
          </div>
        </div>
        <p style={{ textAlign: 'center', margin: '8px 0 0', fontSize: 13 }}>
          <Link to="/game/map">{t('game.profile.toMap')}</Link>
          {' · '}
          <Link to="/game/rewards">{t('game.nav.rewards')}</Link>
        </p>
      </div>
    </div>
  );
}
