import type { CSSProperties } from 'react';
import { t } from '../../i18n';

export type ActionErrorCode =
  | 'not_in_pool'
  | 'locked'
  | 'no_passes'
  | 'map_locked';

const wrap: CSSProperties = {
  position: 'absolute',
  left: 12,
  right: 12,
  top: 'max(52px, calc(env(safe-area-inset-top) + 44px))',
  zIndex: 30,
  display: 'flex',
  flexDirection: 'column',
  gap: 6,
  pointerEvents: 'none',
};

const pill: CSSProperties = {
  pointerEvents: 'auto',
  borderRadius: 12,
  padding: '8px 12px',
  fontSize: 13,
  fontWeight: 700,
  lineHeight: 1.35,
  boxShadow: '0 2px 8px rgba(0,0,0,0.25)',
};

function actionErrorMessage(code: ActionErrorCode, ratingRequired?: number): string {
  switch (code) {
    case 'not_in_pool':
      return t('game.errors.notInPool');
    case 'locked':
      return t('game.errors.deliveryLocked');
    case 'no_passes':
      return t('game.errors.noPasses');
    case 'map_locked':
      return t('game.errors.mapLocked').replace('{rating}', String(ratingRequired ?? 0));
    default:
      return t('game.errors.generic');
  }
}

type GameStatusBannerProps = {
  syncWarning?: string | null;
  actionError?: ActionErrorCode | null;
  actionErrorRatingRequired?: number;
  onDismissActionError?: () => void;
  onDismissSyncWarning?: () => void;
};

export function GameStatusBanner({
  syncWarning,
  actionError,
  actionErrorRatingRequired,
  onDismissActionError,
  onDismissSyncWarning,
}: GameStatusBannerProps) {
  const hasSync = syncWarning != null && syncWarning !== '';
  const hasAction = actionError != null;
  if (!hasSync && !hasAction) {
    return null;
  }

  return (
    <div style={wrap} role="status" aria-live="polite">
      {hasSync ? (
        <div
          style={{
            ...pill,
            background: 'rgba(40, 20, 60, 0.92)',
            color: '#ffe8a8',
            border: '2px solid #c9a227',
          }}
        >
          <span>{syncWarning}</span>
          {onDismissSyncWarning != null ? (
            <button
              type="button"
              onClick={onDismissSyncWarning}
              style={{
                marginLeft: 8,
                border: 'none',
                background: 'transparent',
                color: '#fff',
                cursor: 'pointer',
                fontWeight: 800,
              }}
            >
              ×
            </button>
          ) : null}
        </div>
      ) : null}
      {hasAction ? (
        <div
          style={{
            ...pill,
            background: 'rgba(120, 20, 30, 0.92)',
            color: '#fff',
            border: '2px solid #e02020',
            ...(actionError === 'map_locked'
              ? {
                  width: '40%',
                  marginLeft: 'auto',
                  marginRight: 'auto',
                  textAlign: 'center' as const,
                }
              : {}),
          }}
        >
          <span>{actionErrorMessage(actionError, actionErrorRatingRequired)}</span>
          {onDismissActionError != null ? (
            <button
              type="button"
              onClick={onDismissActionError}
              style={{
                marginLeft: 8,
                border: 'none',
                background: 'transparent',
                color: '#fff',
                cursor: 'pointer',
                fontWeight: 800,
              }}
            >
              ×
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
