import type { Level } from '../../domain/level';
import type { Player } from '../../domain/player';
import { hasSpeedBooster } from '../../domain/player';
import { FORWARD_SPEED_S_PER_SEC, SPEED_BOOST_MULTIPLIER } from '../constants';

export function movePlayerForwardUseCase(
  level: Level,
  player: Player,
  deltaSeconds: number,
): Player {
  const speed =
    FORWARD_SPEED_S_PER_SEC * (hasSpeedBooster(player) ? SPEED_BOOST_MULTIPLIER : 1);
  const nextWorldS = Math.min(player.worldS + speed * deltaSeconds, level.routeEndS);

  if (nextWorldS === player.worldS) {
    return player;
  }

  return { ...player, worldS: nextWorldS };
}
