import type { GiantId, LevelDefinition } from '../../domain';

/** finish_point.x − start_point.x для `test_level.svg` (1 svg unit = 1 m). */
export const SVG_TEST_LEVEL_ROUTE_END_S = 33_305;

export const SVG_TEST_LEVEL_VISUAL_THEME_ID = 'svg_test_level' as const;

/** PoC: любая доставка играет SVG-макет вместо прод-уровня гиганта. */
export const USE_SVG_TEST_LEVEL_FOR_ALL_DELIVERIES = true;

export function isSvgTestLevel(level: LevelDefinition): boolean {
  return level.visualThemeId === SVG_TEST_LEVEL_VISUAL_THEME_ID;
}

/** SVG-уровень для гиганта: геометрия из level pack, метаданные — из шаблона. */
export function getSvgLevelForGiant(giantId: GiantId): LevelDefinition {
  return {
    ...SVG_TEST_LEVEL,
    id: `svg_${giantId}_v1`,
    giantId,
  };
}

/**
 * Dev-уровень: геометрия маршрута и препятствия из `test_level.svg`,
 * сегмент JSON — только метаданные для валидации и скорости.
 */
export const SVG_TEST_LEVEL: LevelDefinition = {
  id: 'svg_test_v1',
  version: 1,
  giantId: 'swami',
  visualThemeId: SVG_TEST_LEVEL_VISUAL_THEME_ID,
  baseForwardSpeed: 90,
  ratingTargets: {
    targetTimeSec: 400,
    targetSparkCount: 0,
  },
  segments: [
    {
      fromS: 0,
      toS: SVG_TEST_LEVEL_ROUTE_END_S,
    },
  ],
};
