import { useLayoutEffect, useRef, type RefObject } from 'react';
import type { Level } from 'src/domain/level';
import type { AppContext } from 'src/infrastructure/bootstrap';
import { spawnBoosterAssets } from './spawnBoosterAssets';
import { spawnCollectibleAssets } from './spawnCollectibleAssets';
import { spawnObstacleAssets } from './spawnObstacleAssets';
import { applyParsedLevelDomEffects } from './svgDomUtils';

import { MAX_PARSE_ATTEMPTS } from 'src/presentation/level/constants';

type ParseLevelFromDomRefs = {
  interactionsHostRef: RefObject<HTMLDivElement | null>;
  obstaclesHostRef: RefObject<HTMLDivElement | null>;
  collectiblesHostRef: RefObject<HTMLDivElement | null>;
  boostersHostRef: RefObject<HTMLDivElement | null>;
};

export function useParseLevelFromDom(
  packId: string,
  obstacleAssets: Record<string, string>,
  collectibleAssets: Record<string, string>,
  boosterAssets: Record<string, string>,
  app: AppContext,
  refs: ParseLevelFromDomRefs,
  onLevelParsed: (level: Level) => void,
): void {
  const parsedOnceRef = useRef(false);

  useLayoutEffect(() => {
    if (parsedOnceRef.current) {
      return;
    }

    let cancelled = false;
    let attempts = 0;

    const tryParse = (): void => {
      if (cancelled || parsedOnceRef.current) {
        return;
      }

      const interactionsSvg = refs.interactionsHostRef.current?.querySelector('svg');
      const obstaclesSvg = refs.obstaclesHostRef.current?.querySelector('svg');
      const collectiblesSvg = refs.collectiblesHostRef.current?.querySelector('svg');
      const boostersSvg = refs.boostersHostRef.current?.querySelector('svg');

      if (
        !(interactionsSvg instanceof SVGSVGElement) ||
        !(obstaclesSvg instanceof SVGSVGElement) ||
        !(collectiblesSvg instanceof SVGSVGElement) ||
        !(boostersSvg instanceof SVGSVGElement)
      ) {
        attempts += 1;
        if (attempts < MAX_PARSE_ATTEMPTS) {
          requestAnimationFrame(tryParse);
        }
        return;
      }

      try {
        const parsed = app.parseLevelSvg(
          packId,
          interactionsSvg,
          obstaclesSvg,
          collectiblesSvg,
          boostersSvg,
        );
        spawnObstacleAssets(obstaclesSvg, parsed.obstacles, obstacleAssets);
        spawnCollectibleAssets(
          collectiblesSvg,
          parsed.collectibles,
          collectibleAssets,
          parsed.viewBox,
        );
        spawnBoosterAssets(boostersSvg, parsed.boosters, boosterAssets, parsed.viewBox);
        applyParsedLevelDomEffects(interactionsSvg, obstaclesSvg);
        parsedOnceRef.current = true;
        onLevelParsed(parsed);
      } catch (error) {
        console.error('[useParseLevelFromDom] parseLevelSvg failed', error);
      }
    };

    tryParse();
    return () => {
      cancelled = true;
    };
  }, [
    app,
    boosterAssets,
    collectibleAssets,
    obstacleAssets,
    onLevelParsed,
    packId,
    refs.boostersHostRef,
    refs.collectiblesHostRef,
    refs.interactionsHostRef,
    refs.obstaclesHostRef,
  ]);
}
