/** Id уровня Свами v1 (реестр {@link LEVEL_BY_GIANT_ID}). */
export const SWAMI_TEMPLATE_LEVEL_ID = 'swami_v1' as const;

/**
 * Ширина «окна» маршрута по оси S в метрах (масштаб world S → экранный X).
 * Должна быть ≥ VIEW_AHEAD_M / (1 − COURIER_SCREEN_X_RATIO), иначе спавны
 * впереди попадают за правый край playfield.
 */
export const PLAYFIELD_WIDTH_M = 18 as const;

/** Эталонное соотношение сторон playfield для перевода S (м) ↔ lane (norm). */
export const PLAYFIELD_REF_WIDTH_TO_HEIGHT = 9 / 16;

/** Lane norm на 1 м маршрута S при эталонном playfield (см. {@link PLAYFIELD_REF_WIDTH_TO_HEIGHT}). */
export const NORM_LANE_PER_ROUTE_METER_S_REF =
  PLAYFIELD_REF_WIDTH_TO_HEIGHT / PLAYFIELD_WIDTH_M;

export const COURIER_HITBOX_WIDTH_M = 0.6 as const;
export const COURIER_HITBOX_HEIGHT_NORM = 0.08 as const;

export const BOOSTER_PICKUP_WIDTH_M = 0.4 as const;
export const BOOSTER_PICKUP_HEIGHT_NORM = 0.06 as const;
/** Масштаб визуала/хитбоксов курьера в прототипе полёта. */
export const FLIGHT_ENTITY_SCALE = 3.515625 as const;

/** Доп. масштаб препятствий относительно {@link FLIGHT_ENTITY_SCALE}. */
export const FLIGHT_OBSTACLE_SCALE_MUL = 1.045 as const;

/** Отладочная отрисовка AABB-хитбокса препятствий в GameplayScreen. */
export const FLIGHT_OBSTACLE_SHOW_HITBOX = true as const;

/** Доп. масштаб бустеров на карте относительно {@link FLIGHT_ENTITY_SCALE}. */
export const FLIGHT_BOOSTER_SCALE_MUL = 1.05 as const;

export const FLIGHT_OBSTACLE_SCALE =
  FLIGHT_ENTITY_SCALE * FLIGHT_OBSTACLE_SCALE_MUL;

/** AABB препятствий: −70% от {@link FLIGHT_OBSTACLE_SCALE} (только коллизия/отладка). */
export const FLIGHT_OBSTACLE_HITBOX_SCALE_MUL = 0.3 as const;

export const FLIGHT_OBSTACLE_HITBOX_SCALE =
  FLIGHT_OBSTACLE_SCALE * FLIGHT_OBSTACLE_HITBOX_SCALE_MUL;

export const FLIGHT_BOOSTER_SCALE =
  FLIGHT_ENTITY_SCALE * FLIGHT_BOOSTER_SCALE_MUL;

/** После засчитанного удара: не strike повторно с тем же объектом, сек. */
export const COLLISION_GRACE_SEC = 2 as const;

/** Длина модификатора по пройденному s, м (GDD / test-level-spec). */
export const MODIFIER_DISTANCE_M = 15 as const;

/** Суффикс id уровней v1 (по одному на гиганта). */
export const GIANT_LEVEL_ID_SUFFIX = '_v1' as const;

/** maxVerticalSpeedNormPerSec = factor * (handling / 6). */
export const VERTICAL_SPEED_BASE_FACTOR = 0.525 as const;

/** Доля ширины поля — фиксированная позиция курьера на экране. */
export const COURIER_SCREEN_X_RATIO = 0.22 as const;

/** Сколько метров маршрута впереди видно от позиции курьера. */
export const VIEW_AHEAD_M = 14 as const;

/** Множитель скорости препятствий с движением `toward_player`. */
export const OBSTACLE_APPROACH_SPEED_MUL = 0.3 as const;

/** Мини-игра шаблонного уровня (вариант A test-level-spec §8.1). */
export const TEMPLATE_LEVEL_MINIGAME_ID = 'rock_repair_gadget' as const;
