import { parseLevelSvg } from './parseLevelSvg';
import { startLevelUseCase } from '../application/use-cases/startLevelUseCase';
import type { LevelSession } from '../application/use-cases/startLevelUseCase';
import type { Level } from '../domain/level';
import { loadLevelPack } from './levelLoader';
import type { LevelPack } from './levels/levelPack';

export type AppContext = {
    loadLevelPack: (levelId: string) => LevelPack;
    parseLevelSvg: typeof parseLevelSvg;
    startLevel: (level: Level) => LevelSession;
};

export function bootstrap(): AppContext {
    return {
        loadLevelPack,
        parseLevelSvg,
        startLevel: startLevelUseCase,
    };
}

export type { LevelSession };
