import type { CSSProperties } from 'react';
import type { LevelCanvasLayout } from './parseLevelLayout';

export function layoutToLayerStyle(layout: LevelCanvasLayout): CSSProperties {
  return {
    position: 'absolute',
    left: layout.canvasLeftPx,
    top: layout.canvasTopPx,
    width: layout.canvasWidthPx,
    height: layout.canvasHeightPx,
    overflow: 'visible',
  };
}
