function StatBar({ value }: { value: number }) {
  const pct = Math.round(value * 100);
  return (
    <div style={barTrack} aria-label={`${pct}%`}>
      <img
        src={skillBarFill}
        alt=""
        style={{
          position: 'absolute',
          left: 0,
          top: 0,
          height: '100%',
          width: `${pct}%`,
          objectFit: 'fill',
          objectPosition: 'left center',
        }}
      />
    </div>
  );
}

export function GameCharacterSelectScreen() {
  const { giantId: giantIdParam } = useParams();
  const navigate = useNavigate();
  const setSelectedCourier = useAppStore((s) => s.setSelectedCourier);
  const ensureAndBeginDelivery = useAppStore((s) => s.ensureAndBeginDelivery);
  const playerEconomy = useAppStore((s) => s.playerEconomy);
  const [index, setIndex] = useState(0);

  const mapPoint =
    giantIdParam != null && giantIdParam !== '' && isGiantId(giantIdParam)
      ? tryGetMapDeliveryPoint(giantIdParam)
      : null;
  const poolEntry =
    mapPoint != null ? findPoolEntryByGiant(playerEconomy, mapPoint.giantId) : null;

  const courierId = COURIER_IDS[index] ?? 'eddy';
  const portraitSrc = COURIER_PORTRAIT_BY_ID[courierId];

  const counterLabel = t('game.character.counter')
    .replace('{n}', String(index + 1))
    .replace('{total}', String(COURIER_IDS.length));

  const goPrev = () => setIndex((i) => (i - 1 + COURIER_IDS.length) % COURIER_IDS.length);
  const goNext = () => setIndex((i) => (i + 1) % COURIER_IDS.length);

  const confirm = () => {
    if (mapPoint == null || poolEntry == null) {
      return;
    }
    void (async () => {
      const mission = { giantId: poolEntry.giantId, orderIndex: poolEntry.orderIndex };
      await setSelectedCourier(courierId);
      const begin = await ensureAndBeginDelivery(mission);
      if (!begin.ok) {
        return;
      }
      navigate('/play', {
        replace: true,
        state: { mission },
      });
    })();
  };

  return (
    <div style={root}>
      <button
        type="button"
        onClick={() => {
          if (giantIdParam != null && giantIdParam !== '' && isGiantId(giantIdParam)) {
            navigate(`/game/delivery/${encodeURIComponent(giantIdParam)}`);
            return;
          }
          navigate('/game/map');
        }}
        style={screenBackBtn}
        aria-label={t('game.character.backToDelivery')}
      >
        <img src={lobbyInteractArrow} alt="" style={headerBackImg} />
      </button>
      <header style={headerStrip}>
        <div style={headerCenter}>
          <h1 style={titleOnHeader}>{t('game.character.title')}</h1>
          <p style={counterOnHeader}>{counterLabel}</p>
        </div>
      </header>
      <div style={mainColumn}>
        <div style={panel}>
        <div style={courierTitle}>{courierId}</div>
        <div style={carousel}>
          <button type="button" style={arrowBtn} onClick={goPrev} aria-label={t('game.character.prev')}>
            <img src={lobbyInteractArrow} alt="" width={26} height={26} style={{ transform: 'rotate(180deg)' }} />
          </button>
          <img src={portraitSrc} alt="" style={portrait} />
          <button type="button" style={arrowBtn} onClick={goNext} aria-label={t('game.character.next')}>
            <img src={lobbyInteractArrow} alt="" width={26} height={26} />
          </button>
        </div>

        <div style={{ ...statRow, marginTop: 16 }}>
          <img src={hpIcon} alt="" width={28} height={28} style={{ objectFit: 'contain' }} />
          <div>
            <div style={{ fontSize: 12, fontWeight: 800, color: '#3a145c', marginBottom: 2 }}>
              {t('game.character.statLife')}
            </div>
            <StatBar value={getCourierStatBarValue(courierId, 'power')} />
          </div>
        </div>
        <div style={statRow}>
          <img src={speedIcon} alt="" width={28} height={28} style={{ objectFit: 'contain' }} />
          <div>
            <div style={{ fontSize: 12, fontWeight: 800, color: '#3a145c', marginBottom: 2 }}>
              {t('game.character.statSpeed')}
            </div>
            <StatBar value={getCourierStatBarValue(courierId, 'speed')} />
          </div>
        </div>
        <div style={statRow}>
          <img src={controlIcon} alt="" width={28} height={28} style={{ objectFit: 'contain' }} />
          <div>
            <div style={{ fontSize: 12, fontWeight: 800, color: '#3a145c', marginBottom: 2 }}>
              {t('game.character.statHandling')}
            </div>
            <StatBar value={getCourierStatBarValue(courierId, 'handling')} />
          </div>
        </div>

        <button type="button" style={selectBtn} onClick={confirm} disabled={mapPoint == null || poolEntry == null}>
          {t('game.character.select')}
        </button>
        {mapPoint != null && poolEntry != null ? (
          <p style={{ marginTop: 10, fontSize: 12, color: '#4a1a6d', textAlign: 'center' }}>
            {t('game.character.forGiant').replace('{name}', getGiantDisplayName(mapPoint.giantId))}
          </p>
        ) : giantIdParam != null && giantIdParam !== '' ? (
          <p style={{ marginTop: 10, fontSize: 12, color: '#8b2040', textAlign: 'center' }}>
            {t('game.character.unknownGiant')}
          </p>
        ) : null}
        </div>
      </div>
    </div>
  );
}
