import { MAX_PLAYER_LIVES } from 'src/domain/constants';
import type { Player } from 'src/domain/player';

/** Снимает одну жизнь за столкновение; не уходит ниже 0. */
export function applyPlayerHitUseCase(player: Player, hitCount = 1): Player {
  if (hitCount <= 0 || player.lives <= 0) {
    return player;
  }

  const nextLives = Math.max(0, Math.min(MAX_PLAYER_LIVES, player.lives - hitCount));
  if (nextLives === player.lives) {
    return player;
  }

  return {
    ...player,
    lives: nextLives,
  };
}
