import { NavLink, Outlet, useLocation, useNavigate } from 'react-router-dom';
import type { CSSProperties } from 'react';
import { formatSignedRatingDelta, getCourierLicenseLevel, getCourierLicenseNameKey } from '../../domain';
import { t } from '../../i18n';
import menuButtonBackground from '../../infrastructure/assets/Images/menuButtonBackground.png';
import activeMenuButtonBackground from '../../infrastructure/assets/Images/activeMenuButtonBackground.png';
import mapIcon from '../../infrastructure/assets/Images/mapIcon.png';
import deliveryIcon from '../../infrastructure/assets/Images/deliveryIcon.png';
import rewardsIcon from '../../infrastructure/assets/Images/rewardsIcon.png';
import coinCountBackground from '../../infrastructure/assets/Images/coinCountBackground_default.png';
import coinIcon from '../../infrastructure/assets/Images/coinIcon.png';
import { GameStatusBanner } from '../components/GameStatusBanner';
import { useAppStore } from '../store/appStore';

const barWrap: CSSProperties = {
  flexShrink: 0,
  paddingBottom: 'env(safe-area-inset-bottom)',
};

const barInner: CSSProperties = {
  display: 'grid',
  gridTemplateColumns: '1fr 1fr 1fr',
  gap: 4,
  padding: '0 8px',
  maxWidth: 520,
  margin: '0 auto',
};

const linkBase: CSSProperties = {
  textDecoration: 'none',
  color: '#f6e9ff',
  padding: '10px 6px 12px',
  minHeight: 80,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 4,
  fontSize: 11,
  fontWeight: 700,
  backgroundSize: '100% 100%',
  backgroundRepeat: 'no-repeat',
  backgroundPosition: 'center bottom',
};

const iconStyle: CSSProperties = {
  width: 40,
  height: 40,
  objectFit: 'contain',
};

function GameBottomNav() {
  return (
    <nav style={barWrap} aria-label={t('game.nav.aria')}>
      <div style={barInner}>
        <NavLink
          to="/game/map"
          style={({ isActive }) => ({
            ...linkBase,
            backgroundImage: `url(${isActive ? activeMenuButtonBackground : menuButtonBackground})`,
          })}
        >
          <img src={mapIcon} alt="" style={iconStyle} />
          {t('game.nav.map')}
        </NavLink>
        <NavLink
          to="/game/deliveries"
          style={({ isActive }) => ({
            ...linkBase,
            backgroundImage: `url(${isActive ? activeMenuButtonBackground : menuButtonBackground})`,
          })}
        >
          <img src={deliveryIcon} alt="" style={iconStyle} />
          {t('game.nav.deliveries')}
        </NavLink>
        <NavLink
          to="/game/rewards"
          style={({ isActive }) => ({
            ...linkBase,
            backgroundImage: `url(${isActive ? activeMenuButtonBackground : menuButtonBackground})`,
          })}
        >
          <img src={rewardsIcon} alt="" style={iconStyle} />
          {t('game.nav.rewards')}
        </NavLink>
      </div>
    </nav>
  );
}

const layoutRoot: CSSProperties = {
  height: '100dvh',
  maxHeight: '100dvh',
  overflow: 'hidden',
  display: 'flex',
  flexDirection: 'column',
  background: '#2a0f45',
};

const outletWrap: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  position: 'relative',
};

const coinHudWrap: CSSProperties = {
  position: 'absolute',
  top: 'max(8px, env(safe-area-inset-top))',
  right: 12,
  zIndex: 20,
  pointerEvents: 'none',
};

const licenseHudWrap: CSSProperties = {
  position: 'absolute',
  top: 'max(8px, env(safe-area-inset-top))',
  left: '50%',
  transform: 'translateX(-50%)',
  zIndex: 20,
  pointerEvents: 'none',
  maxWidth: 'min(52vw, 264px)',
};

const ratingHudWrap: CSSProperties = {
  position: 'absolute',
  top: 'max(8px, env(safe-area-inset-top))',
  left: 12,
  zIndex: 20,
  pointerEvents: 'none',
};

const HUD_PILL_HEIGHT = 48;
const HUD_PILL_ICON_SIZE = 34;

const hudPillBase: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  boxSizing: 'border-box',
  height: HUD_PILL_HEIGHT,
  backgroundColor: 'transparent',
  backgroundImage: `url(${coinCountBackground})`,
  backgroundSize: '100% 100%',
  backgroundRepeat: 'no-repeat',
  border: 'none',
  color: '#fff',
  fontWeight: 800,
  pointerEvents: 'auto',
  filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.35))',
};

const licenseHudPill: CSSProperties = {
  ...hudPillBase,
  justifyContent: 'center',
  padding: '0 14px',
  minWidth: 0,
  fontSize: 16,
  textAlign: 'center',
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
};

const hudPill: CSSProperties = {
  ...hudPillBase,
  gap: 10,
  padding: '0 17px 0 12px',
  minWidth: 144,
  justifyContent: 'flex-end',
  fontSize: 19,
};

const ratingDeltaText = (positive: boolean): CSSProperties => ({
  fontSize: 16,
  fontWeight: 900,
  color: positive ? '#9dffb8' : '#ffb0b0',
  textShadow: '0 1px 2px rgba(0,0,0,0.45)',
  marginLeft: -2,
});

export function GameHubLayout() {
  const location = useLocation();
  const navigate = useNavigate();
  const passesBalance = useAppStore((s) => s.passesBalance);
  const playerEconomy = useAppStore((s) => s.playerEconomy);
  const averageRating = playerEconomy.totalRating;
  const lastRatingDelta = useAppStore((s) => s.lastRatingDelta);
  const syncWarning = useAppStore((s) => s.syncWarning);
  const lastActionError = useAppStore((s) => s.lastActionError);
  const lastActionErrorRatingRequired = useAppStore((s) => s.lastActionErrorRatingRequired);
  const clearActionError = useAppStore((s) => s.clearActionError);
  const dismissSyncWarning = useAppStore((s) => s.dismissSyncWarning);
  const isOverlayScreen =
    location.pathname.startsWith('/game/character') || location.pathname.startsWith('/game/delivery');
  const hideNav = isOverlayScreen;
  const isMapScreen = location.pathname.startsWith('/game/map');
  const isFlightTicketScreen = location.pathname.startsWith('/game/flight-tickets');
  const hidePassHud =
    isFlightTicketScreen ||
    location.pathname.startsWith('/game/deliveries') ||
    location.pathname.startsWith('/game/rewards');
  const showHubBanner =
    !location.pathname.startsWith('/game/map') && !isOverlayScreen;

  const displayRatingDelta = lastRatingDelta ?? 0;

  const ratingAriaLabel = `${t('game.map.averageRating')}: ${averageRating.toFixed(1)}, ${t('game.map.ratingDelta').replace(
    '{delta}',
    formatSignedRatingDelta(displayRatingDelta),
  )}`;

  const licenseLevel = getCourierLicenseLevel(
    playerEconomy.ratedDeliveriesCount,
    playerEconomy.totalRating,
  );
  const licenseName = t(getCourierLicenseNameKey(licenseLevel));

  return (
    <div style={layoutRoot}>
      <div style={outletWrap}>
        {showHubBanner ? (
          <GameStatusBanner
            syncWarning={syncWarning}
            actionError={lastActionError}
            actionErrorRatingRequired={lastActionErrorRatingRequired ?? undefined}
            onDismissActionError={clearActionError}
            onDismissSyncWarning={dismissSyncWarning}
          />
        ) : null}
        <Outlet />
        {hideNav ? null : (
          <>
            {isMapScreen ? (
              <>
                <div style={licenseHudWrap}>
                  <button
                    type="button"
                    style={{ ...licenseHudPill, cursor: 'pointer' }}
                    aria-label={t('game.map.licenseTitle')}
                    onClick={() => navigate('/game/license')}
                  >
                    {licenseName}
                  </button>
                </div>
                <div style={ratingHudWrap}>
                  <button
                    type="button"
                    style={{ ...hudPill, cursor: 'pointer' }}
                    aria-label={ratingAriaLabel}
                    onClick={() => navigate('/game/rating')}
                  >
                    <span>{averageRating.toFixed(1)}</span>
                    <img
                      src={rewardsIcon}
                      alt=""
                      width={HUD_PILL_ICON_SIZE}
                      height={HUD_PILL_ICON_SIZE}
                      style={{ objectFit: 'contain' }}
                    />
                    <span style={ratingDeltaText(displayRatingDelta >= 0)}>
                      {formatSignedRatingDelta(displayRatingDelta)}
                    </span>
                  </button>
                </div>
              </>
            ) : null}
            {!hidePassHud ? (
              <div style={coinHudWrap}>
                <button
                  type="button"
                  style={{ ...hudPill, cursor: 'pointer' }}
                  aria-label={t('game.flightTicket.hudAria').replace('{count}', String(passesBalance))}
                  onClick={() => navigate('/game/flight-tickets')}
                >
                  <span>{passesBalance}</span>
                  <img src={coinIcon} alt="" width={HUD_PILL_ICON_SIZE} height={HUD_PILL_ICON_SIZE} style={{ objectFit: 'contain' }} />
                </button>
              </div>
            ) : null}
          </>
        )}
      </div>
      {hideNav ? null : <GameBottomNav />}
    </div>
  );
}
