import {
  LEVEL_SCREEN_PROGRESS_BAR_ORIGIN_X,
  LEVEL_SCREEN_SVG_SELECTOR,
} from 'src/presentation/level/constants';

/** Масштабирует `#progress_bar_scale` по X от левого края трека (доля 0…1). */
export function setSvgProgressBarFill(host: ParentNode, progress: number): void {
  const scaleEl = host.querySelector(LEVEL_SCREEN_SVG_SELECTOR.PROGRESS_BAR_SCALE);
  if (!(scaleEl instanceof SVGElement)) {
    return;
  }

  const clamped = Math.min(1, Math.max(0, progress));
  const x = LEVEL_SCREEN_PROGRESS_BAR_ORIGIN_X;
  scaleEl.setAttribute(
    'transform',
    `translate(${x} 0) scale(${clamped} 1) translate(${-x} 0)`,
  );
}
