import { getLevelPack } from './levels';
import type { LevelPack } from './levels/levelPack';

export function loadLevelPack(levelId: string): LevelPack {
  const pack = getLevelPack(levelId);
  if (pack == null) {
    throw new Error(`loadLevelPack: unknown level "${levelId}"`);
  }
  return pack;
}
