  flex: 1,
  minWidth: 0,
  minHeight: 0,
  maxWidth: 460,
  width: '100%',
  padding: '16px 14px',
  borderRadius: 18,
  background: 'rgba(255, 255, 255, 0.82)',
  border: '3px solid rgba(90, 30, 120, 0.35)',
