import type { CSSProperties } from 'react';
import { t } from '../../i18n';
import { SCREEN_BACKGROUNDS } from './screenBackgroundAssets';
import commonHeaderBackground from '../../infrastructure/assets/Images/commonHeaderBackground.png';
import rewardsIcon from '../../infrastructure/assets/Images/rewardsIcon.png';
import {
  HeaderHintBackdrop,
  HeaderHintPopup,
  HeaderHintTitleButton,
  headerHintAnchor,
  headerHintTitleButton,
  useHeaderHintPopup,
} from './HeaderHintPopup';
import { useAppStore } from '../store/appStore';

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  color: '#111',
  position: 'relative',
  backgroundImage: `url(${SCREEN_BACKGROUNDS.rating})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const headerStrip: CSSProperties = {
  width: '100%',
  flexShrink: 0,
  marginTop: 3,
  paddingTop: 'max(8px, env(safe-area-inset-top))',
  backgroundImage: `url(${commonHeaderBackground})`,
  backgroundRepeat: 'no-repeat',
  backgroundSize: '100% 100%',
  backgroundPosition: 'center top',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 8,
  minHeight: 52,
  paddingBottom: 12,
  paddingLeft: 16,
  paddingRight: 16,
  boxSizing: 'border-box',
  ...headerHintAnchor,
};

const titleOnHeader: CSSProperties = {
  ...headerHintTitleButton,
  fontSize: 22,
  fontWeight: 900,
  color: '#3a145c',
  textShadow: '0 1px 0 rgba(255,255,255,0.6)',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  overflowY: 'auto',
  padding: '12px 16px 16px',
  boxSizing: 'border-box',
};

const contentCard: CSSProperties = {
  maxWidth: 460,
  margin: '0 auto',
  padding: '16px 14px',
  borderRadius: 18,
  background: 'rgba(255, 255, 255, 0.92)',
  border: '3px solid rgba(90, 30, 120, 0.35)',
};

const ratingRow: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: 12,
};

const ratingLabel: CSSProperties = {
  margin: 0,
  fontSize: 15,
  fontWeight: 700,
  color: '#222',
  lineHeight: 1.3,
};

const ratingBadge: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 6,
  padding: '6px 12px',
  borderRadius: 8,
  background: '#fff5a5',
  fontSize: 18,
  fontWeight: 900,
  color: '#111',
  flexShrink: 0,
};

function formatRatingDisplay(value: number): string {
  return value.toFixed(1).replace('.', ',');
}

export function GameRatingScreen() {
  const averageRating = useAppStore((s) => s.playerEconomy.totalRating);
  const { hintOpen, toggleHint, closeHint } = useHeaderHintPopup();

  return (
    <div style={root}>
      {hintOpen ? <HeaderHintBackdrop onClose={closeHint} /> : null}
      <header style={headerStrip}>
        <HeaderHintTitleButton
          hintOpen={hintOpen}
          hintId="game-rating-hint"
          onClick={toggleHint}
          style={titleOnHeader}
        >
          {t('game.rating.title')}
        </HeaderHintTitleButton>
        {hintOpen ? (
          <HeaderHintPopup
            hintId="game-rating-hint"
            hintTitle={t('game.rating.infoTitle')}
            hintBody={t('game.rating.infoBody')}
            onClose={closeHint}
          />
        ) : null}
      </header>
      <div style={body}>
        <div style={contentCard}>
          <div style={ratingRow}>
            <p style={ratingLabel}>{t('game.map.averageRating')}</p>
            <span style={ratingBadge} aria-label={`${t('game.map.averageRating')}: ${formatRatingDisplay(averageRating)}`}>
              {formatRatingDisplay(averageRating)}
              <img src={rewardsIcon} alt="" width={22} height={22} style={{ objectFit: 'contain' }} />
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
