/** Растровая подложка гигантов в `map.svg` (дублирует векторный слой `#giants`). */
const MAP_RASTER_GIANTS_RECT_ID = 'Rectangle';

export function hideMapRasterGiants(svgRoot: SVGSVGElement | null | undefined): void {
  if (svgRoot == null) {
    return;
  }
  const raster = svgRoot.querySelector(`#${MAP_RASTER_GIANTS_RECT_ID}`);
  if (raster instanceof SVGGraphicsElement) {
    raster.style.display = 'none';
  }
}
