import { MAX_PLAYER_LIVES } from 'src/domain/constants';
import { LEVEL_SCREEN_SVG_ELEMENT_ID, LEVEL_SCREEN_SVG_SELECTOR } from 'src/presentation/level/constants';

export type HeartSlotSvgIds = {
  fillMask: string;
  fillBody: string;
  brokenBody: string;
  brokenMask: string;
};

/**
 * Слоты слева направо (#1…#5). При потере жизни гасится справа налево:
 * lives=5 → все fill; lives=4 → слот #5 broken; …
 */
export const HEART_SLOT_SVG_IDS: readonly HeartSlotSvgIds[] = [
  {
    fillMask: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_MASK_4,
    fillBody: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_BODY_1,
    brokenBody: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_BODY_4,
    brokenMask: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_MASK_4,
  },
  {
    fillMask: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_MASK_3,
    fillBody: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_BODY_2,
    brokenBody: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_BODY_3,
    brokenMask: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_MASK_3,
  },
  {
    fillMask: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_MASK_2,
    fillBody: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_BODY_3,
    brokenBody: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_BODY_2,
    brokenMask: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_MASK_2,
  },
  {
    fillMask: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_MASK,
    fillBody: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_BODY_4,
    brokenBody: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_BODY,
    brokenMask: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_MASK,
  },
  {
    fillMask: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_MASK_5,
    fillBody: LEVEL_SCREEN_SVG_ELEMENT_ID.FILL_HEART_BODY_5,
    brokenBody: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_BODY_5,
    brokenMask: LEVEL_SCREEN_SVG_ELEMENT_ID.BROKEN_HEART_MASK_5,
  },
] as const;

function findHeartElement(host: ParentNode, elementId: string): SVGElement | null {
  const scoped = host.querySelector(`${LEVEL_SCREEN_SVG_SELECTOR.LIFES} [id="${elementId}"]`);
  if (scoped instanceof SVGElement) {
    return scoped;
  }
  const fallback = host.querySelector(`[id="${elementId}"]`);
  return fallback instanceof SVGElement ? fallback : null;
}

function setSvgGroupVisibility(host: ParentNode, elementId: string, visible: boolean): void {
  const el = findHeartElement(host, elementId);
  if (el == null) {
    return;
  }

  const visibility = visible ? 'visible' : 'hidden';
  el.setAttribute('visibility', visibility);

  // broken_heart_mask может быть внутри transform-обёртки без id.
  const parent = el.parentElement;
  if (
    parent instanceof SVGElement
    && parent.tagName === 'g'
    && parent.id === ''
    && parent.hasAttribute('transform')
  ) {
    parent.setAttribute('visibility', visibility);
  }
}

/** Синхронизирует видимость fill/broken слоёв с числом жизней. */
export function setSvgLivesVisibility(host: ParentNode, lives: number): void {
  const clamped = Math.max(0, Math.min(MAX_PLAYER_LIVES, Math.floor(lives)));

  HEART_SLOT_SVG_IDS.forEach((slot, index) => {
    const hasLife = index < clamped;
    setSvgGroupVisibility(host, slot.fillMask, hasLife);
    setSvgGroupVisibility(host, slot.fillBody, hasLife);
    setSvgGroupVisibility(host, slot.brokenBody, !hasLife);
    setSvgGroupVisibility(host, slot.brokenMask, !hasLife);
  });
}
