import { useCallback, useEffect, useRef, useState } from 'react';
import { VERTICAL_INPUT_KEY } from 'src/presentation/level/constants';
import type { VerticalMoveDirection } from 'src/domain/player';

type VerticalKeysHeld = {
  up: boolean;
  down: boolean;
};

function toVerticalDirection({ up, down }: VerticalKeysHeld): VerticalMoveDirection {
  if (up === down) {
    return 0;
  }
  return up ? 1 : -1;
}

export function useVerticalInput(): {
  getVerticalDirection: () => VerticalMoveDirection;
  verticalDirection: VerticalMoveDirection;
} {
  const verticalKeysHeldRef = useRef<VerticalKeysHeld>({ up: false, down: false });
  const [verticalDirection, setVerticalDirection] = useState<VerticalMoveDirection>(0);

  const syncVerticalDirection = useCallback(() => {
    setVerticalDirection(toVerticalDirection(verticalKeysHeldRef.current));
  }, []);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.code === VERTICAL_INPUT_KEY.UP) {
        verticalKeysHeldRef.current.up = true;
        syncVerticalDirection();
        event.preventDefault();
      }
      if (event.code === VERTICAL_INPUT_KEY.DOWN) {
        verticalKeysHeldRef.current.down = true;
        syncVerticalDirection();
        event.preventDefault();
      }
    };

    const onKeyUp = (event: KeyboardEvent): void => {
      if (event.code === VERTICAL_INPUT_KEY.UP) {
        verticalKeysHeldRef.current.up = false;
        syncVerticalDirection();
      }
      if (event.code === VERTICAL_INPUT_KEY.DOWN) {
        verticalKeysHeldRef.current.down = false;
        syncVerticalDirection();
      }
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, [syncVerticalDirection]);

  const getVerticalDirection = useCallback(
    () => toVerticalDirection(verticalKeysHeldRef.current),
    [],
  );

  return { getVerticalDirection, verticalDirection };
}
