import { useEffect, useLayoutEffect, useRef, type Dispatch, type RefObject, type SetStateAction } from 'react';
import { applyPlayerHitUseCase } from 'src/application/use-cases/applyPlayerHitUseCase';
import { handleObstacleCollisionsUseCase } from 'src/application/use-cases/handleObstacleCollisionsUseCase';
import type { Level } from 'src/domain/level';
import { hasShieldBooster, type Player } from 'src/domain/player';
import { applyObstacleVisibility } from './applyObstacleVisibility';
import { logObstacleCollision } from './logObstacleCollision';

export function useObstacleCollisions(
  level: Level | null,
  player: Player | null,
  setLevel: Dispatch<SetStateAction<Level | null>>,
  setPlayer: Dispatch<SetStateAction<Player | null>>,
  obstaclesHostRef: RefObject<HTMLDivElement | null>,
): void {
  const activeCollisionIdsRef = useRef<Set<string>>(new Set());

  useLayoutEffect(() => {
    const host = obstaclesHostRef.current;
    if (host == null || level == null) {
      return;
    }
    applyObstacleVisibility(host, level);
  }, [level, obstaclesHostRef]);

  useEffect(() => {
    activeCollisionIdsRef.current = new Set();
  }, [level?.id]);

  useEffect(() => {
    if (level == null || player == null) {
      return;
    }

    const result = handleObstacleCollisionsUseCase(
      level,
      player,
      activeCollisionIdsRef.current,
    );

    if (result.newlyConsumed.length > 0) {
      for (const obstacle of result.newlyConsumed) {
        logObstacleCollision(obstacle, player);
      }
      setLevel(result.level);
      setPlayer((previous) => {
        if (previous == null) {
          return previous;
        }
        if (hasShieldBooster(previous)) {
          return previous;
        }
        return applyPlayerHitUseCase(previous, result.newlyConsumed.length);
      });
    }

    activeCollisionIdsRef.current = result.nextActiveCollisionIds;
  }, [level, player, setLevel, setPlayer]);
}
