import { useLayoutEffect, type RefObject } from 'react';
import type { LevelViewState } from 'src/presentation/level/session/levelViewState';
import { applyLevelInteractives } from './applyLevelInteractives';

export function useLevelInteractives(
  interactionsHostRef: RefObject<HTMLDivElement | null>,
  viewState: LevelViewState,
): void {
  useLayoutEffect(() => {
    const host = interactionsHostRef.current;
    if (host == null) {
      return;
    }
    applyLevelInteractives(host, viewState);
  }, [interactionsHostRef, viewState]);
}
