import { useCallback, useMemo, useState } from 'react';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';
import type { AppContext } from 'src/infrastructure/bootstrap';
import { INITIAL_LEVEL_VIEW_STATE, type LevelViewState } from './levelViewState';

export function useLevelSession(app: AppContext, levelId: string) {
  const pack = useMemo(() => app.loadLevelPack(levelId), [app, levelId]);

  const [level, setLevel] = useState<Level | null>(null);
  const [player, setPlayer] = useState<Player | null>(null);
  const [viewState, setViewState] = useState<LevelViewState>(INITIAL_LEVEL_VIEW_STATE);

  const onLevelParsed = useCallback(
    (parsed: Level) => {
      const session = app.startLevel(parsed);
      setLevel(session.level);
      setPlayer(session.player);
      setViewState(INITIAL_LEVEL_VIEW_STATE);
    },
    [app],
  );

  return {
    pack,
    level,
    setLevel,
    player,
    setPlayer,
    viewState,
    setViewState,
    onLevelParsed,
  };
}
