import { detectCollectibleCollisions } from '../../domain/collectibleCollision';
import type { Collectible, Level } from '../../domain/level';
import type { Player } from '../../domain/player';
import { consumeCollectibleUseCase } from './consumeCollectibleUseCase';

export type CollectibleCollisionsResult = {
  level: Level;
  nextActiveCollisionIds: Set<string>;
  newlyConsumed: Collectible[];
};

export function handleCollectibleCollisionsUseCase(
  level: Level,
  player: Player,
  activeCollisionIds: ReadonlySet<string>,
): CollectibleCollisionsResult {
  const colliding = detectCollectibleCollisions(level, player);
  const nextActiveCollisionIds = new Set(colliding.map((collectible) => collectible.id));

  let updatedLevel = level;
  const newlyConsumed: Collectible[] = [];

  for (const collectible of colliding) {
    if (activeCollisionIds.has(collectible.id)) {
      continue;
    }

    updatedLevel = consumeCollectibleUseCase(updatedLevel, collectible.id);
    newlyConsumed.push(collectible);
  }

  return {
    level: updatedLevel,
    nextActiveCollisionIds,
    newlyConsumed,
  };
}
