import { detectBoosterCollisions } from '../../domain/boosterCollision';
import type { Booster, Level } from '../../domain/level';
import type { Player } from '../../domain/player';
import { applyBoosterPickupUseCase } from './applyBoosterPickupUseCase';
import { consumeBoosterUseCase } from './consumeBoosterUseCase';

export type BoosterCollisionsResult = {
  level: Level;
  player: Player;
  nextActiveCollisionIds: Set<string>;
  newlyConsumed: Booster[];
};

export function handleBoosterCollisionsUseCase(
  level: Level,
  player: Player,
  activeCollisionIds: ReadonlySet<string>,
): BoosterCollisionsResult {
  const colliding = detectBoosterCollisions(level, player);
  const nextActiveCollisionIds = new Set(colliding.map((booster) => booster.id));

  let updatedLevel = level;
  let updatedPlayer = player;
  const newlyConsumed: Booster[] = [];

  for (const booster of colliding) {
    if (activeCollisionIds.has(booster.id)) {
      continue;
    }

    updatedLevel = consumeBoosterUseCase(updatedLevel, booster.id);
    updatedPlayer = applyBoosterPickupUseCase(updatedPlayer, booster.assetId);
    newlyConsumed.push(booster);
  }

  return {
    level: updatedLevel,
    player: updatedPlayer,
    nextActiveCollisionIds,
    newlyConsumed,
  };
}
