import { SVG_SELECTOR } from 'src/infrastructure/constants';
import type { LevelViewState } from 'src/presentation/level/session/levelViewState';

export type LevelInteractiveBinding = {
  selector: string;
  apply: (element: SVGElement, viewState: LevelViewState) => void;
};

export const LEVEL_INTERACTIVE_BINDINGS: LevelInteractiveBinding[] = [
  {
    selector: SVG_SELECTOR.DIALOG,
    apply: (element, viewState) => {
      element.style.opacity = viewState.reachedFinish ? '1' : '0';
    },
  },
];
