import { useMemo, useState } from 'react';
import type { CSSProperties } from 'react';
import {
  COURIER_LICENSE_TIERS,
  getCourierLicenseLevel,
  type CourierLicenseTier,
} from '../../domain';
import { t } from '../../i18n';
import { SCREEN_BACKGROUNDS } from './screenBackgroundAssets';
import commonHeaderBackground from '../../infrastructure/assets/Images/commonHeaderBackground.png';
import lobbyInteractArrow from '../../infrastructure/assets/Images/lobbyInteractArrow.png';
import rewardsIcon from '../../infrastructure/assets/Images/rewardsIcon.png';
import {
  HeaderHintBackdrop,
  HeaderHintPopup,
  HeaderHintTitleButton,
  headerHintAnchor,
  headerHintTitleButton,
  useHeaderHintPopup,
} from './HeaderHintPopup';
import { useAppStore } from '../store/appStore';

const TIERS_PER_PAGE = 5;

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  color: '#111',
  position: 'relative',
  backgroundImage: `url(${SCREEN_BACKGROUNDS.license})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const headerStrip: CSSProperties = {
  width: '100%',
  flexShrink: 0,
  marginTop: 3,
  paddingTop: 'max(8px, env(safe-area-inset-top))',
  backgroundImage: `url(${commonHeaderBackground})`,
  backgroundRepeat: 'no-repeat',
  backgroundSize: '100% 100%',
  backgroundPosition: 'center top',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 8,
  minHeight: 52,
  paddingBottom: 12,
  paddingLeft: 16,
  paddingRight: 16,
  boxSizing: 'border-box',
  ...headerHintAnchor,
};

const titleOnHeader: CSSProperties = {
  ...headerHintTitleButton,
  fontSize: 22,
  fontWeight: 900,
  color: '#3a145c',
  textShadow: '0 1px 0 rgba(255,255,255,0.6)',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  overflow: 'hidden',
  padding: '12px 16px 8px',
  boxSizing: 'border-box',
  maxWidth: 520,
  width: '100%',
  margin: '0 auto',
};

const tierList: CSSProperties = {
  flex: 1,
  minWidth: 0,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  gap: 8,
};

const tierRow: CSSProperties = {
  display: 'flex',
  alignItems: 'stretch',
  gap: 8,
  minHeight: 0,
};

const statusMark = (achieved: boolean): CSSProperties => ({
  flexShrink: 0,
  width: 28,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: 18,
  fontWeight: 900,
  color: achieved ? '#1a8f3a' : '#c62828',
  lineHeight: 1,
});

const tierPlate: CSSProperties = {
  flex: 1,
  minWidth: 0,
  padding: '8px 10px',
  borderRadius: 10,
  border: '2px solid #111',
  background: 'rgba(255, 255, 255, 0.92)',
};

const tierTitle: CSSProperties = {
  margin: '0 0 4px',
  fontSize: 14,
  fontWeight: 900,
  color: '#111',
  lineHeight: 1.25,
};

const tierRequirement: CSSProperties = {
  margin: 0,
  display: 'flex',
  alignItems: 'center',
  flexWrap: 'wrap',
  gap: 4,
  fontSize: 12,
  fontWeight: 700,
  color: '#333',
  lineHeight: 1.3,
};

const pageNav: CSSProperties = {
  flexShrink: 0,
  display: 'flex',
  justifyContent: 'center',
  paddingTop: 8,
};

const navBtn: CSSProperties = {
  width: 44,
  height: 32,
  border: 'none',
  borderRadius: 12,
  cursor: 'pointer',
  background: 'rgba(88, 40, 140, 0.35)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
};

function formatRatingDisplay(value: number): string {
  return value.toFixed(1).replace('.', ',');
}

function chunkTiers(tiers: readonly CourierLicenseTier[], pageSize: number): CourierLicenseTier[][] {
  const pages: CourierLicenseTier[][] = [];
  for (let i = 0; i < tiers.length; i += pageSize) {
    pages.push(tiers.slice(i, i + pageSize));
  }
  return pages.length > 0 ? pages : [[]];
}

function tierRequirementLabel(tier: CourierLicenseTier): string {
  return t('game.license.requirement')
    .replace('{rating}', formatRatingDisplay(tier.minAverageRating))
    .replace('{deliveries}', String(tier.minSuccessfulDeliveries));
}

export function GameLicenseScreen() {
  const playerEconomy = useAppStore((s) => s.playerEconomy);
  const { hintOpen, toggleHint, closeHint } = useHeaderHintPopup();
  const [pageIndex, setPageIndex] = useState(0);

  const currentLevel = getCourierLicenseLevel(
    playerEconomy.ratedDeliveriesCount,
    playerEconomy.totalRating,
  );

  const pages = useMemo(() => chunkTiers(COURIER_LICENSE_TIERS, TIERS_PER_PAGE), []);
  const pageCount = pages.length;
  const safePageIndex = pageCount > 0 ? pageIndex % pageCount : 0;
  const currentPage = pages[safePageIndex] ?? [];

  const goNext = () => setPageIndex((i) => (i + 1) % pageCount);

  return (
    <div style={root}>
      {hintOpen ? <HeaderHintBackdrop onClose={closeHint} /> : null}
      <header style={headerStrip}>
        <HeaderHintTitleButton
          hintOpen={hintOpen}
          hintId="game-license-hint"
          onClick={toggleHint}
          style={titleOnHeader}
        >
          {t('game.map.licenseTitle')}
        </HeaderHintTitleButton>
        {hintOpen ? (
          <HeaderHintPopup
            hintId="game-license-hint"
            hintTitle={t('game.license.infoTitle')}
            hintBody={t('game.license.infoBody')}
            onClose={closeHint}
          />
        ) : null}
      </header>
      <div style={body}>
        <div style={tierList}>
          {currentPage.map((tier) => {
            const achieved = currentLevel >= tier.level;
            const statusLabel = achieved ? t('game.license.achieved') : t('game.license.notAchieved');
            return (
              <div key={tier.level} style={tierRow}>
                <span style={statusMark(achieved)} aria-label={statusLabel} title={statusLabel}>
                  {achieved ? '✓' : '✗'}
                </span>
                <div style={tierPlate}>
                  <p style={tierTitle}>
                    {tier.level}. {t(tier.nameKey)}
                  </p>
                  <p style={tierRequirement}>
                    <span>{tierRequirementLabel(tier)}</span>
                    <img src={rewardsIcon} alt="" width={16} height={16} style={{ objectFit: 'contain' }} />
                  </p>
                </div>
              </div>
            );
          })}
        </div>

        {pageCount > 1 ? (
          <div style={pageNav}>
            <button type="button" style={navBtn} onClick={goNext} aria-label={t('game.license.nextPage')}>
              <img
                src={lobbyInteractArrow}
                alt=""
                width={24}
                height={24}
                style={{ transform: 'rotate(90deg)' }}
              />
            </button>
          </div>
        ) : null}
      </div>
    </div>
  );
}
