export type SvgTextWrapOptions = {
  maxWidth: number;
  maxHeight?: number;
  maxLines?: number;
  lineHeight?: number;
  minFontSize?: number;
  x?: number;
};

type TextFontProps = {
  baseFontSize: number;
  fontStyle: string;
  fontWeight: string;
  fontFamily: string;
  strokeWidth: number;
};

let measureCanvas: HTMLCanvasElement | null = null;

function buildFont(style: string, weight: string, size: number, family: string): string {
  return `${style} ${weight} ${size}px ${family}`;
}

function getCanvasFont(textEl: SVGTextElement, fontSize: number): string {
  const style = window.getComputedStyle(textEl);
  return buildFont(style.fontStyle, style.fontWeight, fontSize, style.fontFamily);
}

function measureTextWidth(font: string, text: string): number {
  if (measureCanvas == null) {
    measureCanvas = document.createElement('canvas');
  }
  const ctx = measureCanvas.getContext('2d');
  if (ctx == null) {
    return text.length * 10;
  }
  ctx.font = font;
  return ctx.measureText(text).width;
}

function readOriginNumber(textEl: SVGTextElement, attr: string, fallback: number): number {
  const stored = textEl.getAttribute(attr);
  if (stored != null && stored !== '') {
    return Number.parseFloat(stored);
  }
  textEl.setAttribute(attr, String(fallback));
  return fallback;
}

function getTextFontProps(textEl: SVGTextElement): TextFontProps {
  const style = window.getComputedStyle(textEl);
  const parsedSize =
    Number.parseFloat(textEl.getAttribute('font-size') ?? '') ||
    Number.parseFloat(style.fontSize) ||
    16;
  const parsedStroke =
    Number.parseFloat(textEl.getAttribute('stroke-width') ?? '') ||
    Number.parseFloat(style.strokeWidth) ||
    0;

  const baseFontSize = readOriginNumber(textEl, 'data-origin-font-size', parsedSize);
  const strokeWidth = readOriginNumber(textEl, 'data-origin-stroke-width', parsedStroke);

  return {
    baseFontSize,
    fontStyle: style.fontStyle,
    fontWeight: style.fontWeight,
    fontFamily: style.fontFamily,
    strokeWidth,
  };
}

function fitWithEllipsis(line: string, font: string, maxWidth: number): string {
  if (measureTextWidth(font, line) <= maxWidth) {
    return line;
  }
  let truncated = line;
  while (truncated.length > 1 && measureTextWidth(font, `${truncated}…`) > maxWidth) {
    truncated = truncated.slice(0, -1);
  }
  return `${truncated}…`;
}

function splitIntoLines(
  text: string,
  font: string,
  maxWidth: number,
  maxLines?: number,
): string[] {
  const lines: string[] = [];

  for (const paragraph of text.split('\n')) {
    const words = paragraph.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) {
      continue;
    }

    let current = '';
    for (const word of words) {
      const candidate = current === '' ? word : `${current} ${word}`;
      if (measureTextWidth(font, candidate) > maxWidth && current !== '') {
        lines.push(current);
        current = word;
        if (maxLines != null && lines.length >= maxLines) {
          lines[maxLines - 1] = fitWithEllipsis(lines[maxLines - 1], font, maxWidth);
          return lines.slice(0, maxLines);
        }
      } else {
        current = candidate;
      }
    }

    if (current !== '') {
      lines.push(current);
      if (maxLines != null && lines.length >= maxLines) {
        lines[maxLines - 1] = fitWithEllipsis(lines[maxLines - 1], font, maxWidth);
        return lines.slice(0, maxLines);
      }
    }
  }

  return lines.length > 0 ? lines : [''];
}

function maxLinesForHeight(
  maxHeight: number | undefined,
  fontSize: number,
  lineHeightRatio: number,
  explicitMaxLines?: number,
): number {
  if (maxHeight == null) {
    return explicitMaxLines ?? Number.MAX_SAFE_INTEGER;
  }
  const fromHeight = Math.max(1, Math.floor(maxHeight / (fontSize * lineHeightRatio)));
  if (explicitMaxLines != null) {
    return Math.min(explicitMaxLines, fromHeight);
  }
  return fromHeight;
}

function fitsInBlock(
  lines: string[],
  font: string,
  maxWidth: number,
  maxHeight: number | undefined,
  fontSize: number,
  lineHeightRatio: number,
): boolean {
  if (lines.length === 0) {
    return true;
  }

  const widestLine = Math.max(...lines.map((line) => measureTextWidth(font, line)));
  if (widestLine > maxWidth) {
    return false;
  }

  if (maxHeight != null) {
    const totalHeight = fontSize * lineHeightRatio * lines.length;
    if (totalHeight > maxHeight + 0.5) {
      return false;
    }
  }

  return true;
}

function fitTextInBlock(
  text: string,
  fontProps: TextFontProps,
  options: SvgTextWrapOptions,
): { fontSize: number; lines: string[] } {
  const lineHeightRatio = options.lineHeight ?? 1.2;
  const minFontSize = options.minFontSize ?? Math.max(12, Math.round(fontProps.baseFontSize * 0.45));

  for (let fontSize = fontProps.baseFontSize; fontSize >= minFontSize; fontSize -= 1) {
    const font = buildFont(
      fontProps.fontStyle,
      fontProps.fontWeight,
      fontSize,
      fontProps.fontFamily,
    );
    const allowedLines = maxLinesForHeight(
      options.maxHeight,
      fontSize,
      lineHeightRatio,
      options.maxLines,
    );
    const lines = splitIntoLines(text, font, options.maxWidth);

    if (lines.length <= allowedLines && fitsInBlock(lines, font, options.maxWidth, options.maxHeight, fontSize, lineHeightRatio)) {
      return { fontSize, lines };
    }
  }

  const fontSize = minFontSize;
  const font = buildFont(
    fontProps.fontStyle,
    fontProps.fontWeight,
    fontSize,
    fontProps.fontFamily,
  );
  const allowedLines = maxLinesForHeight(
    options.maxHeight,
    fontSize,
    lineHeightRatio,
    options.maxLines,
  );
  const lines = splitIntoLines(text, font, options.maxWidth, allowedLines);

  return { fontSize, lines };
}

export function setSvgWrappedText(
  container: ParentNode,
  elementId: string,
  text: string,
  options: SvgTextWrapOptions,
): void {
  const textEl = container.querySelector(`#${elementId}`);
  if (!(textEl instanceof SVGTextElement)) {
    return;
  }

  const fontProps = getTextFontProps(textEl);
  const { fontSize, lines } = fitTextInBlock(text, fontProps, options);
  const lineHeight = fontSize * (options.lineHeight ?? 1.2);

  const firstTspan = textEl.querySelector('tspan');
  const x = String(options.x ?? firstTspan?.getAttribute('x') ?? '0');
  const y = firstTspan?.getAttribute('y') ?? '0';

  textEl.setAttribute('font-size', String(fontSize));
  if (fontProps.strokeWidth > 0) {
    const strokeScale = fontSize / fontProps.baseFontSize;
    textEl.setAttribute('stroke-width', String(fontProps.strokeWidth * strokeScale));
  }

  textEl.textContent = '';

  lines.forEach((line, index) => {
    const tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
    tspan.setAttribute('x', x);
    if (index === 0) {
      tspan.setAttribute('y', y);
    } else {
      tspan.setAttribute('dy', String(lineHeight));
    }
    tspan.textContent = line;
    textEl.appendChild(tspan);
  });
}
