import { LANE_MIN, LANE_MAX } from '../../domain/constants';
import type { Player, VerticalMoveDirection } from '../../domain/player';
import { LANE_SPEED_PER_SEC } from '../constants';

export type { VerticalMoveDirection };

export function movePlayerVerticalUseCase(
  player: Player,
  direction: VerticalMoveDirection,
  deltaSeconds: number,
): Player {
  if (direction === 0) {
    return player;
  }

  const nextLane = Math.min(
    LANE_MAX,
    Math.max(LANE_MIN, player.lane + direction * LANE_SPEED_PER_SEC * deltaSeconds),
  );

  if (nextLane === player.lane) {
    return player;
  }

  return { ...player, lane: nextLane };
}
