import { useRef, type Dispatch, type SetStateAction } from 'react';
import type { Level } from 'src/domain/level';
import type { LevelPack } from 'src/infrastructure/levels/levelPack';
import type { AppContext } from 'src/infrastructure/bootstrap';
import type { LevelViewState } from 'src/presentation/level/layout/playfieldConfig';
import type { PlayfieldConfig } from 'src/presentation/level/layout/playfieldConfig';
import {
  computeFallbackLayout,
  computeLevelLayout,
  type LevelCanvasLayout,
} from 'src/presentation/level/layout/computeLevelLayout';
import { useBoosterCollisions } from 'src/presentation/level/boosters/useBoosterCollisions';
import { useCollectibleCollisions } from 'src/presentation/level/collectibles/useCollectibleCollisions';
import { useLevelInteractives } from 'src/presentation/level/interactives/useLevelInteractives';
import { useObstacleCollisions } from 'src/presentation/level/obstacles/useObstacleCollisions';
import { useParseLevelFromDom } from 'src/presentation/level/parsing/useParseLevelFromDom';
import type { CourierId } from 'src/domain/courier';
import type { VerticalMoveDirection } from 'src/domain/player';
import type { Player } from 'src/domain/player';
import { LEVEL_LAYER_Z_INDEX } from 'src/presentation/level/constants';
import { LevelLayer } from './LevelLayer';
import { PlayerSprite } from './PlayerSprite';

type LevelCanvasProps = {
  pack: LevelPack;
  level: Level | null;
  setLevel: Dispatch<SetStateAction<Level | null>>;
  player: Player | null;
  setPlayer: Dispatch<SetStateAction<Player | null>>;
  viewState: LevelViewState;
  setViewState: Dispatch<SetStateAction<LevelViewState>>;
  playfield: PlayfieldConfig;
  app: AppContext;
  onLevelParsed: (level: Level) => void;
  verticalDirection: VerticalMoveDirection;
  courierId: CourierId;
};

export function LevelCanvas({
  pack,
  level,
  setLevel,
  player,
  setPlayer,
  viewState,
  setViewState,
  playfield,
  app,
  onLevelParsed,
  verticalDirection,
  courierId,
}: LevelCanvasProps) {
  const interactionsHostRef = useRef<HTMLDivElement | null>(null);
  const obstaclesHostRef = useRef<HTMLDivElement | null>(null);
  const collectiblesHostRef = useRef<HTMLDivElement | null>(null);
  const boostersHostRef = useRef<HTMLDivElement | null>(null);

  useParseLevelFromDom(
    pack.id,
    pack.obstacleAssets,
    pack.collectibleAssets,
    pack.boosterAssets,
    app,
    { interactionsHostRef, obstaclesHostRef, collectiblesHostRef, boostersHostRef },
    onLevelParsed,
  );
  useLevelInteractives(interactionsHostRef, viewState);
  useCollectibleCollisions(level, player, setLevel, setViewState, collectiblesHostRef);
  useBoosterCollisions(level, player, setLevel, setPlayer, boostersHostRef);
  useObstacleCollisions(level, player, setLevel, setPlayer, obstaclesHostRef);

  const layout: LevelCanvasLayout =
    level != null && player != null
      ? computeLevelLayout(level, playfield, player)
      : computeFallbackLayout(pack, playfield);

  return (
    <>
      <LevelLayer
        component={pack.layers.background}
        layout={layout}
        zIndex={LEVEL_LAYER_Z_INDEX.BACKGROUND}
      />
      <LevelLayer
        component={pack.layers.collectibles}
        layout={layout}
        zIndex={LEVEL_LAYER_Z_INDEX.COLLECTIBLES}
        hostRef={collectiblesHostRef}
      />
      <LevelLayer
        component={pack.layers.boosters}
        layout={layout}
        zIndex={LEVEL_LAYER_Z_INDEX.BOOSTERS}
        hostRef={boostersHostRef}
      />
      <LevelLayer
        component={pack.layers.obstacles}
        layout={layout}
        zIndex={LEVEL_LAYER_Z_INDEX.OBSTACLES}
        hostRef={obstaclesHostRef}
      />
      <LevelLayer
        component={pack.layers.foreground}
        layout={layout}
        zIndex={LEVEL_LAYER_Z_INDEX.FOREGROUND}
      />
      <LevelLayer
        component={pack.layers.interact}
        layout={layout}
        zIndex={LEVEL_LAYER_Z_INDEX.INTERACTIONS}
        pointerEvents="auto"
        hostRef={interactionsHostRef}
      />
      {level != null && player != null && (
        <PlayerSprite
          level={level}
          player={player}
          layout={layout}
          verticalDirection={verticalDirection}
          courierId={courierId}
        />
      )}
    </>
  );
}
