import { GIANT_IDS, type GiantId } from '../ids/ids';

/**
 * Допустимые препятствия по гиганту (GDD, раздел «Препятствия»).
 * Стабильные id для уровней и data-oriented спавна.
 */
export const GIANT_ALLOWED_OBSTACLES = {
  swami: ['swarm_copters', 'decree_scrolls', 'king_crowns'],
  rose_observatory: [
    'comets',
    'mountain_mist',
    'shooting_stars',
    'weave_stars',
    'hard_caramels',
  ],
  drakocha: ['lava_towers', 'chili_peppers', 'soundwaves', 'heat_zone'],
  yeti: [
    'hanging_icicles',
    'snowflake_drifts',
    'snowball_hail',
    'ice_sculptures',
    'ice_cream_traps',
    'frozen_notes',
    'blizzard_cold',
  ],
  mona: [
    'kraken_snare',
    'dolphin_playmates',
    'foam_waves',
    'shrinking_growing_bottles',
  ],
  captain_duck: ['passenger_dolphins', 'wake_breakers', 'pool_orbs', 'sea_whirlpool'],
  serge: ['serge_minions', 'ink_poems'],
  factor: ['sand_wall', 'prairie_weeds', 'chimney_smoke', 'loose_cogs'],
  sol: ['heat_haze_clouds', 'sky_choppers'],
  luna_mu: ['phantom_lights', 'dark_islands', 'meteor_shower', 'night_comets'],
  haunted_house: ['phantom_lights', 'dark_islands', 'meteor_shower', 'night_comets'],
  uncle_willy: ['spectacle_glare', 'faded_decrees', 'memory_photos'],
} as const satisfies { [K in GiantId]: readonly string[] };

export type ObstacleKind = (typeof GIANT_ALLOWED_OBSTACLES)[GiantId][number];

export const ALL_OBSTACLE_KINDS: ObstacleKind[] = Array.from(
  new Set(GIANT_IDS.flatMap((g) => [...GIANT_ALLOWED_OBSTACLES[g]])),
) as ObstacleKind[];

export function getAllowedObstaclesForGiant(giantId: GiantId): readonly ObstacleKind[] {
  return GIANT_ALLOWED_OBSTACLES[giantId];
}

export function isObstacleKind(value: string): value is ObstacleKind {
  return (ALL_OBSTACLE_KINDS as readonly string[]).includes(value);
}

export function isObstacleAllowedForGiant(giantId: GiantId, obstacle: ObstacleKind): boolean {
  return (GIANT_ALLOWED_OBSTACLES[giantId] as readonly string[]).includes(obstacle);
}
