import type { Player } from '../../domain/player';

/** Уменьшает таймер активного бустера; по истечении сбрасывает эффект. */
export function tickPlayerBoosterUseCase(player: Player, deltaSeconds: number): Player {
  const active = player.activeBooster;
  if (active == null) {
    return player;
  }

  const remainingSeconds = active.remainingSeconds - deltaSeconds;
  if (remainingSeconds <= 0) {
    return { ...player, activeBooster: null };
  }

  if (remainingSeconds === active.remainingSeconds) {
    return player;
  }

  return {
    ...player,
    activeBooster: {
      kind: active.kind,
      remainingSeconds,
    },
  };
}
