import type { FC, SVGProps } from 'react';
import { ReactComponent as ClaudiSvg } from 'src/infrastructure/assets/characters/claudi.svg';
import { ReactComponent as EddySvg } from 'src/infrastructure/assets/characters/eddy.svg';
import { ReactComponent as TuchiSvg } from 'src/infrastructure/assets/characters/tuchi.svg';
import { ReactComponent as UfoSvg } from 'src/infrastructure/assets/characters/ufo.svg';
import { ReactComponent as RockSvg } from 'src/infrastructure/assets/characters/rock.svg';
import { ReactComponent as VallSvg } from 'src/infrastructure/assets/characters/vall.svg';
import { ReactComponent as ClaudiShieldSvg } from 'src/infrastructure/assets/characters/boosters/shield/claudi_shield.svg';
import { ReactComponent as EddyShieldSvg } from 'src/infrastructure/assets/characters/boosters/shield/eddy_shield.svg';
import { ReactComponent as TuchiShieldSvg } from 'src/infrastructure/assets/characters/boosters/shield/tuchi_shield.svg';
import { ReactComponent as UfoShieldSvg } from 'src/infrastructure/assets/characters/boosters/shield/ufo_shield.svg';
import { ReactComponent as RockShieldSvg } from 'src/infrastructure/assets/characters/boosters/shield/rock_shield.svg';
import { ReactComponent as VallShieldSvg } from 'src/infrastructure/assets/characters/boosters/shield/vall_shield.svg';
import { ReactComponent as ClaudiSpeedSvg } from 'src/infrastructure/assets/characters/boosters/speed/claudi_speed.svg';
import { ReactComponent as EddySpeedSvg } from 'src/infrastructure/assets/characters/boosters/speed/eddy_speed.svg';
import { ReactComponent as TuchiSpeedSvg } from 'src/infrastructure/assets/characters/boosters/speed/tuchi_speed.svg';
import { ReactComponent as UfoSpeedSvg } from 'src/infrastructure/assets/characters/boosters/speed/ufo_speed.svg';
import { ReactComponent as RockSpeedSvg } from 'src/infrastructure/assets/characters/boosters/speed/rock_speed.svg';
import { ReactComponent as VallSpeedSvg } from 'src/infrastructure/assets/characters/boosters/speed/vall_speed.svg';
import { getCourierById } from 'src/domain/couriers';
import type { CourierId } from 'src/domain/courier';
import type { BoosterKind } from 'src/domain/level';

export type CourierSpriteComponent = FC<SVGProps<SVGSVGElement>>;

export type CourierSpriteVariant = 'normal' | BoosterKind;

const COURIER_SPRITE_BY_GROUP_ID: Record<string, CourierSpriteComponent> = {
  claudi: ClaudiSvg,
  eddy: EddySvg,
  tuchi: TuchiSvg,
  ufo: UfoSvg,
  vall: VallSvg,
  rock: RockSvg,
};

const COURIER_SHIELD_SPRITE_BY_GROUP_ID: Record<string, CourierSpriteComponent> = {
  claudi: ClaudiShieldSvg,
  eddy: EddyShieldSvg,
  tuchi: TuchiShieldSvg,
  ufo: UfoShieldSvg,
  vall: VallShieldSvg,
  rock: RockShieldSvg,
};

const COURIER_SPEED_SPRITE_BY_GROUP_ID: Record<string, CourierSpriteComponent> = {
  claudi: ClaudiSpeedSvg,
  eddy: EddySpeedSvg,
  tuchi: TuchiSpeedSvg,
  ufo: UfoSpeedSvg,
  vall: VallSpeedSvg,
  rock: RockSpeedSvg,
};

const DEFAULT_COURIER_SPRITE = VallSvg;

export function getCourierSpriteComponent(
  courierId: CourierId,
  variant: CourierSpriteVariant = 'normal',
): CourierSpriteComponent {
  const { svgGroupId } = getCourierById(courierId);

  if (variant === 'shield') {
    return COURIER_SHIELD_SPRITE_BY_GROUP_ID[svgGroupId] ?? DEFAULT_COURIER_SPRITE;
  }
  if (variant === 'speed') {
    return COURIER_SPEED_SPRITE_BY_GROUP_ID[svgGroupId] ?? DEFAULT_COURIER_SPRITE;
  }

  return COURIER_SPRITE_BY_GROUP_ID[svgGroupId] ?? DEFAULT_COURIER_SPRITE;
}
