import type { GiantId } from '../../domain';
import { GIANT_PORTRAIT_BY_ID } from '../game/giantPortraits';
import { setSvgWrappedText, type SvgTextWrapOptions } from './svgTextWrap';

const SVG_NAMESPACE = 'http://www.w3.org/2000/svg';
const PORTRAIT_WRAPPER_ATTR = 'data-dynamic-giant-portrait';
const PORTRAIT_CLIP_ID = 'giant_icon_portrait_clip';

/** Рамки текстовых блоков из макета `new_delivery_screen.svg` (viewBox 1080×1920). */
export const DELIVERY_SCREEN_LABEL_LAYOUT: Record<string, SvgTextWrapOptions> = {
  title_label: { maxWidth: 580, maxHeight: 140, maxLines: 2, minFontSize: 56 },
  giant_name: { maxWidth: 318, maxHeight: 58, maxLines: 2, minFontSize: 26, x: 536 },
  description_label: { maxWidth: 560, maxHeight: 270, lineHeight: 1.3, minFontSize: 22 },
  title_1_label: { maxWidth: 480, maxHeight: 62, maxLines: 2, minFontSize: 34 },
  green_button_text: { maxWidth: 640, maxHeight: 130, maxLines: 2, minFontSize: 52 },
};

export type DeliveryScreenLabels = {
  title: string;
  giantName: string;
  description: string;
  whatInside: string;
  takeOrder: string;
};

function copyRectGeometry(from: Element, to: Element): void {
  for (const attr of ['x', 'y', 'width', 'height', 'rx', 'ry'] as const) {
    const value = from.getAttribute(attr);
    if (value != null) {
      to.setAttribute(attr, value);
    } else {
      to.removeAttribute(attr);
    }
  }
}

/** Подставляет портрет гиганта в `#giant_icon`, не трогая остальное содержимое группы. */
export function setSvgGiantPortrait(container: ParentNode, giantId: GiantId): void {
  const iconGroup = container.querySelector('#giant_icon');
  if (
    iconGroup == null ||
    iconGroup.namespaceURI !== SVG_NAMESPACE ||
    iconGroup.localName !== 'g'
  ) {
    return;
  }

  const frame = iconGroup.querySelector('rect');
  if (frame == null || frame.namespaceURI !== SVG_NAMESPACE || frame.localName !== 'rect') {
    return;
  }

  let wrapper = iconGroup.querySelector(`g[${PORTRAIT_WRAPPER_ATTR}]`);
  if (wrapper == null || wrapper.namespaceURI !== SVG_NAMESPACE || wrapper.localName !== 'g') {
    wrapper = document.createElementNS(SVG_NAMESPACE, 'g');
    wrapper.setAttribute(PORTRAIT_WRAPPER_ATTR, 'true');
    iconGroup.appendChild(wrapper);
  }

  const transform = frame.getAttribute('transform');
  if (transform != null) {
    wrapper.setAttribute('transform', transform);
  } else {
    wrapper.removeAttribute('transform');
  }

  let clipPath = wrapper.querySelector('clipPath');
  if (clipPath == null) {
    clipPath = document.createElementNS(SVG_NAMESPACE, 'clipPath');
    clipPath.setAttribute('id', PORTRAIT_CLIP_ID);
    const clipRect = document.createElementNS(SVG_NAMESPACE, 'rect');
    clipPath.appendChild(clipRect);
    wrapper.appendChild(clipPath);
  }

  const clipRect = clipPath.querySelector('rect');
  if (clipRect != null && clipRect.namespaceURI === SVG_NAMESPACE && clipRect.localName === 'rect') {
    copyRectGeometry(frame, clipRect);
  }

  let image = wrapper.querySelector('image');
  if (image == null || image.namespaceURI !== SVG_NAMESPACE || image.localName !== 'image') {
    image = document.createElementNS(SVG_NAMESPACE, 'image');
    wrapper.appendChild(image);
  }

  image.setAttribute('href', GIANT_PORTRAIT_BY_ID[giantId]);
  image.setAttribute('x', frame.getAttribute('x') ?? '0');
  image.setAttribute('y', frame.getAttribute('y') ?? '0');
  image.setAttribute('width', frame.getAttribute('width') ?? '0');
  image.setAttribute('height', frame.getAttribute('height') ?? '0');
  image.setAttribute('preserveAspectRatio', 'xMidYMid slice');
  image.setAttribute('clip-path', `url(#${PORTRAIT_CLIP_ID})`);
}

/**
 * Обновляет только текстовые подписи и портрет гиганта.
 * `#delivery_item_container` и прочая графика макета не изменяются.
 */
export function applyDeliveryScreenSvg(
  container: ParentNode,
  labels: DeliveryScreenLabels,
  giantId: GiantId | null,
): void {
  setSvgWrappedText(container, 'title_label', labels.title, DELIVERY_SCREEN_LABEL_LAYOUT.title_label);
  setSvgWrappedText(container, 'giant_name', labels.giantName, DELIVERY_SCREEN_LABEL_LAYOUT.giant_name);
  setSvgWrappedText(
    container,
    'description_label',
    labels.description,
    DELIVERY_SCREEN_LABEL_LAYOUT.description_label,
  );
  setSvgWrappedText(container, 'title_1_label', labels.whatInside, DELIVERY_SCREEN_LABEL_LAYOUT.title_1_label);
  setSvgWrappedText(
    container,
    'green_button_text',
    labels.takeOrder,
    DELIVERY_SCREEN_LABEL_LAYOUT.green_button_text,
  );

  if (giantId != null) {
    setSvgGiantPortrait(container, giantId);
  }
}
