import { CLAUDI_STICKERS, LEGACY_CLAUDI_STICKER_IDS, type PlayerEconomyState } from '../../domain';

export type SevenDayTaskDay = {
  day: number;
  completed: boolean;
  isToday: boolean;
};

export type GameTaskItem = {
  id: string;
  title: string;
  progressText: string;
  completed: boolean;
  kind: 'real_7_day' | 'urgent_mock' | 'quiz_mock';
};

export type ClaudiSticker = {
  id: string;
  name: string;
  emoji: string;
  unlocked: boolean;
  hint: string;
  kind: 'positive' | 'negative';
};

export type LeaderboardEntry = {
  rank: number;
  name: string;
  score: number;
  isPlayer?: boolean;
};

export type LeaderboardsBundle = {
  seasonId: string;
  seasonTitle: string;
  seasonEndsAtIso: string;
  weekly: LeaderboardEntry[];
  allTime: LeaderboardEntry[];
};

const DAY_MS = 24 * 60 * 60 * 1000;

function isoDateFromMs(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10);
}

function dayDiff(fromIso: string, toIso: string): number | null {
  const from = Date.parse(fromIso);
  const to = Date.parse(toIso);
  if (!Number.isFinite(from) || !Number.isFinite(to)) {
    return null;
  }
  return Math.floor((to - from) / DAY_MS);
}

function getActiveStreakDays(state: PlayerEconomyState, nowMs: number): number {
  if (state.lastLoginDate == null) {
    return 0;
  }
  const todayIso = isoDateFromMs(nowMs);
  const diff = dayDiff(state.lastLoginDate, todayIso);
  if (diff == null) {
    return 0;
  }
  if (diff <= 1) {
    return Math.max(0, Math.min(7, Math.floor(state.streakDays)));
  }
  return 0;
}

export function buildSevenDayTask(state: PlayerEconomyState, nowMs = Date.now()): {
  progress: SevenDayTaskDay[];
  completedDays: number;
} {
  const done = getActiveStreakDays(state, nowMs);
  const currentDay = Math.min(7, done + 1);
  const progress: SevenDayTaskDay[] = [];
  for (let day = 1; day <= 7; day += 1) {
    progress.push({
      day,
      completed: day <= done,
      isToday: day === currentDay && done < 7,
    });
  }
  return { progress, completedDays: done };
}

export function buildGameTasks(state: PlayerEconomyState, nowMs = Date.now()): GameTaskItem[] {
  const sevenDay = buildSevenDayTask(state, nowMs);
  const urgentTotal = Math.max(1, state.deliveryPool.filter((d) => d.urgency === 'urgent').length);
  const urgentDone = Math.min(urgentTotal, state.urgentCompletedCount ?? 0);
  const quizTotal = 3;
  const quizDone = Math.min(quizTotal, Math.floor(state.totalRating / 60));
  return [
    {
      id: 'real_7_day',
      title: '7-day real',
      progressText: `${sevenDay.completedDays}/7`,
      completed: sevenDay.completedDays >= 7,
      kind: 'real_7_day',
    },
    {
      id: 'urgent_mock',
      title: 'urgent mock',
      progressText: `${urgentDone}/${urgentTotal}`,
      completed: urgentDone >= urgentTotal,
      kind: 'urgent_mock',
    },
    {
      id: 'quiz_mock',
      title: 'quiz mock',
      progressText: `${quizDone}/${quizTotal}`,
      completed: quizDone >= quizTotal,
      kind: 'quiz_mock',
    },
  ];
}

export function buildClaudiStickers(state: PlayerEconomyState): ClaudiSticker[] {
  const unlockedSet = new Set(
    (state.stickers ?? []).map((s) => LEGACY_CLAUDI_STICKER_IDS[s.id] ?? s.id),
  );
  return CLAUDI_STICKERS.map((def) => ({
    id: def.id,
    name: def.name,
    emoji: def.emoji,
    hint: def.hint,
    kind: def.kind,
    unlocked: unlockedSet.has(def.id),
  }));
}

function injectPlayer(entries: LeaderboardEntry[], playerScore: number, playerName: string): LeaderboardEntry[] {
  const withPlayer = [...entries, { rank: 0, name: playerName, score: playerScore, isPlayer: true }];
  withPlayer.sort((a, b) => b.score - a.score);
  return withPlayer.slice(0, 10).map((e, idx) => ({ ...e, rank: idx + 1 }));
}

function seasonInfo(nowMs: number): { id: string; title: string; endsAtIso: string } {
  const d = new Date(nowMs);
  const year = d.getUTCFullYear();
  const month = d.getUTCMonth();
  const quarter = Math.floor(month / 3) + 1;
  const nextQuarterMonth = quarter * 3;
  const nextQuarterStart = Date.UTC(year, nextQuarterMonth, 1, 0, 0, 0, 0);
  return {
    id: `${year}-Q${quarter}`,
    title: `Сезон ${year} Q${quarter}`,
    endsAtIso: new Date(nextQuarterStart).toISOString(),
  };
}

export function buildLeaderboards(state: PlayerEconomyState, nowMs = Date.now()): LeaderboardsBundle {
  const season = seasonInfo(nowMs);
  const weeklyBase: LeaderboardEntry[] = [
    { rank: 1, name: 'Rock', score: 620 },
    { rank: 2, name: 'Eddy', score: 540 },
    { rank: 3, name: 'Mona', score: 500 },
    { rank: 4, name: 'Yeti', score: 430 },
  ];
  const allTimeBase: LeaderboardEntry[] = [
    { rank: 1, name: 'Swami', score: 4000 },
    { rank: 2, name: 'Factor', score: 3600 },
    { rank: 3, name: 'Rock', score: 2850 },
    { rank: 4, name: 'Eddy', score: 2400 },
  ];

  return {
    seasonId: season.id,
    seasonTitle: season.title,
    seasonEndsAtIso: season.endsAtIso,
    weekly: injectPlayer(weeklyBase, Math.max(0, Math.round(state.totalRating)), 'Вы'),
    allTime: injectPlayer(
      allTimeBase,
      Math.max(0, Math.round(state.totalRating + state.perfectDeliveriesCount * 80)),
      'Вы',
    ),
  };
}

