import { useLayoutEffect, useState } from 'react';
import type { GiantId } from '../../domain';
import { parseMapGiantAnchorsFromLayout, type MapGiantAnchor } from './parseMapGiantAnchors';

export function useMapGiantAnchors(
  svgRoot: SVGSVGElement | null,
  mapContainer: HTMLElement | null,
): Partial<Record<GiantId, MapGiantAnchor>> {
  const [anchors, setAnchors] = useState<Partial<Record<GiantId, MapGiantAnchor>>>({});

  useLayoutEffect(() => {
    if (svgRoot == null || mapContainer == null) {
      return;
    }

    let cancelled = false;
    let rafId = 0;

    const measure = () => {
      if (cancelled) {
        return;
      }
      const next = parseMapGiantAnchorsFromLayout(svgRoot, mapContainer);
      if (Object.keys(next).length > 0) {
        setAnchors(next);
        return;
      }
      rafId = requestAnimationFrame(measure);
    };

    measure();

    const ro =
      typeof ResizeObserver !== 'undefined'
        ? new ResizeObserver(() => {
            if (!cancelled) {
              setAnchors(parseMapGiantAnchorsFromLayout(svgRoot, mapContainer));
            }
          })
        : null;
    ro?.observe(mapContainer);
    ro?.observe(svgRoot);

    return () => {
      cancelled = true;
      cancelAnimationFrame(rafId);
      ro?.disconnect();
    };
  }, [mapContainer, svgRoot]);

  return anchors;
}
