import {
  computeFitLevelCanvasLayout,
  computeSvgLevelCanvasLayout,
  type LevelCanvasLayout,
} from 'src/presentation/shared/layout/parseLevelLayout';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';
import type { LevelPack } from 'src/infrastructure/levels/levelPack';
import type { PlayfieldConfig } from './playfieldConfig';

export type { LevelCanvasLayout };

export function computeLevelLayout(
  level: Level,
  playfield: PlayfieldConfig,
  player: Player,
): LevelCanvasLayout {
  return computeSvgLevelCanvasLayout(
    {
      playfieldHeightPx: playfield.heightPx,
      courierScreenX: playfield.courierScreenX,
    },
    {
      viewBoxWidth: level.viewBox.width,
      viewBoxHeight: level.viewBox.height,
      spawnSvgX: level.spawnSvgX,
    },
    player.worldS,
  );
}

export function computeFallbackLayout(
  pack: LevelPack,
  playfield: PlayfieldConfig,
): LevelCanvasLayout {
  return computeFitLevelCanvasLayout(playfield.widthPx, playfield.heightPx, {
    viewBoxWidth: pack.viewBox.width,
    viewBoxHeight: pack.viewBox.height,
  });
}
