import type { LevelPack } from './levelPack';
import { LEVEL_IDS } from '../constants';
import { captainDuckLevelPack } from './captainDuckLevelPack';
import { drakochiLevelPack } from './drakochiLevelPack';
import { faktorPlantLevelPack } from './faktorPlantLevelPack';
import { monaLevelPack } from './monaLevelPack';
import { roseObservatoryLevelPack } from './roseObservatoryLevelPack';
import { rulersSvamiLevelPack } from './rulersSvamiLevelPack';
import { solLevelPack } from './solLevelPack';
import { willyLevelPack } from './willyLevelPack';
import { yetiLevelPack } from './yetiLevelPack';

const levelPacks: Record<string, LevelPack> = {
  [LEVEL_IDS.WILLY]: willyLevelPack,
  [LEVEL_IDS.MONA]: monaLevelPack,
  [LEVEL_IDS.CAPTAIN_DUCK]: captainDuckLevelPack,
  [LEVEL_IDS.ROSE_OBSERVATORY]: roseObservatoryLevelPack,
  [LEVEL_IDS.FAKTOR_PLANT]: faktorPlantLevelPack,
  [LEVEL_IDS.RULERS_SVAMI]: rulersSvamiLevelPack,
  [LEVEL_IDS.YETI]: yetiLevelPack,
  [LEVEL_IDS.DRAKOCHI]: drakochiLevelPack,
  [LEVEL_IDS.SOL]: solLevelPack,
};

export function getLevelPack(id: string): LevelPack | undefined {
  return levelPacks[id];
}

export type { LevelPack, SvgComponent } from './levelPack';
export {
  captainDuckLevelPack,
  drakochiLevelPack,
  faktorPlantLevelPack,
  monaLevelPack,
  roseObservatoryLevelPack,
  rulersSvamiLevelPack,
  solLevelPack,
  willyLevelPack,
  yetiLevelPack,
};
