import type { GiantId, MissionRef } from '../domain';

/** v2 level pack ids from `v2/new_src/infrastructure/constants.ts`. */
const V2_LEVEL_ID_BY_GIANT: Partial<Record<GiantId, string>> = {
  uncle_willy: 'willy',
  captain_duck: 'captainDuck',
  mona: 'mona',
  rose_observatory: 'roseObservatory',
  factor: 'faktorPlant',
  swami: 'rulersSvami',
  drakocha: 'drakochi',
  yeti: 'yeti',
  sol: 'sol',
};

const V2_LEVEL_FALLBACK = 'willy';

export function getV2LevelIdForGiant(giantId: GiantId): string {
  return V2_LEVEL_ID_BY_GIANT[giantId] ?? V2_LEVEL_FALLBACK;
}

/** Level geometry is per giant; orderIndex does not affect which pack is used. */
export function getV2LevelIdForMission(mission: MissionRef): string {
  return getV2LevelIdForGiant(mission.giantId);
}
