import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { KeyboardEvent, PointerEvent } from 'react';
import type { CSSProperties } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  deliveryGiantMessageId,
  deliveryGiantMessageI18nKey,
  isPoolEntryDelivered,
  shouldShowDailyPackCompleteModal,
  type GiantId,
} from '../../domain';
import { t } from '../../i18n';
import { GameStatusBanner } from '../components/GameStatusBanner';
import { useAppStore } from '../store/appStore';
import { ReactComponent as MapSvg } from '../../infrastructure/assets/Images/map.svg';
import lobbyInteractArrow from '../../infrastructure/assets/Images/lobbyInteractArrow.png';
import { resolveMapDeliveryPoint } from './mapContent';
import { getGiantDisplayName } from '../../content/giantDisplayNames';
import { GiantMapMarker, mapMarkerStackHeightPx } from './GiantDeliveryUi';
import { DailyPackCompleteModal } from './DailyPackCompleteModal';
import { useMapGiantAnchors } from './useMapGiantAnchors';
import { hideMapRasterGiants } from './applyMapSvgCleanup';
import { mapDisplaySize } from './parseMapGiantAnchors';
import { MAP_SVG_ID_TO_GIANT } from './mapSvgGiantIds';

/** Доля ширины/высоты вьюпорта за одно нажатие (клавиатура / короткий тап). */
const SCROLL_STEP_RATIO = 0.048;
/**
 * Скорость пана при удержании стрелки: доля вьюпорта в секунду по каждой оси
 * (кадры rAF дают плавное движение).
 */
const PAN_SPEED_VIEWPORT_PER_SEC = 0.26;

const mapFrame: CSSProperties = {
  flex: 1,
  position: 'relative',
  minHeight: 0,
  overflow: 'hidden',
  touchAction: 'none',
};

const arrowBtn: CSSProperties = {
  position: 'absolute',
  width: 83,
  height: 83,
  border: 'none',
  padding: 0,
  cursor: 'pointer',
  background: 'transparent',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  zIndex: 2,
};

const arrowImg: CSSProperties = {
  width: 53,
  height: 53,
  objectFit: 'contain',
};

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n));
}

/** Ширина попапа доставки (см. {@link GiantMapMarker}). */
const MARKER_W_PX = 135;
const MARKER_STACK_H_PX = mapMarkerStackHeightPx({ includePortrait: false });

type PanArrow = 'left' | 'right' | 'up' | 'down';

type Rect = { left: number; right: number; top: number; bottom: number };

function markerBoundsPx(p: { x: number; y: number }, mapW: number, mapH: number): Rect {
  const cx = p.x * mapW;
  const cy = p.y * mapH;
  return {
    left: cx - MARKER_W_PX / 2,
    right: cx + MARKER_W_PX / 2,
    top: cy - MARKER_STACK_H_PX,
    bottom: cy,
  };
}

function viewportRect(scroll: { x: number; y: number }, vw: number, vh: number): Rect {
  return {
    left: scroll.x,
    right: scroll.x + vw,
    top: scroll.y,
    bottom: scroll.y + vh,
  };
}

function rectsIntersect(a: Rect, b: Rect): boolean {
  return a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;
}

/**
 * Если маркер не пересекает вьюпорт — направление стрелки пана, куда сдвинуть карту,
 * чтобы приблизить заказ; при диагонали — ось с большим зазором между прямоугольниками.
 */
function primaryPanForOffscreenMarker(v: Rect, m: Rect): PanArrow | null {
  if (rectsIntersect(v, m)) {
    return null;
  }
  let hDir: 'left' | 'right' | null = null;
  let vDir: 'up' | 'down' | null = null;
  let gapX = 0;
  let gapY = 0;
  if (m.right <= v.left) {
    hDir = 'left';
    gapX = v.left - m.right;
  } else if (m.left >= v.right) {
    hDir = 'right';
    gapX = m.left - v.right;
  }
  if (m.bottom <= v.top) {
    vDir = 'up';
    gapY = v.top - m.bottom;
  } else if (m.top >= v.bottom) {
    vDir = 'down';
    gapY = m.top - v.bottom;
  }
  if (hDir != null && vDir != null) {
    return gapX >= gapY ? hDir : vDir;
  }
  if (hDir != null) {
    return hDir;
  }
  if (vDir != null) {
    return vDir;
  }
  const vcx = (v.left + v.right) / 2;
  const vcy = (v.top + v.bottom) / 2;
  const mcx = (m.left + m.right) / 2;
  const mcy = (m.top + m.bottom) / 2;
  const dx = mcx - vcx;
  const dy = mcy - vcy;
  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx < 0 ? 'left' : 'right';
  }
  return dy < 0 ? 'up' : 'down';
}

const offscreenBadgeStyle: CSSProperties = {
  position: 'absolute',
  top: -6,
  right: -4,
  minWidth: 18,
  height: 18,
  padding: '0 4px',
  borderRadius: 999,
  background: '#e02020',
  color: '#fff',
  fontSize: 11,
  fontWeight: 800,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  zIndex: 1,
  boxSizing: 'border-box',
};

export function GameMapScreen() {
  const navigate = useNavigate();
  const refreshEconomy = useAppStore((s) => s.refreshEconomy);
  const acknowledgeDailyPackCompleteModal = useAppStore((s) => s.acknowledgeDailyPackCompleteModal);
  const playerEconomy = useAppStore((s) => s.playerEconomy);
  const syncWarning = useAppStore((s) => s.syncWarning);
  const lastActionError = useAppStore((s) => s.lastActionError);
  const lastActionErrorRatingRequired = useAppStore((s) => s.lastActionErrorRatingRequired);
  const clearActionError = useAppStore((s) => s.clearActionError);
  const dismissSyncWarning = useAppStore((s) => s.dismissSyncWarning);

  useEffect(() => {
    void refreshEconomy();
  }, [refreshEconomy]);
  const viewportRef = useRef<HTMLDivElement | null>(null);
  const mapSvgRef = useRef<SVGSVGElement | null>(null);
  const [mapSvgRoot, setMapSvgRoot] = useState<SVGSVGElement | null>(null);
  const bindMapSvgRef = useCallback((node: SVGSVGElement | null) => {
    mapSvgRef.current = node;
    setMapSvgRoot(node);
  }, []);
  const mapWorldRef = useRef<HTMLDivElement | null>(null);
  const [mapWorldEl, setMapWorldEl] = useState<HTMLDivElement | null>(null);
  const bindMapWorldRef = useCallback((node: HTMLDivElement | null) => {
    mapWorldRef.current = node;
    setMapWorldEl(node);
  }, []);
  const panHoldRafRef = useRef<number | null>(null);
  const panHoldDirRef = useRef<{ dx: number; dy: number } | null>(null);
  const panHoldLastTsRef = useRef<number | null>(null);
  const mapSize = mapDisplaySize();
  const viewportSizeRef = useRef({ w: 0, h: 0 });
  const [viewportSize, setViewportSize] = useState({ w: 0, h: 0 });
  const mapSizeRef = useRef(mapSize);
  const [scroll, setScroll] = useState({ x: 0, y: 0 });
  const giantAnchors = useMapGiantAnchors(mapSvgRoot, mapWorldEl);

  mapSizeRef.current = mapSize;
  viewportSizeRef.current = viewportSize;

  useLayoutEffect(() => {
    const el = viewportRef.current;
    if (el == null) {
      return;
    }

    const apply = (w: number, h: number) => {
      if (w > 0 && h > 0) {
        setViewportSize({ w, h });
      }
    };

    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver((entries) => {
        const cr = entries[0]?.contentRect;
        if (cr == null) {
          return;
        }
        apply(cr.width, cr.height);
      });
      ro.observe(el);
      return () => ro.disconnect();
    }

    const sync = () => {
      const r = el.getBoundingClientRect();
      apply(r.width, r.height);
    };
    sync();
    window.addEventListener('resize', sync);
    return () => window.removeEventListener('resize', sync);
  }, []);

  const maxScroll = useCallback(() => {
    if (viewportSize.w === 0 || viewportSize.h === 0) {
      return { x: 0, y: 0 };
    }
    return {
      x: Math.max(0, mapSize.width - viewportSize.w),
      y: Math.max(0, mapSize.height - viewportSize.h),
    };
  }, [mapSize.height, mapSize.width, viewportSize.h, viewportSize.w]);

  useEffect(() => {
    const m = maxScroll();
    setScroll((s) => {
      const nx = clamp(s.x, 0, m.x);
      const ny = clamp(s.y, 0, m.y);
      if (nx === s.x && ny === s.y) {
        return s;
      }
      return { x: nx, y: ny };
    });
  }, [maxScroll]);

  const panBy = useCallback(
    (dx: number, dy: number) => {
      setScroll((s) => {
        if (viewportSize.w === 0 || viewportSize.h === 0) {
          return s;
        }
        const maxX = Math.max(0, mapSize.width - viewportSize.w);
        const maxY = Math.max(0, mapSize.height - viewportSize.h);
        const stepX = viewportSize.w * SCROLL_STEP_RATIO;
        const stepY = viewportSize.h * SCROLL_STEP_RATIO;
        return {
          x: clamp(s.x + dx * stepX, 0, maxX),
          y: clamp(s.y + dy * stepY, 0, maxY),
        };
      });
    },
    [mapSize.height, mapSize.width, viewportSize.h, viewportSize.w],
  );

  const stopPanHold = useCallback(() => {
    if (panHoldRafRef.current != null) {
      cancelAnimationFrame(panHoldRafRef.current);
      panHoldRafRef.current = null;
    }
    panHoldDirRef.current = null;
    panHoldLastTsRef.current = null;
  }, []);

  const runPanHoldFrame = useCallback(() => {
    const dir = panHoldDirRef.current;
    if (dir == null) {
      return;
    }
    const now = performance.now();
    const last = panHoldLastTsRef.current ?? now;
    panHoldLastTsRef.current = now;
    const dt = Math.min(Math.max(0, (now - last) / 1000), 0.05);

    const map = mapSizeRef.current;
    const vp = viewportSizeRef.current;
    if (vp.w === 0 || vp.h === 0) {
      panHoldRafRef.current = requestAnimationFrame(runPanHoldFrame);
      return;
    }

    const maxX = Math.max(0, map.width - vp.w);
    const maxY = Math.max(0, map.height - vp.h);
    const speedW = PAN_SPEED_VIEWPORT_PER_SEC * vp.w;
    const speedH = PAN_SPEED_VIEWPORT_PER_SEC * vp.h;

    setScroll((s) => ({
      x: clamp(s.x + dir.dx * speedW * dt, 0, maxX),
      y: clamp(s.y + dir.dy * speedH * dt, 0, maxY),
    }));

    panHoldRafRef.current = requestAnimationFrame(runPanHoldFrame);
  }, []);

  const startPanHold = useCallback(
    (dx: number, dy: number) => {
      stopPanHold();
      panHoldDirRef.current = { dx, dy };
      panHoldLastTsRef.current = performance.now();
      panHoldRafRef.current = requestAnimationFrame(runPanHoldFrame);
    },
    [runPanHoldFrame, stopPanHold],
  );

  useEffect(() => {
    return () => {
      stopPanHold();
    };
  }, [stopPanHold]);

  const onPanArrowPointerDown = (e: PointerEvent<HTMLButtonElement>, dx: number, dy: number) => {
    if (e.pointerType === 'mouse' && e.button !== 0) {
      return;
    }
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    startPanHold(dx, dy);
  };

  const onPanArrowKeyDown = (e: KeyboardEvent<HTMLButtonElement>, dx: number, dy: number) => {
    if (e.key !== 'Enter' && e.key !== ' ') {
      return;
    }
    e.preventDefault();
    if (e.repeat) {
      return;
    }
    panBy(dx, dy);
  };

  const onPanArrowPointerEnd = (e: PointerEvent<HTMLButtonElement>) => {
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
    stopPanHold();
  };

  useEffect(() => {
    const activeKeys = new Set<string>();
    const keyToDir = (key: string): { dx: number; dy: number } | null => {
      switch (key.toLowerCase()) {
        case 'w':
        case 'arrowup':
          return { dx: 0, dy: -1 };
        case 's':
        case 'arrowdown':
          return { dx: 0, dy: 1 };
        case 'a':
        case 'arrowleft':
          return { dx: -1, dy: 0 };
        case 'd':
        case 'arrowright':
          return { dx: 1, dy: 0 };
        default:
          return null;
      }
    };

    const recomputeHoldFromKeys = () => {
      let dx = 0;
      let dy = 0;
      activeKeys.forEach((k) => {
        const dir = keyToDir(k);
        if (dir == null) {
          return;
        }
        dx += dir.dx;
        dy += dir.dy;
      });
      dx = clamp(dx, -1, 1);
      dy = clamp(dy, -1, 1);
      if (dx === 0 && dy === 0) {
        stopPanHold();
        return;
      }
      startPanHold(dx, dy);
    };

    const onKeyDown = (e: globalThis.KeyboardEvent) => {
      const dir = keyToDir(e.key);
      if (dir == null) {
        return;
      }
      e.preventDefault();
      if (e.repeat) {
        return;
      }
      activeKeys.add(e.key.toLowerCase());
      panBy(dir.dx, dir.dy);
      recomputeHoldFromKeys();
    };

    const onKeyUp = (e: globalThis.KeyboardEvent) => {
      const dir = keyToDir(e.key);
      if (dir == null) {
        return;
      }
      activeKeys.delete(e.key.toLowerCase());
      recomputeHoldFromKeys();
    };

    const onWindowBlur = () => {
      activeKeys.clear();
      stopPanHold();
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    window.addEventListener('blur', onWindowBlur);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      window.removeEventListener('blur', onWindowBlur);
      activeKeys.clear();
      stopPanHold();
    };
  }, [panBy, startPanHold, stopPanHold]);

  const onViewportPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    viewportRef.current?.focus();
  };

  const worldTransform = {
    width: mapSize.width,
    height: mapSize.height,
    transform: `translate(${-scroll.x}px, ${-scroll.y}px)`,
  } as const;

  const activePoolMarkers = useMemo(() => {
    return playerEconomy.deliveryPool
      .filter((entry) => !isPoolEntryDelivered(entry))
      .map((entry) => {
        const point = resolveMapDeliveryPoint(entry.giantId, giantAnchors);
        return { entry, point };
      });
  }, [giantAnchors, playerEconomy.deliveryPool]);

  const activePoolByGiantId = useMemo(() => {
    const map = new Map<GiantId, (typeof activePoolMarkers)[number]>();
    for (const marker of activePoolMarkers) {
      map.set(marker.point.giantId, marker);
    }
    return map;
  }, [activePoolMarkers]);

  const openDeliveryForGiant = useCallback(
    (giantId: GiantId) => {
      const marker = activePoolByGiantId.get(giantId);
      if (marker == null) {
        return;
      }
      clearActionError();
      navigate(`/game/delivery/${encodeURIComponent(giantId)}`);
    },
    [activePoolByGiantId, clearActionError, navigate],
  );

  useEffect(() => {
    const svg = mapSvgRef.current;
    if (svg == null) {
      return;
    }

    hideMapRasterGiants(svg);

    const giantsGroup = svg.querySelector('#giants');
    if (giantsGroup == null) {
      return;
    }

    for (const child of giantsGroup.children) {
      if (!(child instanceof SVGGraphicsElement)) {
        continue;
      }
      const giantId = MAP_SVG_ID_TO_GIANT[child.id];
      const hasDelivery = giantId != null && activePoolByGiantId.has(giantId);
      child.style.pointerEvents = hasDelivery ? 'all' : 'none';
      child.style.cursor = hasDelivery ? 'pointer' : 'default';
    }

    const onGiantClick = (event: Event) => {
      const target = event.target;
      if (!(target instanceof Element)) {
        return;
      }
      const giantGroup = target.closest<SVGGElement>('#giants > g[id]');
      if (giantGroup == null) {
        return;
      }
      const giantId = MAP_SVG_ID_TO_GIANT[giantGroup.id];
      if (giantId == null || !activePoolByGiantId.has(giantId)) {
        return;
      }
      event.stopPropagation();
      openDeliveryForGiant(giantId);
    };

    giantsGroup.addEventListener('click', onGiantClick);
    return () => giantsGroup.removeEventListener('click', onGiantClick);
  }, [activePoolByGiantId, mapSvgRoot, openDeliveryForGiant]);

  const showDailyPackComplete = shouldShowDailyPackCompleteModal(playerEconomy);

  const offScreenByArrow = useMemo(() => {
    const z = { left: 0, right: 0, up: 0, down: 0 };
    if (viewportSize.w === 0 || viewportSize.h === 0) {
      return z;
    }
    const v = viewportRect(scroll, viewportSize.w, viewportSize.h);
    const acc = { ...z };
    for (const { point } of activePoolMarkers) {
      const m = markerBoundsPx(point, mapSize.width, mapSize.height);
      const dir = primaryPanForOffscreenMarker(v, m);
      if (dir != null) {
        acc[dir] += 1;
      }
    }
    return acc;
  }, [activePoolMarkers, mapSize, scroll, viewportSize]);

  const badge = (dir: PanArrow) => {
    const n = offScreenByArrow[dir];
    if (n <= 0) {
      return null;
    }
    const label = `${t('game.map.offscreenOrdersLabel')}: ${n}`;
    return (
      <span aria-label={label} style={offscreenBadgeStyle}>
        {n > 99 ? '99+' : n}
      </span>
    );
  };

  return (
    <div
      ref={viewportRef}
      style={mapFrame}
      tabIndex={0}
      onPointerDown={onViewportPointerDown}
      onBlur={() => stopPanHold()}
    >
        <GameStatusBanner
          syncWarning={syncWarning}
          actionError={lastActionError}
          actionErrorRatingRequired={lastActionErrorRatingRequired ?? undefined}
          onDismissActionError={clearActionError}
          onDismissSyncWarning={dismissSyncWarning}
        />
        <button
          type="button"
          aria-label={t('game.map.panUp')}
          style={{ ...arrowBtn, top: 52, left: '50%', transform: 'translateX(-50%)' }}
          onPointerDown={(e) => onPanArrowPointerDown(e, 0, -1)}
          onPointerUp={onPanArrowPointerEnd}
          onPointerCancel={onPanArrowPointerEnd}
          onLostPointerCapture={stopPanHold}
          onKeyDown={(e) => onPanArrowKeyDown(e, 0, -1)}
        >
          {badge('up')}
          <img src={lobbyInteractArrow} alt="" style={{ ...arrowImg, transform: 'rotate(-90deg)' }} />
        </button>
        <button
          type="button"
          aria-label={t('game.map.panDown')}
          style={{ ...arrowBtn, bottom: 8, left: '50%', transform: 'translateX(-50%)' }}
          onPointerDown={(e) => onPanArrowPointerDown(e, 0, 1)}
          onPointerUp={onPanArrowPointerEnd}
          onPointerCancel={onPanArrowPointerEnd}
          onLostPointerCapture={stopPanHold}
          onKeyDown={(e) => onPanArrowKeyDown(e, 0, 1)}
        >
          {badge('down')}
          <img src={lobbyInteractArrow} alt="" style={{ ...arrowImg, transform: 'rotate(90deg)' }} />
        </button>
        <button
          type="button"
          aria-label={t('game.map.panLeft')}
          style={{ ...arrowBtn, left: 8, top: '50%', transform: 'translateY(-50%)' }}
          onPointerDown={(e) => onPanArrowPointerDown(e, -1, 0)}
          onPointerUp={onPanArrowPointerEnd}
          onPointerCancel={onPanArrowPointerEnd}
          onLostPointerCapture={stopPanHold}
          onKeyDown={(e) => onPanArrowKeyDown(e, -1, 0)}
        >
          {badge('left')}
          <img src={lobbyInteractArrow} alt="" style={{ ...arrowImg, transform: 'rotate(180deg)' }} />
        </button>
        <button
          type="button"
          aria-label={t('game.map.panRight')}
          style={{ ...arrowBtn, right: 8, top: '50%', transform: 'translateY(-50%)' }}
          onPointerDown={(e) => onPanArrowPointerDown(e, 1, 0)}
          onPointerUp={onPanArrowPointerEnd}
          onPointerCancel={onPanArrowPointerEnd}
          onLostPointerCapture={stopPanHold}
          onKeyDown={(e) => onPanArrowKeyDown(e, 1, 0)}
        >
          {badge('right')}
          <img src={lobbyInteractArrow} alt="" style={arrowImg} />
        </button>

        <div
          style={{
            position: 'absolute',
            inset: 0,
            overflow: 'hidden',
          }}
        >
          <div ref={bindMapWorldRef} style={{ position: 'relative', ...worldTransform }}>
            <MapSvg
              ref={bindMapSvgRef}
              aria-hidden
              style={{ display: 'block', width: mapSize.width, height: mapSize.height }}
            />
            {activePoolMarkers.map(({ entry, point }) => {
              const urgent = entry.urgency === 'urgent';
              const caption = t(
                deliveryGiantMessageI18nKey(
                  deliveryGiantMessageId(entry.urgency, entry.waitingDay),
                ),
              );
              return (
                <div
                  key={entry.deliveryId}
                  style={{
                    position: 'absolute',
                    left: `${point.x * 100}%`,
                    top: `${point.y * 100}%`,
                    transform: 'translate(-50%, -100%)',
                    zIndex: 1,
                  }}
                >
                    <GiantMapMarker
                      giantId={point.giantId}
                      urgent={urgent}
                      important={entry.urgency === 'important'}
                      waitingDay={entry.waitingDay}
                      locked={false}
                      showPortrait={false}
                      caption={caption}
                    onClick={() => openDeliveryForGiant(point.giantId)}
                    ariaLabel={
                      urgent
                        ? `${t('game.map.markerUrgent')}: ${getGiantDisplayName(point.giantId)}`
                        : entry.urgency === 'important'
                          ? `${t('game.map.markerImportant')}: ${getGiantDisplayName(point.giantId)}`
                          : `${t('game.map.markerNormal')}: ${getGiantDisplayName(point.giantId)}`
                    }
                  />
                </div>
              );
            })}
          </div>
        </div>
        {showDailyPackComplete ? (
          <DailyPackCompleteModal
            onClose={() => {
              void acknowledgeDailyPackCompleteModal();
            }}
          />
        ) : null}
    </div>
  );
}
