import type { Obstacle } from 'src/domain/level';
import type { Player } from 'src/domain/player';

export function logObstacleCollision(obstacle: Obstacle, player: Player): void {
  if (process.env.NODE_ENV === 'production') {
    return;
  }

  console.log('[obstacle collision]', {
    obstacleId: obstacle.id,
    playerS: player.worldS,
    playerLane: player.lane,
    obstacleS: obstacle.hitbox.centerS,
    obstacleLane: obstacle.hitbox.centerLane,
  });
}
