import type { GiantId } from '../../domain';

/** Id группы гиганта внутри `#giants` в `map.svg`. */
export const MAP_SVG_GIANT_GROUP_ID: Partial<Record<GiantId, string>> = {
  drakocha: 'drakochi',
  factor: 'factor',
  uncle_willy: 'willy',
  swami: 'swami',
  rose_observatory: 'roza',
  yeti: 'yetti',
  captain_duck: 'captainDuck',
  mona: 'mona',
  serge: 'serj',
};

export const MAP_SVG_ID_TO_GIANT: Record<string, GiantId> = Object.fromEntries(
  Object.entries(MAP_SVG_GIANT_GROUP_ID).map(([giantId, svgId]) => [svgId, giantId as GiantId]),
) as Record<string, GiantId>;
