import type { Obstacle } from 'src/domain/level';
import { STATIC_OBSTACLE_SIZE_SCALE } from 'src/domain/constants';
import { SVG_NAMESPACE, SVG_SELECTOR } from 'src/infrastructure/constants';

export function spawnObstacleAssets(
  obstaclesRoot: ParentNode,
  obstacles: Obstacle[],
  assetUrls: Record<string, string>,
): void {
  const container = obstaclesRoot.querySelector(SVG_SELECTOR.OBSTACLES);
  if (container == null) {
    return;
  }

  for (const obstacle of obstacles) {
    const placeholder = container.querySelector(`#${CSS.escape(obstacle.svgGroupId)}`);
    if (!(placeholder instanceof SVGRectElement)) {
      continue;
    }

    const url = assetUrls[obstacle.assetId];
    if (url == null) {
      console.warn(`[spawnObstacleAssets] missing asset for id "${obstacle.assetId}"`);
      continue;
    }

    const x = Number.parseFloat(placeholder.getAttribute('x') ?? '0');
    const y = Number.parseFloat(placeholder.getAttribute('y') ?? '0');
    const width = Number.parseFloat(placeholder.getAttribute('width') ?? '0');
    const height = Number.parseFloat(placeholder.getAttribute('height') ?? '0');
    const scale = obstacle.assetId === 'static' ? STATIC_OBSTACLE_SIZE_SCALE : 1;
    const drawWidth = width * scale;
    const drawHeight = height * scale;
    const drawX = x + width / 2 - drawWidth / 2;
    const drawY = y + height / 2 - drawHeight / 2;

    const image = document.createElementNS(SVG_NAMESPACE, 'image');
    image.id = obstacle.svgGroupId;
    image.setAttribute('href', url);
    image.setAttribute('x', String(drawX));
    image.setAttribute('y', String(drawY));
    image.setAttribute('width', String(drawWidth));
    image.setAttribute('height', String(drawHeight));

    placeholder.replaceWith(image);
  }
}
