import { useLayoutEffect, useMemo, useRef } from 'react';
import { ReactComponent as LevelScreenSvg } from 'src/infrastructure/assets/screens/level_screen.svg';
import {
  LEVEL_LAYER_Z_INDEX,
  LEVEL_SCREEN_SVG_SELECTOR,
  LEVEL_SCREEN_VIEW_BOX,
} from 'src/presentation/level/constants';
import {
  computeRouteProgress,
  formatCollectibleCount,
  formatFlightTimer,
  formatRouteDistanceMeters,
} from 'src/presentation/level/hud/formatLevelHud';
import { layoutToLayerStyle } from 'src/presentation/shared/layout/layoutToLayerStyle';
import { computeFitLevelCanvasLayout } from 'src/presentation/shared/layout/parseLevelLayout';
import { useViewportSize } from 'src/presentation/shared/hooks/useViewportSize';
import { setSvgLivesVisibility } from 'src/presentation/shared/svg/setSvgLivesVisibility';
import { setSvgProgressBarFill } from 'src/presentation/shared/svg/setSvgProgressBarFill';
import { setSvgTextContent } from 'src/presentation/shared/svg/setSvgTextContent';
import 'src/presentation/level/styles/levelScreenHud.css';

export type LevelScreenHudData = {
  levelName: string;
  elapsedSeconds: number;
  routeEndS: number;
  worldS: number;
  collectiblesCollected: number;
  collectiblesTotal: number;
  lives: number;
};

type LevelScreenOverlayProps = {
  hud: LevelScreenHudData;
  onPauseClick?: () => void;
};

function bindSvgButton(
  host: ParentNode,
  selector: string,
  className: string,
  onClick: () => void,
): (() => void) | undefined {
  const button = host.querySelector(selector);
  if (!(button instanceof SVGElement)) {
    return undefined;
  }

  button.classList.add(className);
  button.style.pointerEvents = 'all';
  button.addEventListener('click', onClick);
  return () => {
    button.removeEventListener('click', onClick);
  };
}

export function LevelScreenOverlay({ hud, onPauseClick }: LevelScreenOverlayProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const viewport = useViewportSize();
  const layout = useMemo(
    () => computeFitLevelCanvasLayout(viewport.width, viewport.height, LEVEL_SCREEN_VIEW_BOX),
    [viewport.width, viewport.height],
  );

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (host == null) {
      return;
    }

    setSvgTextContent(host, LEVEL_SCREEN_SVG_SELECTOR.LEVEL_NAME_TEXT, `\u201c${hud.levelName}\u201d`);
    setSvgTextContent(host, LEVEL_SCREEN_SVG_SELECTOR.TIMER_TEXT, formatFlightTimer(hud.elapsedSeconds));
    setSvgTextContent(
      host,
      LEVEL_SCREEN_SVG_SELECTOR.TOTAL_DISTANCE_TEXT,
      formatRouteDistanceMeters(hud.routeEndS),
    );
    setSvgTextContent(
      host,
      LEVEL_SCREEN_SVG_SELECTOR.COLLECTIBLE_COUNT,
      formatCollectibleCount(hud.collectiblesCollected, hud.collectiblesTotal),
    );
    setSvgProgressBarFill(host, computeRouteProgress(hud.worldS, hud.routeEndS));
    setSvgLivesVisibility(host, hud.lives);
  }, [hud]);

  useLayoutEffect(() => {
    if (onPauseClick == null) {
      return;
    }

    const host = hostRef.current;
    if (host == null) {
      return;
    }

    return bindSvgButton(
      host,
      LEVEL_SCREEN_SVG_SELECTOR.PAUSE_BUTTON,
      'level-scene__pause-button',
      onPauseClick,
    );
  }, [onPauseClick]);

  return (
    <div
      ref={hostRef}
      className="level-scene__hud screen-svg"
      style={{
        ...layoutToLayerStyle(layout),
        zIndex: LEVEL_LAYER_Z_INDEX.HUD,
        pointerEvents: 'none',
        ['--svg-scale' as string]: layout.displayScale,
      }}
      aria-hidden
    >
      <LevelScreenSvg width={layout.canvasWidthPx} height={layout.canvasHeightPx} />
    </div>
  );
}
