import { BOOSTER_DURATION_SECONDS } from '../constants';
import type { BoosterKind } from '../../domain/level';
import type { Player } from '../../domain/player';

export function applyBoosterPickupUseCase(player: Player, kind: BoosterKind): Player {
  return {
    ...player,
    activeBooster: {
      kind,
      remainingSeconds: BOOSTER_DURATION_SECONDS,
    },
  };
}
