import type { CourierId } from 'src/domain/courier';
import { PLAYER_SPRITE_SVG_HEIGHT, PLAYER_SPRITE_SVG_WIDTH } from 'src/domain/constants';
import { getCourierSpriteComponent } from 'src/infrastructure/assets/characters/courierSprites';
import type { VerticalMoveDirection } from 'src/domain/player';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';
import type { LevelCanvasLayout } from 'src/presentation/shared/layout/parseLevelLayout';
import {
  LEVEL_LAYER_Z_INDEX,
  PLAYER_SPRITE_TRANSFORM_TRANSITION,
  PLAYER_TILT_DEGREES,
} from 'src/presentation/level/constants';
import { projectPlayerToScreen } from 'src/presentation/level/layout/projectPlayerPosition';

type PlayerSpriteProps = {
  level: Level;
  player: Player;
  layout: LevelCanvasLayout;
  verticalDirection: VerticalMoveDirection;
  courierId: CourierId;
};

function playerTiltDegrees(verticalDirection: VerticalMoveDirection): number {
  return -verticalDirection * PLAYER_TILT_DEGREES;
}

export function PlayerSprite({
  level,
  player,
  layout,
  verticalDirection,
  courierId,
}: PlayerSpriteProps) {
  const { leftPx, topPx } = projectPlayerToScreen(level, player, layout);
  const widthPx = PLAYER_SPRITE_SVG_WIDTH * layout.displayScale;
  const heightPx = PLAYER_SPRITE_SVG_HEIGHT * layout.displayScale;
  const tiltDeg = playerTiltDegrees(verticalDirection);
  const spriteVariant = player.activeBooster?.kind ?? 'normal';
  const CourierSprite = getCourierSpriteComponent(courierId, spriteVariant);

  return (
    <div
      className="player-sprite"
      style={{
        position: 'absolute',
        left: leftPx,
        top: topPx,
        width: widthPx,
        height: heightPx,
        transform: `translate(-50%, -50%) rotate(${tiltDeg}deg)`,
        transition: PLAYER_SPRITE_TRANSFORM_TRANSITION,
        zIndex: LEVEL_LAYER_Z_INDEX.PLAYER,
        pointerEvents: 'none',
      }}
    >
      <CourierSprite width={widthPx} height={heightPx} style={{ display: 'block' }} />
    </div>
  );
}
