import { DEFAULT_DISPLAY_SCALE } from 'src/presentation/level/constants';

export type WorldProjection = {
  playfieldHeightPx: number;
  courierScreenX: number;
};

export type LevelCanvasLayout = {
  canvasLeftPx: number;
  canvasTopPx: number;
  canvasWidthPx: number;
  canvasHeightPx: number;
  contentOffsetPx: number;
  displayScale: number;
};

export type LevelLayoutMetrics = {
  viewBoxWidth: number;
  viewBoxHeight: number;
  spawnSvgX: number;
};

export function computeSvgLevelDisplayScale(
  playfieldHeightPx: number,
  viewBoxHeight: number,
): number {
  if (viewBoxHeight <= 0 || playfieldHeightPx <= 0) {
    return DEFAULT_DISPLAY_SCALE;
  }
  return playfieldHeightPx / viewBoxHeight;
}

export function computeSvgLevelCanvasLayout(
  proj: WorldProjection,
  metrics: LevelLayoutMetrics,
  playerWorldS: number,
): LevelCanvasLayout {
  const displayScale = computeSvgLevelDisplayScale(proj.playfieldHeightPx, metrics.viewBoxHeight);
  return {
    canvasLeftPx: proj.courierScreenX - playerWorldS * displayScale,
    canvasTopPx: 0,
    canvasWidthPx: metrics.viewBoxWidth * displayScale,
    canvasHeightPx: proj.playfieldHeightPx,
    contentOffsetPx: -metrics.spawnSvgX * displayScale,
    displayScale,
  };
}

/** Вписывает весь viewBox уровня в viewport (object-fit: contain). */
export function computeFitLevelCanvasLayout(
  viewportWidthPx: number,
  viewportHeightPx: number,
  metrics: Pick<LevelLayoutMetrics, 'viewBoxWidth' | 'viewBoxHeight'>,
): LevelCanvasLayout {
  if (metrics.viewBoxWidth <= 0 || metrics.viewBoxHeight <= 0) {
    return {
      canvasLeftPx: 0,
      canvasTopPx: 0,
      canvasWidthPx: viewportWidthPx,
      canvasHeightPx: viewportHeightPx,
      contentOffsetPx: 0,
      displayScale: DEFAULT_DISPLAY_SCALE,
    };
  }

  const displayScale = Math.min(
    viewportWidthPx / metrics.viewBoxWidth,
    viewportHeightPx / metrics.viewBoxHeight,
  );
  const canvasWidthPx = metrics.viewBoxWidth * displayScale;
  const canvasHeightPx = metrics.viewBoxHeight * displayScale;

  return {
    canvasLeftPx: (viewportWidthPx - canvasWidthPx) / 2,
    canvasTopPx: (viewportHeightPx - canvasHeightPx) / 2,
    canvasWidthPx,
    canvasHeightPx,
    contentOffsetPx: 0,
    displayScale,
  };
}
