import type { LevelViewState } from 'src/presentation/level/session/levelViewState';
import { LEVEL_INTERACTIVE_BINDINGS } from './levelInteractiveBindings';

export function applyLevelInteractives(
  interactionsHost: ParentNode,
  viewState: LevelViewState,
): void {
  for (const binding of LEVEL_INTERACTIVE_BINDINGS) {
    const element = interactionsHost.querySelector(binding.selector);
    if (element instanceof SVGElement) {
      binding.apply(element, viewState);
    }
  }
}
