import { useEffect, useLayoutEffect, useRef, type Dispatch, type RefObject, type SetStateAction } from 'react';
import { handleCollectibleCollisionsUseCase } from 'src/application/use-cases/handleCollectibleCollisionsUseCase';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';
import type { LevelViewState } from 'src/presentation/level/session/levelViewState';
import { applyCollectibleVisibility } from './applyCollectibleVisibility';

export function useCollectibleCollisions(
  level: Level | null,
  player: Player | null,
  setLevel: Dispatch<SetStateAction<Level | null>>,
  setViewState: Dispatch<SetStateAction<LevelViewState>>,
  collectiblesHostRef: RefObject<HTMLDivElement | null>,
): void {
  const activeCollisionIdsRef = useRef<Set<string>>(new Set());

  useLayoutEffect(() => {
    const host = collectiblesHostRef.current;
    if (host == null || level == null) {
      return;
    }
    applyCollectibleVisibility(host, level);
  }, [level, collectiblesHostRef]);

  useEffect(() => {
    activeCollisionIdsRef.current = new Set();
  }, [level?.id]);

  useEffect(() => {
    if (level == null || player == null) {
      return;
    }

    const result = handleCollectibleCollisionsUseCase(
      level,
      player,
      activeCollisionIdsRef.current,
    );

    if (result.newlyConsumed.length > 0) {
      setLevel(result.level);
      setViewState((previous) => ({
        ...previous,
        collectiblesCollected: previous.collectiblesCollected + result.newlyConsumed.length,
      }));
    }

    activeCollisionIdsRef.current = result.nextActiveCollisionIds;
  }, [level, player, setLevel, setViewState]);
}
