import { aabbFromCenter, aabbIntersects } from './collision';
import type { Collectible, Level, ObstacleHitbox } from './level';
import type { Player } from './player';
import { computePlayerHitbox } from './playerHitbox';

function hitboxToAabb(hitbox: ObstacleHitbox) {
  return aabbFromCenter(
    hitbox.centerS,
    hitbox.centerLane,
    hitbox.widthS,
    hitbox.heightLane,
  );
}

export function detectCollectibleCollisions(level: Level, player: Player): Collectible[] {
  const playerBox = hitboxToAabb(computePlayerHitbox(level, player));
  const colliding: Collectible[] = [];

  for (const collectible of level.collectibles) {
    if (collectible.consumed) {
      continue;
    }
    if (aabbIntersects(playerBox, hitboxToAabb(collectible.hitbox))) {
      colliding.push(collectible);
    }
  }

  return colliding;
}
