import { useEffect, useRef, type Dispatch, type SetStateAction } from 'react';
import { tickLevelUseCase } from 'src/application/use-cases/tickLevelUseCase';
import { hasPlayerReachedFinish } from 'src/domain/levelRules';
import type { VerticalMoveDirection } from 'src/domain/player';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';

import { MAX_DELTA_SECONDS } from 'src/presentation/level/constants';

export function useLevelTick(
  level: Level | null,
  player: Player | null,
  setPlayer: Dispatch<SetStateAction<Player | null>>,
  getVerticalDirection: () => VerticalMoveDirection,
  onFrame?: (deltaSeconds: number) => void,
  isPaused = false,
): void {
  const playerRef = useRef(player);
  playerRef.current = player;
  const onFrameRef = useRef(onFrame);
  onFrameRef.current = onFrame;
  const isPausedRef = useRef(isPaused);
  isPausedRef.current = isPaused;

  useEffect(() => {
    if (level == null) {
      return;
    }

    let frameId = 0;
    let lastTimestamp = performance.now();

    const tick = (timestamp: number): void => {
      if (isPausedRef.current) {
        lastTimestamp = timestamp;
        frameId = requestAnimationFrame(tick);
        return;
      }

      const current = playerRef.current;
      if (current != null && (hasPlayerReachedFinish(level, current) || current.lives <= 0)) {
        return;
      }

      const deltaSeconds = Math.min((timestamp - lastTimestamp) / 1000, MAX_DELTA_SECONDS);
      lastTimestamp = timestamp;

      const verticalDirection = getVerticalDirection();

      onFrameRef.current?.(deltaSeconds);

      setPlayer((state) => {
        if (state == null) {
          return state;
        }
        if (hasPlayerReachedFinish(level, state) || state.lives <= 0) {
          return state;
        }

        const next = tickLevelUseCase(level, state, verticalDirection, deltaSeconds);
        playerRef.current = next;
        return next;
      });

      frameId = requestAnimationFrame(tick);
    };

    frameId = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frameId);
    };
  }, [level, setPlayer, getVerticalDirection]);
}
