import type { Booster, BoosterKind } from 'src/domain/level';
import {
  SHIELD_BOOSTER_SPRITE_SVG_HEIGHT,
  SHIELD_BOOSTER_SPRITE_SVG_WIDTH,
  SPEED_BOOSTER_SPRITE_SVG_HEIGHT,
  SPEED_BOOSTER_SPRITE_SVG_WIDTH,
} from 'src/domain/constants';
import { SVG_NAMESPACE, SVG_SELECTOR } from 'src/infrastructure/constants';
import {
  layerSpriteScale,
  parseSvgViewBox,
  type SvgViewBoxSize,
} from 'src/infrastructure/svgViewBox';

function boosterSpriteSize(kind: BoosterKind): { width: number; height: number } {
  if (kind === 'shield') {
    return {
      width: SHIELD_BOOSTER_SPRITE_SVG_WIDTH,
      height: SHIELD_BOOSTER_SPRITE_SVG_HEIGHT,
    };
  }
  return {
    width: SPEED_BOOSTER_SPRITE_SVG_WIDTH,
    height: SPEED_BOOSTER_SPRITE_SVG_HEIGHT,
  };
}

export function spawnBoosterAssets(
  boostersRoot: ParentNode,
  boosters: Booster[],
  assetUrls: Record<string, string>,
  levelViewBox: SvgViewBoxSize,
): void {
  const container = boostersRoot.querySelector(SVG_SELECTOR.BOOSTERS);
  if (container == null) {
    return;
  }

  const scale =
    boostersRoot instanceof SVGSVGElement
      ? layerSpriteScale(parseSvgViewBox(boostersRoot), levelViewBox)
      : { scaleX: 1, scaleY: 1 };

  for (const booster of boosters) {
    const placeholder = container.querySelector(`#${CSS.escape(booster.svgGroupId)}`);
    if (!(placeholder instanceof SVGRectElement)) {
      continue;
    }

    const url = assetUrls[booster.assetId];
    if (url == null) {
      console.warn(`[spawnBoosterAssets] missing asset for id "${booster.assetId}"`);
      continue;
    }

    const markerX = Number.parseFloat(placeholder.getAttribute('x') ?? '0');
    const markerY = Number.parseFloat(placeholder.getAttribute('y') ?? '0');
    const markerWidth = Number.parseFloat(placeholder.getAttribute('width') ?? '0');
    const markerHeight = Number.parseFloat(placeholder.getAttribute('height') ?? '0');
    const centerX = markerX + markerWidth / 2;
    const centerY = markerY + markerHeight / 2;
    const sprite = boosterSpriteSize(booster.assetId);
    const spriteWidth = sprite.width * scale.scaleX;
    const spriteHeight = sprite.height * scale.scaleY;

    const image = document.createElementNS(SVG_NAMESPACE, 'image');
    image.id = booster.svgGroupId;
    image.setAttribute('href', url);
    image.setAttribute('x', String(centerX - spriteWidth / 2));
    image.setAttribute('y', String(centerY - spriteHeight / 2));
    image.setAttribute('width', String(spriteWidth));
    image.setAttribute('height', String(spriteHeight));
    image.setAttribute('preserveAspectRatio', 'xMidYMid meet');

    placeholder.replaceWith(image);
  }
}
