import { COURIER_SCREEN_X_RATIO } from '../constants';
import type { LevelViewState } from '../session/levelViewState';

export type PlayfieldConfig = {
  widthPx: number;
  heightPx: number;
  courierScreenX: number;
};

export function createPlayfieldConfig(widthPx: number, heightPx: number): PlayfieldConfig {
  return {
    widthPx,
    heightPx,
    courierScreenX: widthPx * COURIER_SCREEN_X_RATIO,
  };
}

export type { LevelViewState };
