import { PLAYER_SPRITE_SVG_HEIGHT, PLAYER_SPRITE_SVG_WIDTH } from './constants';
import type { Level, ObstacleHitbox } from './level';
import type { Player } from './player';

export function computePlayerHitbox(level: Level, player: Player): ObstacleHitbox {
  return {
    centerS: player.worldS,
    centerLane: player.lane,
    widthS: PLAYER_SPRITE_SVG_WIDTH,
    heightLane: PLAYER_SPRITE_SVG_HEIGHT / level.viewBox.height,
  };
}
