import { SVG_SELECTOR } from 'src/infrastructure/constants';
import { hideSvgEditorLayer } from 'src/presentation/level/parsing/svgDomUtils';
import type { Level } from 'src/domain/level';

export function applyCollectibleVisibility(collectiblesHost: ParentNode, level: Level): void {
  const container = collectiblesHost.querySelector(SVG_SELECTOR.ROUTE_COLLECTIBLE);
  if (container == null) {
    return;
  }

  for (const collectible of level.collectibles) {
    if (!collectible.consumed) {
      continue;
    }

    const element = container.querySelector(`#${CSS.escape(collectible.svgGroupId)}`);
    if (element instanceof SVGGraphicsElement) {
      hideSvgEditorLayer(element);
    }
  }
}
