import { useCallback, useMemo, useState, type CSSProperties } from 'react';
import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { isGiantId, validateMissionRef, type MissionRef } from '../../domain';
import { LevelView } from 'src/presentation/level/components/LevelView';
import { useAppStore } from '../store/appStore';
import { getV2LevelIdForMission } from '../../v2Bridge/giantIdToV2LevelId';
import { v2App } from '../../v2Bridge/v2AppContext';

const rootStyle: CSSProperties = {
  height: '100dvh',
  maxHeight: '100dvh',
  overflow: 'hidden',
  position: 'relative',
  background: '#1a0a2e',
};

function missionFromLocationState(state: unknown): MissionRef | null {
  if (state == null || typeof state !== 'object') {
    return null;
  }
  const raw = (state as { mission?: unknown }).mission;
  if (raw == null || typeof raw !== 'object') {
    return null;
  }
  const rec = raw as { giantId?: unknown; orderIndex?: unknown };
  if (typeof rec.giantId !== 'string' || typeof rec.orderIndex !== 'number') {
    return null;
  }
  if (!isGiantId(rec.giantId) || !Number.isInteger(rec.orderIndex)) {
    return null;
  }
  const mission: MissionRef = { giantId: rec.giantId, orderIndex: rec.orderIndex };
  return validateMissionRef(mission).ok ? mission : null;
}

/**
 * Demo bridge: mounts v2 LevelView on `/play` without changing v1 game logic
 * or v2/new_src sources. Economy/settle are intentionally skipped.
 */
export function V2GameplayScreen() {
  const courierId = useAppStore((s) => s.selectedCourierId);
  const location = useLocation();
  const navigate = useNavigate();
  const [sessionKey, setSessionKey] = useState(0);

  const mission = useMemo(() => missionFromLocationState(location.state), [location.state]);
  const levelId = useMemo(() => {
    const activeMission = mission ?? { giantId: 'swami' as const, orderIndex: 0 };
    return getV2LevelIdForMission(activeMission);
  }, [mission]);

  const goMap = useCallback(() => {
    navigate('/game/map');
  }, [navigate]);

  const restart = useCallback(() => {
    setSessionKey((k) => k + 1);
  }, []);

  if (courierId == null) {
    return <Navigate to="/courier" replace />;
  }

  return (
    <div style={rootStyle}>
      <LevelView
        key={sessionKey}
        levelId={levelId}
        app={v2App}
        courierId={courierId}
        onFinish={goMap}
        onGameOver={restart}
        onQuit={goMap}
      />
    </div>
  );
}
