export type SvgViewBoxSize = {
  width: number;
  height: number;
};

export type LayerSpriteScale = {
  scaleX: number;
  scaleY: number;
};

export function parseSvgViewBox(svg: SVGSVGElement): SvgViewBoxSize {
  const raw = svg.getAttribute('viewBox');
  if (raw != null) {
    const parts = raw.trim().split(/[\s,]+/).map(Number);
    if (parts.length === 4 && parts.every((n) => Number.isFinite(n))) {
      return { width: parts[2], height: parts[3] };
    }
  }
  const width = Number.parseFloat(svg.getAttribute('width') ?? '0');
  const height = Number.parseFloat(svg.getAttribute('height') ?? '0');
  if (width > 0 && height > 0) {
    return { width, height };
  }
  throw new Error('parseSvgViewBox: SVG viewBox or width/height required');
}

/**
 * Scale from level (interactions) coordinates into a layer's SVG user units.
 * Sprite constants are authored for the level viewBox; multiply by this when drawing
 * into a layer whose viewBox differs (e.g. Mona boosters at ~4.5×).
 */
export function layerSpriteScale(
  layerViewBox: SvgViewBoxSize,
  levelViewBox: SvgViewBoxSize,
): LayerSpriteScale {
  if (levelViewBox.width <= 0 || levelViewBox.height <= 0) {
    throw new Error('layerSpriteScale: level viewBox must be positive');
  }
  if (layerViewBox.width <= 0 || layerViewBox.height <= 0) {
    throw new Error('layerSpriteScale: layer viewBox must be positive');
  }
  return {
    scaleX: layerViewBox.width / levelViewBox.width,
    scaleY: layerViewBox.height / levelViewBox.height,
  };
}

/** Map a point from layer SVG units into level (interactions) units. */
export function layerPointToLevel(
  x: number,
  y: number,
  scale: LayerSpriteScale,
): { x: number; y: number } {
  return {
    x: x / scale.scaleX,
    y: y / scale.scaleY,
  };
}
