import { MAX_PLAYER_LIVES } from '../../domain/constants';
import type { Level } from '../../domain/level';
import type { Player } from '../../domain/player';

export type LevelSession = {
  level: Level;
  player: Player;
};

export function createSpawnPlayer(level: Level): Player {
  return {
    worldS: level.spawnSvgX - level.startPointSvgX,
    lane: level.startLane,
    lives: MAX_PLAYER_LIVES,
    activeBooster: null,
  };
}

export function startLevelUseCase(level: Level): LevelSession {
  return {
    level,
    player: createSpawnPlayer(level),
  };
}
