import type { Level } from 'src/domain/level';
import { LANE_MAX } from 'src/domain/constants';
import type { Player } from 'src/domain/player';
import type { LevelCanvasLayout } from 'src/presentation/shared/layout/parseLevelLayout';

export type PlayerScreenPosition = {
  leftPx: number;
  topPx: number;
};

function computePlayerWorldPosition(level: Level, player: Player): { svgX: number; svgY: number } {
  return {
    svgX: level.startPointSvgX + player.worldS,
    svgY: (LANE_MAX - player.lane) * level.viewBox.height,
  };
}

export function projectSvgToScreen(
  svgX: number,
  svgY: number,
  layout: LevelCanvasLayout,
): PlayerScreenPosition {
  return {
    leftPx: layout.canvasLeftPx + svgX * layout.displayScale + layout.contentOffsetPx,
    topPx: layout.canvasTopPx + svgY * layout.displayScale,
  };
}

export function projectPlayerToScreen(
  level: Level,
  player: Player,
  layout: LevelCanvasLayout,
): PlayerScreenPosition {
  const { svgX, svgY } = computePlayerWorldPosition(level, player);
  return projectSvgToScreen(svgX, svgY, layout);
}
