import { useLayoutEffect, useMemo, useRef } from 'react';
import { ReactComponent as PauseScreenSvg } from 'src/infrastructure/assets/screens/pause_screen.svg';
import {
  PAUSE_SCREEN_VIEW_BOX,
  PAUSE_SVG_SELECTOR,
} from 'src/presentation/screen/constants';
import { layoutToLayerStyle } from 'src/presentation/shared/layout/layoutToLayerStyle';
import { computeFitLevelCanvasLayout } from 'src/presentation/shared/layout/parseLevelLayout';
import { useViewportSize } from 'src/presentation/shared/hooks/useViewportSize';
import 'src/presentation/screen/styles/pauseScreen.css';

type PauseScreenProps = {
  onContinue: () => void;
  onRestart: () => void;
  onQuit: () => void;
};

function bindSvgButton(
  host: ParentNode,
  selector: string,
  className: string,
  onClick: () => void,
): (() => void) | undefined {
  const button = host.querySelector(selector);
  if (!(button instanceof SVGElement)) {
    return undefined;
  }

  button.classList.add(className);
  button.style.pointerEvents = 'all';
  button.addEventListener('click', onClick);
  return () => {
    button.removeEventListener('click', onClick);
  };
}

export function PauseScreen({ onContinue, onRestart, onQuit }: PauseScreenProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const viewport = useViewportSize();
  const layout = useMemo(
    () => computeFitLevelCanvasLayout(viewport.width, viewport.height, PAUSE_SCREEN_VIEW_BOX),
    [viewport.width, viewport.height],
  );

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (host == null) {
      return;
    }

    const unbindContinue = bindSvgButton(
      host,
      PAUSE_SVG_SELECTOR.CONTINUE_BUTTON,
      'pause-screen__button',
      onContinue,
    );
    const unbindRestart = bindSvgButton(
      host,
      PAUSE_SVG_SELECTOR.RESTART_BUTTON,
      'pause-screen__button',
      onRestart,
    );
    const unbindQuit = bindSvgButton(
      host,
      PAUSE_SVG_SELECTOR.QUIT_BUTTON,
      'pause-screen__button',
      onQuit,
    );

    return () => {
      unbindContinue?.();
      unbindRestart?.();
      unbindQuit?.();
    };
  }, [onContinue, onQuit, onRestart]);

  return (
    <div className="pause-screen">
      <div
        ref={hostRef}
        className="pause-screen__canvas screen-svg"
        style={layoutToLayerStyle(layout)}
      >
        <PauseScreenSvg width={layout.canvasWidthPx} height={layout.canvasHeightPx} />
      </div>
    </div>
  );
}
