import type { CSSProperties } from 'react';
import screenBackground1 from '../../infrastructure/assets/Images/ui/screens/base_background_1.svg';
import screenBackground2 from '../../infrastructure/assets/Images/ui/screens/base_background_2.svg';
import openDeliveryScreen from '../../infrastructure/assets/Images/ui/screens/open_delivery_screen.svg';

export const SCREEN_BACKGROUND_1 = screenBackground1;
export const SCREEN_BACKGROUND_2 = screenBackground2;
export const OPEN_DELIVERY_SCREEN = openDeliveryScreen;

/** Два варианта фона экранов — распределены по разделам для визуального разнообразия. */
export const SCREEN_BACKGROUNDS = {
  start: SCREEN_BACKGROUND_1,
  characterSelect: SCREEN_BACKGROUND_2,
  quiz: SCREEN_BACKGROUND_2,
  dailyLogin: SCREEN_BACKGROUND_1,
  deliveries: SCREEN_BACKGROUND_2,
  rewards: SCREEN_BACKGROUND_1,
  rating: SCREEN_BACKGROUND_2,
  license: SCREEN_BACKGROUND_1,
  flightTicket: SCREEN_BACKGROUND_2,
  profile: SCREEN_BACKGROUND_1,
  deliveryResult: SCREEN_BACKGROUND_2,
} as const;

export function screenBackgroundCover(src: string, position: CSSProperties['backgroundPosition'] = 'center'): CSSProperties {
  return {
    backgroundImage: `url(${src})`,
    backgroundSize: 'cover',
    backgroundPosition: position,
    backgroundRepeat: 'no-repeat',
  };
}
