import { useEffect, useLayoutEffect, useRef, type Dispatch, type RefObject, type SetStateAction } from 'react';
import { applyBoosterPickupUseCase } from 'src/application/use-cases/applyBoosterPickupUseCase';
import { handleBoosterCollisionsUseCase } from 'src/application/use-cases/handleBoosterCollisionsUseCase';
import type { Level } from 'src/domain/level';
import type { Player } from 'src/domain/player';
import { applyBoosterVisibility } from './applyBoosterVisibility';

export function useBoosterCollisions(
  level: Level | null,
  player: Player | null,
  setLevel: Dispatch<SetStateAction<Level | null>>,
  setPlayer: Dispatch<SetStateAction<Player | null>>,
  boostersHostRef: RefObject<HTMLDivElement | null>,
): void {
  const activeCollisionIdsRef = useRef<Set<string>>(new Set());

  useLayoutEffect(() => {
    const host = boostersHostRef.current;
    if (host == null || level == null) {
      return;
    }
    applyBoosterVisibility(host, level);
  }, [level, boostersHostRef]);

  useEffect(() => {
    activeCollisionIdsRef.current = new Set();
  }, [level?.id]);

  useEffect(() => {
    if (level == null || player == null) {
      return;
    }

    const result = handleBoosterCollisionsUseCase(
      level,
      player,
      activeCollisionIdsRef.current,
    );

    if (result.newlyConsumed.length > 0) {
      setLevel(result.level);
      setPlayer((previous) => {
        if (previous == null) {
          return previous;
        }
        let next = previous;
        for (const booster of result.newlyConsumed) {
          next = applyBoosterPickupUseCase(next, booster.assetId);
        }
        return next;
      });
    }

    activeCollisionIdsRef.current = result.nextActiveCollisionIds;
  }, [level, player, setLevel, setPlayer]);
}
