import { aabbFromCenter, aabbIntersects } from './collision';
import type { Level, Obstacle, ObstacleHitbox } from './level';
import type { Player } from './player';
import { computePlayerHitbox } from './playerHitbox';

function hitboxToAabb(hitbox: ObstacleHitbox) {
  return aabbFromCenter(
    hitbox.centerS,
    hitbox.centerLane,
    hitbox.widthS,
    hitbox.heightLane,
  );
}

export function detectObstacleCollisions(level: Level, player: Player): Obstacle[] {
  const playerBox = hitboxToAabb(computePlayerHitbox(level, player));
  const colliding: Obstacle[] = [];

  for (const obstacle of level.obstacles) {
    if (obstacle.consumed) {
      continue;
    }
    if (aabbIntersects(playerBox, hitboxToAabb(obstacle.hitbox))) {
      colliding.push(obstacle);
    }
  }

  return colliding;
}
