import { detectObstacleCollisions } from '../../domain/obstacleCollision';
import type { Level, Obstacle } from '../../domain/level';
import type { Player } from '../../domain/player';
import { consumeObstacleUseCase } from './consumeObstacleUseCase';

export type ObstacleCollisionsResult = {
  level: Level;
  nextActiveCollisionIds: Set<string>;
  newlyConsumed: Obstacle[];
};

export function handleObstacleCollisionsUseCase(
  level: Level,
  player: Player,
  activeCollisionIds: ReadonlySet<string>,
): ObstacleCollisionsResult {
  const colliding = detectObstacleCollisions(level, player);
  const nextActiveCollisionIds = new Set(colliding.map((obstacle) => obstacle.id));

  let updatedLevel = level;
  const newlyConsumed: Obstacle[] = [];

  for (const obstacle of colliding) {
    if (!activeCollisionIds.has(obstacle.id)) {
      updatedLevel = consumeObstacleUseCase(updatedLevel, obstacle.id);
      newlyConsumed.push(obstacle);
    }
  }

  return {
    level: updatedLevel,
    nextActiveCollisionIds,
    newlyConsumed,
  };
}
