import type { PlayerEconomyState } from '../../domain';
import {
  fetchAllTimeLeaderboardFromBackend,
  fetchSeasonLeaderboardFromBackend,
} from '../../infrastructure';
import { buildLeaderboards, type LeaderboardsBundle } from './gameExtras';

export async function fetchLeaderboardsFromBackend(
  state: PlayerEconomyState,
  nowMs = Date.now(),
): Promise<LeaderboardsBundle | null> {
  const local = buildLeaderboards(state, nowMs);
  const [seasonRemote, allTimeRemote] = await Promise.all([
    fetchSeasonLeaderboardFromBackend(local.seasonId),
    fetchAllTimeLeaderboardFromBackend(),
  ]);
  if (seasonRemote == null && allTimeRemote == null) {
    return null;
  }
  return {
    seasonId: seasonRemote?.seasonId ?? local.seasonId,
    seasonTitle: seasonRemote?.seasonTitle ?? local.seasonTitle,
    seasonEndsAtIso: seasonRemote?.seasonEndsAtIso ?? local.seasonEndsAtIso,
    weekly: seasonRemote?.entries ?? local.weekly,
    allTime: allTimeRemote?.entries ?? local.allTime,
  };
}
