import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import type { CSSProperties } from 'react';
import { getGiantOrder } from '../../content';
import {
  isDeliveryHistorySuccess,
  listDeliveryHistorySorted,
  missionFromDeliveryId,
  type DeliveryHistoryEntry,
} from '../../domain';
import { t } from '../../i18n';
import { SCREEN_BACKGROUNDS } from './screenBackgroundAssets';
import commonHeaderBackground from '../../infrastructure/assets/Images/commonHeaderBackground.png';
import lobbyInteractArrow from '../../infrastructure/assets/Images/lobbyInteractArrow.png';
import rewardsIcon from '../../infrastructure/assets/Images/rewardsIcon.png';
import { GIANT_PORTRAIT_BY_ID } from './giantPortraits';
import { DeliveryResultModal } from './DeliveryResultModal';
import {
  HeaderHintBackdrop,
  HeaderHintPopup,
  HeaderHintTitleButton,
  headerHintAnchor,
  headerHintTitleButton,
  useHeaderHintPopup,
} from './HeaderHintPopup';
import { useAppStore } from '../store/appStore';

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  textAlign: 'center',
  color: '#111',
  position: 'relative',
  backgroundImage: `url(${SCREEN_BACKGROUNDS.deliveries})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const headerStrip: CSSProperties = {
  width: '100%',
  flexShrink: 0,
  marginTop: 3,
  paddingTop: 'max(8px, env(safe-area-inset-top))',
  backgroundImage: `url(${commonHeaderBackground})`,
  backgroundRepeat: 'no-repeat',
  backgroundSize: '100% 100%',
  backgroundPosition: 'center top',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  minHeight: 52,
  paddingBottom: 12,
  paddingLeft: 16,
  paddingRight: 16,
  boxSizing: 'border-box',
  ...headerHintAnchor,
};

const titleOnHeader: CSSProperties = {
  ...headerHintTitleButton,
  fontSize: 22,
  fontWeight: 900,
  color: '#3a145c',
  textShadow: '0 1px 0 rgba(255,255,255,0.6)',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  padding: '10px 12px 8px',
  boxSizing: 'border-box',
};

const list: CSSProperties = {
  flex: 1,
  minHeight: 0,
  overflowY: 'auto',
  paddingBottom: 8,
  display: 'flex',
  flexDirection: 'column',
  gap: 12,
  alignItems: 'center',
};

const card: CSSProperties = {
  width: '100%',
  maxWidth: 420,
  boxSizing: 'border-box',
  borderRadius: 14,
  border: '2px solid #111',
  background: '#fff',
  display: 'grid',
  gridTemplateColumns: '1fr 1fr auto',
  gridTemplateRows: 'auto auto',
  overflow: 'hidden',
};

const cardCol: CSSProperties = {
  padding: '10px 12px 8px',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  gap: 6,
  minWidth: 0,
};

const colLabel: CSSProperties = {
  fontSize: 12,
  fontWeight: 800,
  color: '#333',
};

const giantImg: CSSProperties = {
  width: 64,
  height: 64,
  objectFit: 'contain',
};

const packageContent: CSSProperties = {
  minHeight: 64,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: 13,
  fontWeight: 700,
  textAlign: 'center',
  lineHeight: 1.2,
  padding: '0 4px',
};

const questionMark: CSSProperties = {
  fontSize: 36,
  fontWeight: 900,
  lineHeight: 1,
};

const statusBar: CSSProperties = {
  gridColumn: '1 / 3',
  padding: '8px 12px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 6,
  fontSize: 14,
  fontWeight: 800,
};

const statusSuccess: CSSProperties = {
  ...statusBar,
  background: '#f5d547',
  color: '#111',
};

const statusFail: CSSProperties = {
  ...statusBar,
  background: '#f0f0f0',
  color: '#111',
};

const actionCol: CSSProperties = {
  gridRow: '1 / 3',
  gridColumn: '3',
  display: 'flex',
  alignItems: 'stretch',
  borderLeft: '2px solid #111',
};

const actionBtn: CSSProperties = {
  width: 44,
  border: 'none',
  padding: 0,
  cursor: 'pointer',
  background: '#f5d547',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
};

function historyOutcome(entry: DeliveryHistoryEntry): 'completed' | 'failed_minigame' {
  return isDeliveryHistorySuccess(entry) ? 'completed' : 'failed_minigame';
}

export function GameDeliveriesScreen() {
  const navigate = useNavigate();
  const playerEconomy = useAppStore((s) => s.playerEconomy);
  const ensureAndBeginDelivery = useAppStore((s) => s.ensureAndBeginDelivery);
  const [selectedEntry, setSelectedEntry] = useState<DeliveryHistoryEntry | null>(null);
  const { hintOpen, toggleHint, closeHint } = useHeaderHintPopup();

  const deliveries = useMemo(
    () => listDeliveryHistorySorted(playerEconomy),
    [playerEconomy],
  );

  const scrollHint = () => {
    const el = document.getElementById('game-deliveries-list');
    el?.scrollBy({ top: 120, behavior: 'smooth' });
  };

  const selectedMission =
    selectedEntry != null ? missionFromDeliveryId(selectedEntry.deliveryId) : null;

  return (
    <div style={root}>
      {hintOpen ? <HeaderHintBackdrop onClose={closeHint} /> : null}
      <header style={headerStrip}>
        <HeaderHintTitleButton
          hintOpen={hintOpen}
          hintId="game-deliveries-hint"
          onClick={toggleHint}
          style={titleOnHeader}
        >
          {t('game.deliveries.title')}
        </HeaderHintTitleButton>
        {hintOpen ? (
          <HeaderHintPopup
            hintId="game-deliveries-hint"
            hintTitle={t('game.deliveries.hintTitle')}
            hintBody={t('game.deliveries.hintBody')}
            onClose={closeHint}
          />
        ) : null}
      </header>
      <div style={body}>
        <div id="game-deliveries-list" style={list}>
          {deliveries.length === 0 ? (
            <p style={{ margin: 0, fontSize: 14, color: '#333' }}>{t('game.deliveries.empty')}</p>
          ) : (
            deliveries.map((entry) => {
              const success = isDeliveryHistorySuccess(entry);
              const mission = missionFromDeliveryId(entry.deliveryId);
              const orderItem =
                mission != null ? getGiantOrder(mission).item : null;

              return (
                <div key={entry.deliveryId} style={card}>
                  <div style={cardCol}>
                    <span style={colLabel}>{t('game.deliveries.toWhom')}</span>
                    <img
                      src={GIANT_PORTRAIT_BY_ID[entry.giantId]}
                      alt=""
                      style={giantImg}
                    />
                  </div>
                  <div style={cardCol}>
                    <span style={colLabel}>{t('game.deliveries.whatInside')}</span>
                    <div style={packageContent}>
                      {success ? (
                        <span>{orderItem}</span>
                      ) : (
                        <span style={questionMark} aria-label={t('game.deliveries.unknownPackage')}>
                          ?
                        </span>
                      )}
                    </div>
                  </div>
                  <div style={actionCol}>
                    <button
                      type="button"
                      style={actionBtn}
                      aria-label={t('game.deliveries.openResult')}
                      onClick={() => setSelectedEntry(entry)}
                    >
                      <img
                        src={lobbyInteractArrow}
                        alt=""
                        width={24}
                        height={24}
                        style={{ objectFit: 'contain' }}
                      />
                    </button>
                  </div>
                  <div style={success ? statusSuccess : statusFail}>
                    {success ? (
                      <>
                        {t('game.deliveries.orderRating')}{' '}
                        {entry.bestRating.toFixed(1).replace('.', ',')} {t('game.deliveries.outOf5')}
                        <img
                          src={rewardsIcon}
                          alt=""
                          width={18}
                          height={18}
                          style={{ objectFit: 'contain' }}
                        />
                      </>
                    ) : (
                      t('game.deliveries.failed')
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
        {deliveries.length > 0 ? (
          <div style={{ display: 'flex', justifyContent: 'center', paddingBottom: 4 }}>
            <button
              type="button"
              onClick={scrollHint}
              aria-label={t('game.tasks.scrollDown')}
              style={{
                border: 'none',
                background: 'transparent',
                cursor: 'pointer',
                padding: 4,
              }}
            >
              <img
                src={lobbyInteractArrow}
                alt=""
                width={32}
                height={32}
                style={{ transform: 'rotate(90deg)' }}
              />
            </button>
          </div>
        ) : null}
      </div>

      {selectedEntry != null && selectedMission != null ? (
        <DeliveryResultModal
          mission={selectedMission}
          outcome={historyOutcome(selectedEntry)}
          rating={
            selectedEntry.lastRating ??
            (selectedEntry.bestRating > 0
              ? {
                  timeScore: 0,
                  sparkScore: 0,
                  skillScore: 0,
                  totalScore: selectedEntry.bestRating,
                  isPerfect: selectedEntry.bestRating >= 5,
                }
              : null)
          }
          sparksCollected={selectedEntry.lastSparksCollected}
          sparksTotal={selectedEntry.lastSparksTotal}
          onRetry={() => {
            void (async () => {
              const begin = await ensureAndBeginDelivery(selectedMission);
              if (!begin.ok) {
                return;
              }
              setSelectedEntry(null);
              navigate(`/game/character/${selectedMission.giantId}/${selectedMission.orderIndex}`);
            })();
          }}
          onToHub={() => setSelectedEntry(null)}
        />
      ) : null}
    </div>
  );
}
